window.__SUM[1]={"LR002063":{"pair":"A2M -> HSPA5","headline":"Purified GRP78 binds activated alpha2-macroglobulin with a reported Kd of about 150 pM, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Purified Grp 78 binds alpha(2)M* with high affinity; a monoclonal antibody against Grp 78 abolished alpha(2)M*-induced signal transduction [PMID:12194978]. Direction and agonist/antagonist role: not reported beyond this.","molecular_requirements":"The binding is to the receptor-recognized activated form alpha(2)M*, not native A2M [PMID:12194978]. LRP co-precipitated with the Grp 78 antibody and was not necessary for the signalling by RNA interference (abstract truncated) [PMID:12194978].","affinity_potency":[{"value":"Kd approximately 150 pM","assay":"equilibrium binding, purified Grp 78 to alpha(2)M*","system":"purified protein; Grp 78 from 1-LN human prostate cancer cells","cite":"PMID:12194978"}],"species_and_systems":"Binding partners purified from human 1-LN prostate cancer cells and murine macrophages; mouse pair is ortholog-inferred [PMID:12194978].","localisation_and_range":"Grp 78 is shown on the cell surface of 1-LN cells by flow cytometry; A2M is flagged secreted [PMID:12194978] [flag].","caveats":"One paper, abstract only. A BioGRID record cites the same paper (Reconstituted Complex) [DB:BioGRID]. Two other judged rows were abstract-insufficient.","key_references":[{"PMID":"12194978","why":"Kd of purified Grp 78 for alpha(2)M* and signalling block"}],"covers":["LR002063","LR005389"]},"LR005015":{"pair":"ADAM11 -> ITGA4","headline":"Non-catalytic ADAM11 supports integrin alpha4-dependent cell adhesion in one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Human ADAM11, ADAM23 and ADAM29 selectively support integrin alpha4-dependent cell adhesion; their disintegrin-like domains are ligands for a subset of integrins [PMID:28913673].","molecular_requirements":"The beta partner and domain details beyond the disintegrin-like domain are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; integrin binding assays [PMID:28913673].","localisation_and_range":"ADAM11 is flagged not secreted [flag]; adhesive ligand on a cell surface.","caveats":"One paper, abstract only; the curator's evidence sentence is truncated mid-word. Assay is cell adhesion, not purified binding.","key_references":[{"PMID":"28913673","why":"Non-catalytic ADAMs support integrin alpha4 adhesion"}],"covers":["LR001627","LR005015"]},"LR002072":{"pair":"ADAM23 -> ITGAV","headline":"ADAM23 disintegrin domain binds integrin alphavbeta3 and negatively modulates its activation; two abstract-only papers, human.","interaction_type":"direct binding","direction_and_effect":"ADAM23 disintegrin-like domain promotes cell adhesion via alphavbeta3 by an RGD-independent mechanism [PMID:10749942]. ADAM23 knockdown enhanced alphavbeta3 activation by at least 2- to 4-fold, indicating a negative modulator (curator label: antagonist) [PMID:19549921].","molecular_requirements":"Binding is mediated by a short sequence in the disintegrin loop lacking an RGD motif; alphav pairs with beta3 [PMID:10749942].","affinity_potency":[],"species_and_systems":"Human neural and astrocytoma cells, transfected HeLa [PMID:10749942]; MDA-MB-435 cells and immunodeficient mice [PMID:19549921].","localisation_and_range":"ADAM23 flagged secreted and receptor [flag]; the studies used the cell-bound and recombinant domain.","caveats":"Both abstract only. The two papers describe different effects (adhesion-promoting versus negative modulation of activation).","key_references":[{"PMID":"10749942","why":"ADAM23 disintegrin binds alphavbeta3, RGD-independent"},{"PMID":"19549921","why":"ADAM23 negatively modulates alphavbeta3 activation"}],"covers":["LR002072","LR005398"]},"LR001631":{"pair":"ADAM7 -> ITGB7","headline":"ADAM7 disintegrin domain is recognised by alpha4beta7 in cell-adhesion assays; abstract only.","interaction_type":"functional only","direction_and_effect":"Alpha4beta7 recognises the disintegrin domains of ADAM7 and ADAM28 but not ADAM33; the authors say this is the first demonstration of a mammalian disintegrin interacting with alpha4beta7 [PMID:15504110].","molecular_requirements":"Beta7 acts as alpha4beta7; recognition is activation-dependent, needing Mn2+ or an activating monoclonal antibody [PMID:15504110].","affinity_potency":[],"species_and_systems":"Human ADAM disintegrin-like domains in cell-adhesion assays [PMID:15504110]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM7 is flagged secreted [flag]; adhesion to immobilised domain.","caveats":"Abstract read only; adhesion assay rather than purified binding.","key_references":[{"PMID":"15504110","why":"Alpha4beta7 recognises ADAM7 disintegrin domain"}],"covers":["LR001631","LR005019"]},"LR008210":{"pair":"ADAM9 -> ITGA6:ITGB1","headline":"ADAM9 disintegrin domain captured alpha6 and beta1 integrin chains from kidney lysate; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Immobilised GST-ADAM9 disintegrin domain recovered alpha3, alpha6, alphav and beta1 integrin chains from renal cortical lysate; the same domain competitively inhibited HEK-293 adhesion to several matrix proteins, so ADAM9 acts as an adhesion ligand [PMID:15361064].","molecular_requirements":"The disintegrin domain was the active part; the cysteine-rich domain alone had no effect [PMID:15361064]. Chains were detected separately by Western, so the alpha6beta1 heterodimer itself is inferred, not shown.","affinity_potency":[],"species_and_systems":"Human HEK-293 cells and renal cortical lysate [PMID:15361064].","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Single paper, read as abstract only [PMID:15361064]. Affinity not reported in our evidence. No database support.","key_references":[{"PMID":"15361064","why":"GST-disintegrin capture of alpha6 and beta1 chains from lysate"}],"covers":["LR008210"]},"LR005402":{"pair":"ADAMTS13 -> CD163","headline":"ADAMTS13 binds CD163 SRCR domains by SPR and CD163 mediates its macrophage uptake; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance showed ADAMTS13 binding to CD163 scavenger receptor cysteine-rich domains 1-9 and 1-5; anti-CD163 antibody EDHu-1 decreased ADAMTS13 internalisation by macrophages, and CD163-expressing CHO cells rapidly internalised it, so CD163 acts as an endocytic clearance receptor [PMID:29296945].","molecular_requirements":"SRCR domains 1-5 are sufficient for binding in SPR [PMID:29296945]. Uptake was not blocked by an antibody to the mannose receptor CD206 [PMID:29296945].","affinity_potency":[],"species_and_systems":"Human monocyte-derived macrophages, CHO cells expressing CD163, recombinant proteins [PMID:29296945].","localisation_and_range":"Ligand flagged secreted [flag]; CD163 is on macrophages, with uptake from the circulation [PMID:29296945].","caveats":"Abstract-only read; no Kd reported in our evidence. Inhibition by antibody was partial and strongest in CD163-high macrophages [PMID:29296945]. No database support.","key_references":[{"PMID":"29296945","why":"SPR binding and macrophage uptake via CD163"}],"covers":["LR002076","LR005402"]},"LR000029":{"pair":"ADCYAP1 -> VIPR2","headline":"PACAP binds VPAC2 and stimulates adenylate cyclase in recombinant systems; abstract-level evidence from three papers.","interaction_type":"direct binding","direction_and_effect":"Recombinant mouse PACAPR-3 bound VIP as well as PACAP-38 and -27, with slightly higher affinity for PACAP-38, and was positively coupled to adenylate cyclase [PMID:8146174]. Human VPAC2 cAMP and calcium responses to PACAP were characterised in CHO cells [PMID:16930633]. GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain. The carboxy-terminal helical structure of related peptides is needed for VIP2 recognition [PMID:9928018].","affinity_potency":[],"species_and_systems":"Recombinant mouse receptor in mammalian cells [PMID:8146174]; human recombinant receptor in CHO cells [PMID:16930633]. The mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Ligand flagged secreted [flag]; peptide acting on a membrane receptor.","caveats":"All read as abstracts only; no numeric affinity in our evidence. Two pending and one different_entity row not shown. PMID:9928018 concerns related peptides, not PACAP itself. Structures exist [DB:PDB 7VQX].","key_references":[{"PMID":"8146174","why":"cloned mouse VPAC2 binds PACAP-38, PACAP-27 and VIP and couples to adenylate cyclase"},{"PMID":"16930633","why":"PACAP potency at human VPAC2"}],"covers":["LR000029","LR003579"]},"LR002081":{"pair":"ADGRL1 -> NRXN2","headline":"Latrophilin-1 ectodomain binds neurexins with nanomolar affinity; evidence is one abstract-only paper that covers neurexins as a group.","interaction_type":"direct binding","direction_and_effect":"Direct binding between the extracellular domains of latrophilin-1 (CL1) and neurexins; CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing both formed stable adhesion, so trans-cellular [PMID:22262843].","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1; those with an SS4 insert do not. The olfactomedin-like domain of CL1 mediates binding [PMID:22262843].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"saturation binding","system":"purified ectodomains","cite":"PMID:22262843"}],"species_and_systems":"Purified ectodomains and cell adhesion assays; species not stated beyond curator label human [PMID:22262843]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both partners are membrane proteins [flag]; interaction is trans-cellular, suggesting juxtacrine signalling [PMID:22262843].","caveats":"Abstract only, and the abstract speaks of neurexins generally, so isoform specificity for NRXN2 is not shown in our evidence. Only the SS4-minus form binds [PMID:22262843]. Ligand-receptor direction is not defined, as both are membrane proteins.","key_references":[{"PMID":"22262843","why":"identifies latrophilin-1/neurexin binding"}],"covers":["LR002081","LR005407"]},"LR005411":{"pair":"ADIPOQ -> CDH13","headline":"T-cadherin was expression-cloned as a receptor for hexameric and HMW adiponectin (one abstract-only paper).","interaction_type":"direct binding","direction_and_effect":"T-cadherin is a receptor for hexameric and high-molecular-weight adiponectin but not trimeric or globular species [PMID:15210937]. A signalling effect is not shown; the authors suggest a coreceptor role [PMID:15210937].","molecular_requirements":"Only eukaryotically expressed adiponectin bound; a mutant lacking the N-terminal cysteine needed for hexamer/HMW formation did not bind T-cadherin in co-immunoprecipitation [PMID:15210937]. T-cadherin may need an unidentified signalling receptor [PMID:15210937].","affinity_potency":[],"species_and_systems":"Cloning by panning a C2C12 myoblast cDNA library in Ba/F3 cells with recombinant adiponectin [PMID:15210937]; curator labels species human, which the abstract does not support.","localisation_and_range":"Adiponectin flagged secreted [flag]; T-cadherin is a GPI-anchored extracellular protein [PMID:15210937].","caveats":"Abstract only; no affinity reported. Form-specific: trimeric and globular adiponectin are not bound [PMID:15210937].","key_references":[{"PMID":"15210937","why":"expression cloning of T-cadherin"}],"covers":["LR002085","LR005411"]},"LR005024":{"pair":"ADM -> RAMP3","headline":"ADM acts on CLR:RAMP3 (the AM2 receptor); binding shown on the RAMP3/CRLR complex in HEK cells, so RAMP3 is a co-receptor, not a stand-alone receptor.","interaction_type":"direct binding","direction_and_effect":"ADM is an agonist at the RAMP3-containing receptor: 125I-ADM radioligand binding and cAMP responses characterise RAMP3/CRLR as an ADM receptor [PMID:10347248][PMID:11693189]. In HUVEC, ADM-driven migration and invasion is mediated by CRLR/RAMP2 and CRLR/RAMP3 [PMID:14712479]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RAMP3 acts with CLR/CRLR (obligate heterodimer; RAMP2 or RAMP3 gives AM1 or AM2 receptors) [PMID:27013657]. RAMP2/CRLR and RAMP3/CRLR were indistinguishable for ADM binding and cAMP [PMID:10347248]. Both subunits should be counted when scoring this pair. RAMP3 shapes the CLR juxtamembrane region and gives the most negative ECD electrostatic potential [PMID:27013657].","affinity_potency":[{"value":"pKi 8.3-9.0","assay":"binding, GtoPdb agonist record","system":"not given in the database record","cite":"DB:GtoPdb"},{"value":"pEC50 6.9-8.3","assay":"functional, GtoPdb agonist record","system":"not given in the database record","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments used human or porcine CRLR with rat-ADM tracer in HEK-293/293T cells [PMID:11693189][PMID:10347248], HUVEC [PMID:14712479], and mutagenesis with modelling [PMID:27013657]. The mouse pair is projected from human. A PDB structure (6UUS) contains chains of ADM-pathway receptor proteins P35318 and O60896 [DB:PDB 6UUS].","localisation_and_range":"ADM is flagged secreted and RAMP3 transmembrane [flag]; so paracrine or endocrine signalling to a membrane receptor.","caveats":"Evidence is at complex level, not RAMP3 alone. All papers were read as abstracts (one with full text). One paper counted here concerns AM2/IMD, not ADM [PMID:30139742]. Four papers were abstract_insufficient and one is pending.","key_references":[{"PMID":"10347248","why":"125I-ADM binding on RAMP3/CRLR in HEK293T"},{"PMID":"11693189","why":"radioligand binding and cAMP, human and porcine CRLR with RAMP3"},{"PMID":"27013657","why":"RAMP2/RAMP3 give distinct AM receptor subtypes"}],"covers":["LR001636","LR005024"]},"LR002090":{"pair":"AGR2 -> LYPD3","headline":"AGR2 is reported as a ligand of LYPD3 (C4.4A) by two-hybrid records; the paper adds only a structure and docking suggestion, not a direct demonstration.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says AGR2 interacts with LYPD3 and DAG1 [DB:UniProt]; BioGRID lists two two-hybrid records [DB:BioGRID]. The paper's Fab site on C4.4A appears to be the AGR2 binding site, and docking placed AGR2 near that site [PMID:32140067].","molecular_requirements":"Both LU-domains of LYPD3 contribute to the Fab combining site and the proposed AGR2 contact; the docking points to the DII-Lk1 region [PMID:32140067].","affinity_potency":[],"species_and_systems":"Human C4.4A crystal structures and a ZDOCK docking model; no AGR2-LYPD3 experiment [PMID:32140067].","localisation_and_range":"AGR2 is flagged secreted [flag].","caveats":"The paper calls AGR2 a 'reported ligand' and does not test the interaction. Abstract plus excerpts only. Direction or effect is not reported in our evidence.","key_references":[{"PMID":"32140067","why":"structure of two LU-domain C4.4A with docking of AGR2"}],"covers":["LR002090","LR005416"]},"LR000038":{"pair":"AGRN -> ATP1A3","headline":"Agrin binds the alpha3 subunit of Na+/K+-ATPase in CNS neurons and inhibits its activity; one abstract, with the pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Biochemical evidence shows agrin binds alpha3NKA; agrin inhibits alpha3NKA activity, depolarising membranes and raising action potential frequency in cultured and slice cortical neurons. A competitive-antagonist agrin fragment lowers frequency [PMID:16630822].","molecular_requirements":"Only the alpha3 subunit of NKA is reported [PMID:16630822]. Other partners are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured and acute-slice cortical neurons [PMID:16630822]; the animal species is not stated in the abstract. Both listed pairs are ortholog-inferred.","localisation_and_range":"AGRN is flagged secreted and transmembrane [flag]; ATP1A3 is flagged receptor [flag].","caveats":"Abstract-only; ATP1A3 is an enzyme and the effect is inhibitory, so it differs from a usual receptor activation. Binding is described as biochemical evidence, with no affinity in our evidence.","key_references":[{"PMID":"16630822","why":"agrin binds alpha3 Na+/K+-ATPase and inhibits it in CNS neurons"}],"covers":["LR000038","LR003588"]},"LR005420":{"pair":"AGRN -> PTPRS","headline":"Agrin binds chicken PTPsigma with high affinity in vitro through its heparan sulfate chains; evidence is avian and glycan-dependent.","interaction_type":"direct binding","direction_and_effect":"Agrin and collagen XVIII were identified as basal lamina ligands of cPTPsigma, interacting with high affinity in vitro [PMID:11865065]. Reactome lists an AGRN:NCAM1, PTPRS complex [DB:Reactome].","molecular_requirements":"The binding is totally dependent on agrin's heparan sulfate chains, and a heparin/heparan sulfate binding site maps to the first immunoglobulin-like domain of cPTPsigma [PMID:11865065].","affinity_potency":[],"species_and_systems":"Chicken protein (cPTPsigma / CRYPalpha) only; no human or mouse experiments in our evidence [PMID:11865065].","localisation_and_range":"Basal lamina (matrix) ligand [PMID:11865065]; PTPRS is flagged secreted and transmembrane [flag].","caveats":"Abstract-only. Because binding is glycan-dependent, other heparan sulfate proteoglycans bind too (collagen XVIII shown), so it is not protein-specific. The affinity is called 'high' but no value is given. Human or mouse relevance is ortholog-inferred.","key_references":[{"PMID":"11865065","why":"In vitro high-affinity, heparan sulfate-dependent binding of agrin to chicken PTPsigma"}],"covers":["LR002094","LR005420"]},"LR000047":{"pair":"AGT -> LRP2","headline":"One paper shows purified megalin binds angiotensin II by SPR; megalin acts as an uptake receptor for the peptide, not full-length AGT.","interaction_type":"direct binding","direction_and_effect":"Megalin and, to a lesser extent, cubilin act as receptors for Ang II: antisera interfered with Ang II uptake in BN-16 cells, and with binding to mouse brush-border membrane vesicles, and purified megalin bound Ang II directly in SPR [PMID:15467006]. Effect is internalisation (clearance).","molecular_requirements":"Cubilin, described as megalin's chaperone, contributes to a lesser extent [PMID:15467006]. Uptake was only partly blocked by AT1 antagonists, so other receptors contribute.","affinity_potency":[],"species_and_systems":"Curator records human ligand and mouse receptor; the abstract names BN-16 yolk sac cells and mouse proximal tubule vesicles [PMID:15467006].","localisation_and_range":"Megalin is an endocytic membrane receptor; the ligand is secreted [flag].","caveats":"Single paper, abstract only. No affinity reported. Ligand is Ang II, not full-length AGT. Mouse pair is ortholog-inferred. No database records.","key_references":[{"PMID":"15467006","why":"Four lines of evidence including SPR binding of purified megalin to Ang II"}],"covers":["LR000047","LR003597"]},"LR001640":{"pair":"ALCAM -> CD6","headline":"CD6 and ALCAM engagement is needed for T cell-APC contact and proliferation; binding assays appear in databases.","interaction_type":"functional only","direction_and_effect":"ALCAM-blocking antibodies interfered with DC-T cell conjugate formation, and CD6-blocking antibodies or recombinant ALCAM-Fc inhibited T cell proliferation. CD6 and CD3 crosslinking drove proliferation comparable to CD3/CD28, so CD6 is described as costimulatory [PMID:16352806].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human DC and T cells [PMID:16352806]. Databases list ELISA, light scattering, competition binding and solid phase assays [DB:IntAct] and a reconstituted complex [DB:BioGRID 279128].","localisation_and_range":"Both are membrane proteins acting at the DC-T cell contact zone (juxtacrine); the paper reports stable binding unlike transient ALCAM homophilic contact [PMID:16352806].","caveats":"Verified paper is functional, abstract only; physical binding rests on database records. No affinity in this dossier.","key_references":[{"PMID":"16352806","why":"ALCAM-CD6 needed for DC-T cell contact and proliferation"}],"covers":["LR001640","LR005028"]},"LR005033":{"pair":"ALKAL1 -> LTK","headline":"ALKAL1 is a crystallographically and biochemically supported agonist ligand of LTK; evidence is human, in vitro and in cells.","interaction_type":"direct binding","direction_and_effect":"ALKAL1 (FAM150A) activates LTK; it is described as an LTK-specific ligand that only weakly binds ALK [PMID:26630010]. Both ALKAL1 and ALKAL2 are strong LTK activators [PMID:34646012]. GtoPdb lists an agonist/activation interaction [DB:GtoPdb].","molecular_requirements":"Crystal structure of the LTK cytokine-binding (TNF-like plus glycine-rich) domain with ALKAL1 shows ALKAL1 helix A residues Phe80 and Phe76 inserting into an LTK hydrophobic pocket [PMID:34646012]. LTK-ALKAL1 complexes were 2 receptors : 1 cytokine, not the canonical 2:2 [PMID:34646012]. Site 1 charge-reversal mutants in ALKAL1 markedly reduced affinity for both receptors [PMID:34646012]. Other subunit or co-receptor needs: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins: purified human LTK ectodomain fragments and ALKAL1 for crystallography [PMID:34646012]; human ALK/LTK-expressing cells in binding and activation assays [PMID:26630010]. The mouse pair is inferred from human by orthology.","localisation_and_range":"ALKAL1 is flagged as secreted in the entity annotation [flag]; Reactome places the LTK dimer:ALKAL1,2 complex at the plasma membrane [DB:Reactome]. Acts as a secreted ligand on a membrane receptor.","caveats":"[PMID:26630010] was read as abstract only. Affinity values are not reported in our evidence. The dossier also lists a PDB entry [DB:PDB 7NX0] and IntAct co-immunoprecipitation [DB:IntAct]. One further row is still pending.","key_references":[{"PMID":"34646012","why":"Crystal structures of LTK with ALKAL1, interface mutagenesis, stoichiometry"},{"PMID":"26630010","why":"Specificity of ALKAL1 for LTK versus ALK in cells"}],"covers":["LR001645","LR005033"]},"LR000056":{"pair":"ANGPT1 -> TIE1","headline":"ANGPT1 weakly activates TIE1 alone, more strongly via Tie2 heteromers; one phosphorylation paper and one mouse genetics abstract.","interaction_type":"functional only","direction_and_effect":"Native Ang1 and Ang4 induced Tie1 phosphorylation, less efficiently than the soluble chimera COMP-Ang1; this is an agonist effect [PMID:15851516]. In mice, the combined function of angiopoietin-1 and TIE1 is critical for right-hand-side venous development [PMID:11172728].","molecular_requirements":"Overexpressed Tie1 alone was only weakly phosphorylated by COMP-Ang1 in cells without Tie2; Tie2 co-transfection formed Tie1/Tie2 heteromeric complexes, enhanced Tie1 activation and induced phosphorylation of kinase-inactive Tie1 in a ligand-dependent manner [PMID:15851516]. Tie2 acts as a co-receptor for this activation.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in endothelial and transfected cells [PMID:15851516]; mouse genetics [PMID:11172728]. BioGRID lists a protein-peptide ANGPT1-TIE1 record [DB:BioGRID].","localisation_and_range":"ANGPT1 is flagged as secreted [flag]; TIE1 has no localisation flag beyond receptor status.","caveats":"Both papers were read as abstracts. Direct ANGPT1-TIE1 binding is not shown in our evidence: the phosphorylation paper used mostly COMP-Ang1, and the mouse paper reports a genetic interaction and the receptor is called an orphan [PMID:11172728]. Relevance for CCC: TIE1 activation depends on Tie2.","key_references":[{"PMID":"15851516","why":"Ang1-induced Tie1 phosphorylation, amplified by Tie2 heteromers"},{"PMID":"11172728","why":"Mouse genetics: Ang1 and TIE1 jointly needed for right-side venous system"}],"covers":["LR000056","LR003606"]},"LR002108":{"pair":"ANGPTL2 -> LILRB5","headline":"ANGPTL2 bound LILRB5-overexpressing cells with lower affinity than LILRB2; one paper, cell-binding assay only.","interaction_type":"direct binding","direction_and_effect":"Angptl2 bound LILRB5-overexpressing cells [PMID:22660330]. Effect on receptor signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor expressed in 293T cells [PMID:22660330].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Binding to LILRB5 was described as of lower affinity than to LILRB2-expressing cells; the values are in a supplementary table not shown [PMID:22660330]. The paper's purified-protein co-IP and SPR were for LILRB2, not LILRB5. No affinity in our evidence.","key_references":[{"PMID":"22660330","why":"Angptl2 binds LILRB5-expressing cells, weaker than LILRB2"}],"covers":["LR002108"]},"LR003611":{"pair":"ANGPTL3 -> ITGAV","headline":"Recombinant ANGPTL3 binds integrin alphaVbeta3; the evidence is for the heterodimer, not ITGAV alone.","interaction_type":"direct binding","direction_and_effect":"Recombinant ANGPTL3 bound alpha(v)beta(3) and induced alpha(v)beta(3)-dependent endothelial cell adhesion and migration, with phosphorylation of Akt, MAPK and FAK [PMID:11877390]. UniProt records the same [DB:UniProt].","molecular_requirements":"Evidence is for the alphaVbeta3 heterodimer; ITGAV alone is not tested in our evidence. The C-terminal fibrinogen-like domain alone was sufficient for adhesion and in vivo angiogenesis [PMID:11877390].","affinity_potency":[],"species_and_systems":"Endothelial cells and rat corneal assay; species of the recombinant protein not reported in our evidence [PMID:11877390]. The mouse pair is projected from human.","localisation_and_range":"ANGPTL3 is described as a liver-specific secreted factor [PMID:11877390]; ligand also flagged secreted [flag].","caveats":"Abstract-only evidence; no affinity. Co-IP failed to detect ANGPTL3 binding to Tie2 [PMID:11877390].","key_references":[{"PMID":"11877390","why":"ANGPTL3 binds alphaVbeta3 and promotes endothelial adhesion and migration"}],"covers":["LR000061","LR003611"]},"LR002117":{"pair":"ANGPTL4 -> NRP2","headline":"ANGPTL4 is reported to bind NRP2 and NRP1 directly on endothelial cells, activating RhoA/ROCK; abstract-level.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 binds directly to NRP1 and NRP2 on endothelial cells, rapidly activating RhoA/ROCK and breaking down EC-EC junctions; curator labels it agonist [PMID:31545295]. The permeability effect is independent of VEGFR2, and soluble NRP1 blocks ANGPTL4-NRP1 binding and retinal leakage in vivo [PMID:31545295].","molecular_requirements":"NRP2 alone is not shown to suffice; NRP1 is the partner dissected with the soluble-receptor blocker, and no co-receptor requirement is stated for NRP2 [PMID:31545295].","affinity_potency":[],"species_and_systems":"Endothelial cells in vitro, diabetic mouse retina, and diabetic macular edema patient samples [PMID:31545295]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; NRP2 transmembrane [flag]; paracrine action on endothelium.","caveats":"Abstract only; no affinity or binding assay detail; the block experiments target NRP1, so NRP2-specific functional evidence is thinner.","key_references":[{"PMID":"31545295","why":"ANGPTL4 binds NRP1/NRP2 to drive RhoA/ROCK junction breakdown"}],"covers":["LR002117","LR005439"]},"LR000065":{"pair":"ANXA1 -> FPR3","headline":"One paper shows an annexin 1 N-terminal peptide activates FPR3 (FPRL2); intact ANXA1 not tested in our evidence.","interaction_type":"functional only","direction_and_effect":"An annexin 1 N-terminal peptide activated and desensitised HEK293 cells stably expressing FPRL2 (FPR3), and the authors call it the first endogenous ligand of FPRL2, acting as an agonist [PMID:15187149]. GtoPdb lists it as full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain tested; no co-receptor reported in our evidence. The active entity was the peptide, not the full-length protein [PMID:15187149].","affinity_potency":[{"value":"pEC50 5.0 to 7.0","assay":"GtoPdb affinity range (pEC50)","system":"not specified in dossier","cite":"PMID:15187149"}],"species_and_systems":"Human FPR family members expressed in HEK293 cells; peptide also acted on human monocytes [PMID:15187149].","localisation_and_range":"ANXA1 is flagged as secreted and FPR3 as transmembrane [flag].","caveats":"Single paper, read as abstract only. Peptide, not intact ANXA1, was used. A second judged paper was review-only. Reactome and UniProt records cite the same paper [DB:Reactome, DB:UniProt].","key_references":[{"PMID":"15187149","why":"Annexin 1 peptide activates all three FPR family members in single-receptor HEK293 cells."}],"covers":["LR000065"]},"LR005042":{"pair":"ANXA2 -> ROBO4","headline":"Weak, functional-only support that recombinant ANXA2 signals through a Robo4 pathway in brain endothelial cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Recombinant ANXA2 reduced trans-endothelial permeability and rescued junctional proteins in human brain endothelial cells damaged by hypoxia plus IL-1beta, in part by modulating signalling via the Robo4-paxillin-ARF6 pathway [PMID:29786451]. Curators label it agonist.","molecular_requirements":"Not reported in our evidence. Effects were also mediated in part through F-actin and VE-cadherin interactions [PMID:29786451].","affinity_potency":[],"species_and_systems":"Human brain endothelial cells in vitro; ANXA2 knockout mice (E15.5 and adult) showed reduced junctional proteins and more tracer leakage [PMID:29786451].","localisation_and_range":"ANXA2 is flagged as secreted [flag]; the paper describes it as an endothelial cell membrane protein [PMID:29786451].","caveats":"No direct binding to Robo4 is shown in the abstract; Robo4 involvement is inferred from pathway modulation, and the effect is only 'in part'. Single paper read as abstract only; no database record.","key_references":[{"PMID":"29786451","why":"Proposes ANXA2 as a Robo4 ligand in cerebral endothelium."}],"covers":["LR001655","LR005042"]},"LR012152":{"pair":"APCDD1 -> FZD6:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD6 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD6 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD6 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD6. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012152"]},"LR002135":{"pair":"APOA1 -> CUBN","headline":"ApoA-I binds cubilin with high affinity by surface plasmon resonance in one paper; read as abstract only.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance showed high-affinity binding of apoA-I and HDL to cubilin; cubilin-expressing yolk sac cells endocytosed 125I-HDL, blocked by antibodies against apoA-I and cubilin [PMID:10371504]. Cubilin is proposed as a receptor in epithelial apoA-I/HDL metabolism [PMID:10371504].","molecular_requirements":"Reactome models the complex as apoA-I bound to CUBN:AMN, so AMN may be part of the receptor [DB:Reactome]; the abstract does not test this.","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; the abstract gives no further system detail, and the yolk sac cell species is not stated [PMID:10371504].","localisation_and_range":"Cubilin carries a receptor flag [flag]; endocytosis of HDL implies a membrane receptor on epithelial cells [PMID:10371504].","caveats":"No numeric affinity in the abstract. Single paper, abstract only.","key_references":[{"PMID":"10371504","why":"SPR binding and HDL endocytosis"}],"covers":["LR002135","LR005452"]},"LR007103":{"pair":"APOB -> TREM2:TYROBP","headline":"Database records about TREM2 only; the single paper judged was review-only.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a TREM2-APOB reconstituted complex and UniProt lists apolipoproteins including APOB as TREM2 ligands [DB:BioGRID][DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"Complex members TREM2 and TYROBP [flag]; whether TREM2 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TYROBP is flagged transmembrane and TREM2 flagged secreted [flag].","caveats":"No primary paper confirmation. See the APOB -> TREM2 dossier.","key_references":[],"covers":["LR007103"]},"LR002144":{"pair":"APOC3 -> LRP1","headline":"Mouse genetics show APOC3 inhibits triglyceride-rich lipoprotein clearance through LRP1; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"An APOC3-targeting antisense oligonucleotide lowered fasting triglycerides in a manner dependent on LDLR and LRP1; the effect was lost only in mice lacking both [PMID:27400128]. The authors conclude APOC3 inhibits clearance of triglyceride-rich lipoproteins (antagonist-like) through the hepatic LDLR/LRP1 axis [PMID:27400128].","molecular_requirements":"Redundant: either LRP1 or LDLR alone suffices for the effect; both knocked out abolishes it [PMID:27400128].","affinity_potency":[],"species_and_systems":"Mouse, in vivo with knockout lines and injections of lipoproteins [PMID:27400128]. Human pair is ortholog-inferred.","localisation_and_range":"APOC3 flagged secreted; the receptor carries a receptor flag [flag]. Mainly hepatic clearance [PMID:27400128].","caveats":"Indirect genetic evidence; no binding assay in our evidence. Abstract only. Single paper, same for both receptors.","key_references":[{"PMID":"27400128","why":"ASO and receptor knockouts show LDLR/LRP1-dependent effect"}],"covers":["LR002144","LR005461"]},"LR000074":{"pair":"APOE -> LRP2","headline":"Thin: only an in vivo infusion study and a BioGRID reconstituted-complex record; no direct binding in our evidence.","interaction_type":"functional only","direction_and_effect":"Infusing recombinant apoE3 into apoE-deficient and RAP-deficient mice had differential neurotrophic effects correlated with LRP and LDL-R levels [PMID:11421580]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant apoE3 in mice [PMID:11421580]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"ApoE flagged secreted [flag].","caveats":"The curated evidence sentence is a background statement that apoE binds five receptors including megalin, not a result about LRP2; the study itself concerned LRP and LDL-R. Another confirmed paper is not shown; one review-only.","key_references":[{"PMID":"11421580","why":"in vivo apoE infusion; abstract only"}],"covers":["LR000074","LR003623"]},"LR002153":{"pair":"APP -> AGER","headline":"One 1996 abstract reports RAGE as a receptor for amyloid-beta (APP-derived peptide); no affinity shown.","interaction_type":"functional only","direction_and_effect":"RAGE was presented as a cell-surface receptor for amyloid-beta peptide, mediating its effects on neurons and microglia [PMID:8751438]. UniProt describes AGER as sensing amyloid beta/APP oligomers [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and brain; details not reported in our evidence [PMID:8751438].","localisation_and_range":"APP flagged secreted, receptor and transmembrane; the active ligand is the secreted peptide [flag].","caveats":"Ligand evidence concerns the amyloid-beta peptide, not full-length APP. Abstract only.","key_references":[{"PMID":"8751438","why":"RAGE as amyloid-beta receptor"}],"covers":["LR002153","LR005468"]},"LR000083":{"pair":"APP -> LRP1","headline":"Secreted, KPI-containing APP binds LRP1 and is internalised through it; shown by two older papers plus BioGRID and IntAct.","interaction_type":"direct binding","direction_and_effect":"LRP is responsible for endocytosis of secreted APP; APPs770 degradation was inhibited by the antagonist RAP and by LRP antibodies and was greatly reduced in LRP-deficient fibroblasts [PMID:7543026]. A GST-LRP cluster II fusion bound sAPP-KPI from conditioned medium, and RAP competed with this binding [PMID:12212791].","molecular_requirements":"The KPI-domain-containing form is the ligand: APPs695, which lacks KPI, is a poor LRP ligand [PMID:7543026]. The LRP cluster II region is sufficient for binding in vitro [PMID:12212791].","affinity_potency":[],"species_and_systems":"Cultured cells and LRP-deficient fibroblasts [PMID:7543026]; CHO cells (LRP-deficient L2 and LRP-expressing L3) [PMID:12212791]. Species of fibroblasts not reported in our evidence.","localisation_and_range":"Ligand is secreted APP; the receptor is an endocytic receptor, so the interaction is paracrine or autocrine clearance [PMID:7543026]. LRP1 is flagged receptor [flag].","caveats":"Both papers read as abstracts. The effect is endocytosis and degradation, not a signalling response. One further paper is pending and not shown. BioGRID (Affinity Capture-Western) and IntAct (pull down) also list the pair [DB:BioGRID][DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"7543026","why":"LRP mediates endocytosis of secreted APP"},{"PMID":"12212791","why":"LRP cluster II binds sAPP-KPI"}],"covers":["LR000083","LR003632"]},"LR002162":{"pair":"APP -> LRP4","headline":"APP binds LRP4 in recombinant and cell-aggregation assays, and mouse genetics support cooperation at the neuromuscular junction.","interaction_type":"direct binding","direction_and_effect":"APP interacts with LRP4, and agrin also binds APP and cooperatively enhances APP-LRP4 interaction; APP synergistically increased agrin-induced AChR clustering in myotubes [PMID:23986861]. APP-/- combined with LRP4 ECD/ECD gave smaller and fewer NMJs and perinatal lethality [PMID:23986861].","molecular_requirements":"Agrin enhances the interaction; LRP4 is the obligate co-receptor for MuSK [PMID:23986861]. Interaction is ectodomain-dependent: LRP4 ligand-binding domain (MBP fusion) bound APP ECD (Fc fusion) [PMID:23986861].","affinity_potency":[],"species_and_systems":"Recombinant fusion proteins, 293-cell aggregation and cultured myotubes; mouse NMJ genetics [PMID:23986861]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound pair acting at the NMJ; cell aggregation suggests trans interaction, consistent with APP and LRP4 on neighbouring cells [PMID:23986861].","caveats":"Single paper, abstract plus excerpts, no database record. APP-LRP4 may act as a hetero-oligomeric complex with agrin rather than a simple ligand-receptor pair. Affinity not reported in our evidence.","key_references":[{"PMID":"23986861","why":"APP-LRP4-agrin interaction at the NMJ"}],"covers":["LR002162","LR005477"]},"LR000092":{"pair":"ASIP -> MC4R","headline":"ASIP inhibits agonist-stimulated cAMP at human MC4R in one 1997 paper (abstract only); a potent antagonist here, no affinity number in our evidence.","interaction_type":"functional only","direction_and_effect":"ASIP is an antagonist: purified recombinant ASIP inhibited agonist-stimulated cAMP generation (alpha-MSH, or ACTH for hMC2R) and also inhibited radiolabeled-melanocortin binding to hMCR1-5. At MC4R it is a potent inhibitor (surmountable antagonism) [PMID:9058374].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence. Degree and mechanism of inhibition vary significantly among the five melanocortin receptor subtypes [PMID:9058374].","affinity_potency":[],"species_and_systems":"Human ASIP and human MC4R stably expressed in L cells and the adrenocortical OS3 cell line [PMID:9058374]. Recombinant cell assays, not in vivo.","localisation_and_range":"ASIP is flagged secreted and the receptor as a transmembrane receptor [flag]; the paper calls agouti protein a paracrine signalling molecule (stated for mouse agouti) [PMID:9058374]. ","caveats":"Single paper, read as abstract only. No Kd, Ki or IC50 in our evidence, so potency is qualitative. Schild-analysis details are not available beyond the abstract-level curator note. The same paper covers all five melanocortin receptors, so this is one study counted in five pairs.","key_references":[{"PMID":"9058374","why":"Pharmacology of human ASIP at hMC1R-hMC5R: cAMP and binding inhibition"}],"covers":["LR000092"]},"LR012080":{"pair":"BAMBI -> ACVR1:BMPR2","headline":"BAMBI to ACVR1:BMPR2 has no verified paper; support is limited to one BioGRID record that names a different receptor chain pair.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR1 and BMPR2; the BioGRID record concerns BMPR1B only, which is not a member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012080"]},"LR012062":{"pair":"BAMBI -> ACVR2B:BMPR1B","headline":"BAMBI to ACVR2B:BMPR1B has no verified paper; support is one BioGRID reconstituted-complex record for BMPR1B only.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR2B and BMPR1B; the BioGRID record concerns BMPR1B only, one member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012062"]},"LR007112":{"pair":"BMP2 -> ACVR2B:BMPR1A","headline":"Heteromer is not supported: the one paper judged found ACVR2B was not required for BMP signalling in primary human MSCs; database records are chain-level.","interaction_type":"conflicting","direction_and_effect":"Same hMSC screen found osteoinductive BMP activity acts through ACVR1A, BMPR1A, ACVR2A and BMPR2, and ACVR2B was not found to play a significant role [PMID:18436533]. GtoPdb lists BMP2 as agonist at ACVR2B and at BMPR1A separately [DB:GtoPdb].","molecular_requirements":"Not reported for this combination. Records for ACVR2B binding BMP2 come from BioGRID reconstituted complexes [DB:BioGRID], a PDB ternary structure of BMP-2 with receptors [DB:PDB 2H62], and UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Negative from human primary mesenchymal stem cells [PMID:18436533]. Other records: species not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"ACVR2B was expressed at low levels in hMSC, so the negative may reflect expression [PMID:18436533]. Abstract-only read. Complex-level support is database-derived only.","key_references":[{"PMID":"18436533","why":"explicit negative for ACVR2B in hMSC"}],"covers":["LR007112"]},"LR000119":{"pair":"BMP2 -> BMPR1A","headline":"Well supported direct binding: crystal structure, mutational mapping, gel filtration and SPR with human proteins.","interaction_type":"direct binding","direction_and_effect":"BMP2 is the ligand and BMPR1A (BRIA) the type I receptor; effect recorded as stimulatory/agonist [DB:GtoPdb]. The BMP-2 L51P variant lost type I receptor binding only, keeping type II and noggin binding [PMID:15064755]. A GDF5 variant with higher BMPR1A affinity gained BMP2-like properties, and BMP2 was almost completely inhibited by the BMPR1A ectodomain, which the paper cites as earlier work [PMID:19956691].","molecular_requirements":"Two BRIA ectodomains bind one BMP-2 dimer at the wrist epitopes, with no contacts between the receptor domains [PMID:10881198]; BMP-2 forms a 1:2 complex with sBMPR-IA [PMID:10692589]. Leu51 and Asp53 main-chain atoms of BMP-2 are a binding hot spot [PMID:15064755]. Signalling needs a type II chain too [DB:UniProt].","affinity_potency":[{"value":"apparent KD 0.8 nM","assay":"SPR, immobilized BMPR-IA ectodomain","system":"recombinant ligand and receptor ectodomains","cite":"PMID:19735544"},{"value":"KD 48 nM","assay":"SPR with immobilized BMP2, soluble BMPR-IA (no avidity)","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Human proteins for the crystal structure, gel filtration and SPR [PMID:10881198][PMID:10692589]; human and mouse pairs both listed. Mouse P19 cell labelling formed ALK3 and ALK6 complexes with BMP2 [PMID:9748228].","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"Three of the structural/binding papers were read as abstracts only. The 0.8 nM and 48 nM values differ by assay format [PMID:19735544]. The GDF5 paper concerns a GDF5 mutant, not BMP2 directly [PMID:19956691]. The 9748228 quote is browser-read, unverified, and uses ALK3 naming.","key_references":[{"PMID":"10881198","why":"crystal structure of BMP-2 with BRIA ectodomains"},{"PMID":"19735544","why":"SPR affinities of BMP2 for type I and II receptors"},{"PMID":"15064755","why":"mutational hot spot of BMP-2 for BRIA"}],"covers":["LR000119","LR003668"]},"LR000128":{"pair":"BMP4 -> BMPR1A","headline":"BMP4 binds BMPR1A (ALK-3) in transfected COS cells and nontransfected cells; supported by two binding papers, both abstract only.","interaction_type":"direct binding","direction_and_effect":"BMP-4 bound ALK-3 (BMPR1A) and ALK-6 efficiently, in transfected COS cells and in nontransfected MC3T3-E1 osteoblasts and human foreskin fibroblasts; effect is agonist [PMID:8006002]. A second paper maps the BMPR-IA ligand-binding domain by alanine scanning for BMP-4 binding [PMID:11241215]. UniProt describes BMP4 associating with BMPR1A [DB:UniProt].","molecular_requirements":"In the 1994 paper binding to some type I receptors occurred without a type II receptor and was increased by co-transfected C. elegans DAF-4 [PMID:8006002].","affinity_potency":[],"species_and_systems":"Transfected COS cells and nontransfected MC3T3-E1 and human foreskin fibroblasts [PMID:8006002]; recombinant extracellular domain [PMID:11241215]. Curators record human.","localisation_and_range":"BMP4 flagged secreted; BMPR1A transmembrane [flag].","caveats":"Both papers abstract only. No affinity value in our evidence. MC3T3-E1 is a mouse line per the curator's description.","key_references":[{"PMID":"8006002","why":"BMP-4 binds ALK-3 efficiently in transfected and nontransfected cells"},{"PMID":"11241215","why":"Ligand-binding site mapping of BMPR-IA for BMP-4"}],"covers":["LR000128","LR003677"]},"LR007121":{"pair":"BMP4 -> BMPR1B:BMPR2","headline":"BMP4 binds each chain (BMPR1B and BMPR2) in separate papers; hMSC siRNA found BMPR1B not required; complex not tested as a unit.","interaction_type":"conflicting","direction_and_effect":"BMP-4 bound ALK-6 (BMPR1B) efficiently in COS cells [PMID:8006002] and CFK-43a specifically binds BMP-4 [PMID:7811286]. BRK-3 (BMPR2) binds BMP-4 [PMID:7673243]; BMPR-II bound ligands only weakly alone [PMID:7644468]. In primary hMSC, BMPR1B was not found to play a significant role [PMID:18436533].","molecular_requirements":"BMPR2 cross-linking to BMP-4 was undetectable without a type I receptor (BRK-1 or BRK-2); a super-high-affinity subpopulation formed only with BRK-2+BRK-3 [PMID:7673243]. Which type I receptor pairs with BMPR2 is not resolved to BMPR1B in the abstracts.","affinity_potency":[],"species_and_systems":"COS transfectants and human skin fibroblast-derived receptor [PMID:7673243; PMID:8006002]; primary human MSC for the negative [PMID:18436533].","localisation_and_range":"BMP4 flagged secreted; complex flagged transmembrane [flag].","caveats":"All abstract only. The 1994 binding paper used C. elegans DAF-4 as type II partner [PMID:8006002]. The BMPR2 chain evidence does not name BMPR1B. Negative in hMSC likely reflects low expression there.","key_references":[{"PMID":"7811286","why":"BMP-4 binding to cloned BMPR1B"},{"PMID":"7673243","why":"BMPR2 binds BMP-4, requires type I receptor"},{"PMID":"18436533","why":"BMPR1B not required in hMSC"}],"covers":["LR007121"]},"LR002180":{"pair":"BMP4 -> MUSK","headline":"MuSK binds BMP4 directly with low-nanomolar affinity and acts as a BMP co-receptor; one paper, human/human labels, read in full.","interaction_type":"direct binding","direction_and_effect":"MuSK is reported as a BMP4 co-receptor: it promotes BMP4-dependent SMAD phosphorylation and Id1 transcription in myoblasts, and the curators label it agonist [PMID:27601729]. The soluble MuSK ectodomain instead inhibited BMP4-induced Id1 reporter activity by 50% at 50 or 100 nM, possibly by sequestering BMP4 [PMID:27601729].","molecular_requirements":"High-affinity BMP4 binding required the alternatively spliced third Ig-like domain (Ig3) of MuSK; a construct lacking Ig3 showed only low, nonsaturable binding. MuSK also bound type I receptors ALK3 and ALK6 independently of ligand, and its BMP effect needed type I BMP receptor activity but not MuSK kinase activity [PMID:27601729].","affinity_potency":[{"value":"Kd 6.1 nM","assay":"SPR, BMP4 immobilised, MuSK ectodomain as analyte","system":"recombinant proteins","cite":"PMID:27601729"},{"value":"half-maximal binding ~30 nM","assay":"binding titration of BMP4 to Fc-fused full-length MuSK ectodomain","system":"recombinant proteins","cite":"PMID:27601729"}],"species_and_systems":"Curators label ligand and receptor experiments as human. Binding was shown by nickel-bead pull-down and SPR with recombinant proteins; signalling used C2C12-derived myoblasts/myotubes, whose species the excerpts do not state [PMID:27601729]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP4 is flagged secreted [flag]; MuSK is a receptor tyrosine kinase described in muscle cells [PMID:27601729]. Ligand-receptor range beyond that is not reported in our evidence.","caveats":"Single paper. Binding Kd varied by assay (6.1 nM SPR; half-maximal about 30 nM in a binding titration with Fc-fusion ectodomain).","key_references":[{"PMID":"27601729","why":"SPR and pull-down binding of BMP4 to MuSK; Ig3 requirement; BMP signalling effects"}],"covers":["LR002180","LR005494"]},"LR007130":{"pair":"BMP5 -> BMPR1B:BMPR2","headline":"BMP5 to BMPR1B:BMPR2 rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with BMPR2 (type II) with BMPR1A, not BMPR1B [DB:UniProt][PMID:11580864].","molecular_requirements":"Chains in the complex: BMPR1B and BMPR2; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 4 review_only. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007130"]},"LR000137":{"pair":"BMP6 -> BMPR1B","headline":"BMP-6 binds BMPR-IB efficiently in one full-text paper (cross-linking, cell-type dependent); GtoPdb and BioGRID agree.","interaction_type":"direct binding","direction_and_effect":"BMP-6 bound BMPR-IB (ALK-6) in ROB-C26 cells, together with BMPR-II; curated effect is agonist [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR1B [DB:GtoPdb].","molecular_requirements":"When type I receptors were singly transfected, only weak BMP-6 binding to BMPR-IB was seen; binding improved with co-transfected type II receptors [PMID:10504300].","affinity_potency":[],"species_and_systems":"125I-BMP-6 (recombinant human) cross-linking in transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 cell lines and rat-lineage ROB-C26 cells named in the paper [PMID:10504300]. BioGRID lists a BMP6-BMPR1B reconstituted complex [DB:BioGRID]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"BMP6 is flagged as secreted [flag].","caveats":"The BMPR-IB binding profile was cell-type dependent (ROB-C26). Single verified paper; no affinity value. Two abstract-insufficient papers not used.","key_references":[{"PMID":"10504300","why":"Efficient BMP-6 binding to BMPR-IB, cell-type dependent"}],"covers":["LR000137","LR003686"]},"LR005501":{"pair":"BMP7 -> RGMA","headline":"BMP7 binds RGMA directly by SPR (Kd 63 nM); single abstract-level paper with full-text support, human proteins.","interaction_type":"direct binding","direction_and_effect":"Curators record the effect as agonist; the paper's abstract describes RGM proteins as co-receptors that enhance cellular responses to BMP ligands, but this paper measured binding only [PMID:23029472].","molecular_requirements":"Binding was measured for the RGM protein alone; type I/II BMP receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 63 nM","assay":"surface plasmon resonance","system":"recombinant human proteins (curator-annotated species)","cite":"PMID:23029472"}],"species_and_systems":"SPR with recombinant proteins; curators annotate both partners as human, mouse pair is ortholog-inferred [PMID:23029472].","localisation_and_range":"Both BMP7 and RGMA are flagged secreted [flag]; range of action not reported in our evidence.","caveats":"RGMA bound BMP7 with intermediate affinity, between HJV (20 nM) and RGMB (166 nM) [PMID:23029472]. BMP7 had the lowest relative affinity of the BMPs tested for the RGMs, and BMP7-RGM data needed CM4 sensor chips because fitting on CM5 chips was poor [PMID:23029472]. Curator read depth is abstract-only. Only one paper.","key_references":[{"PMID":"23029472","why":"SPR kinetics of all RGM-BMP pairs including BMP7"}],"covers":["LR002187","LR005501"]},"LR005051":{"pair":"BSG -> SELE","headline":"Basigin is a glycan-dependent E-selectin ligand on neutrophils in mouse renal ischemia/reperfusion; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Bsg-deficient mice showed suppressed neutrophil infiltration and less renal damage; Bsg-/- neutrophils had reduced E-selectin binding and reduced E-selectin-dependent adherence to HUVEC [PMID:19443639]. Curator effect: agonist.","molecular_requirements":"Binding depends on N-linked glycans: Bsg isolated from HL-60 cells bound E-selectin and tunicamycin abolished this binding; neutrophil Bsg carries N-linked polylactosamine chains [PMID:19443639].","affinity_potency":[],"species_and_systems":"Mouse in vivo model and neutrophils, plus HL-60 and HUVEC in vitro cells; mouse experiments for the paper, human cell lines for binding [PMID:19443639].","localisation_and_range":"BSG is flagged transmembrane; SELE is flagged transmembrane and not secreted [flag]; leukocyte-endothelial contact (juxtacrine).","caveats":"Abstract only; no affinity reported; effect on receptor is adhesion, not classical signalling [PMID:19443639].","key_references":[{"PMID":"19443639","why":"Bsg-deficient mice and neutrophil binding assays; glycan-dependent E-selectin binding."}],"covers":["LR001671","LR005051"]},"LR000146":{"pair":"BTC -> EGFR","headline":"BTC is a well-supported EGFR agonist from several papers, with sub-nanomolar to nanomolar affinity.","interaction_type":"direct binding","direction_and_effect":"BTC binds and activates EGFR as an agonist: it is equipotent with EGF in stimulating Balb/c 3T3 proliferation and competes with EGF at the same receptor [PMID:8144591]. In MIN-6 beta cells BTC induced phosphorylation of ErbB-1 and ErbB-2 only [PMID:21897861]. UniProt lists BTC among known EGFR ligands [DB:UniProt].","molecular_requirements":"BTC-TX50 phosphorylated EGFR and HER4, and EGFR (not HER4) mediated its internalisation-dependent cytotoxicity [PMID:9528863]. Truncated forms (BTC-1a, BTC-1b, BTC-2) are equally active [PMID:8144591].","affinity_potency":[{"value":"Kd 0.5 nM","assay":"receptor binding","system":"Balb/c 3T3 cells, human BTC","cite":"PMID:8144591"},{"value":"pKi 8.45","assay":"NanoBRET competition vs EGF-AF488","system":"HEK293T cells, full-length NLuc-EGFR","cite":"PMID:36505413"}],"species_and_systems":"Human BTC on Balb/c 3T3 cells, A431, rat mesangial cells [PMID:8144591]; HEK293T [PMID:36505413]; mouse MIN-6 cells and mice [PMID:21897861]. The mouse pair is listed without ortholog inference.","localisation_and_range":"BTC is flagged both secreted and transmembrane [flag]; soluble forms were purified from conditioned medium [PMID:8144591].","caveats":"All papers were read at abstract level plus excerpts; pKi in GtoPdb [DB:GtoPdb] comes from the same paper as the NanoBRET value [PMID:36505413]. A structure/scattering record exists in IntAct [DB:IntAct].","key_references":[{"PMID":"8144591","why":"Recombinant BTC; Kd 0.5 nM and EGF cross-competition at EGFR."},{"PMID":"36505413","why":"NanoBRET pKi 8.45 for BTC at full-length EGFR."},{"PMID":"9528863","why":"BTC binds EGFR and HER4; EGFR-dependent cytotoxicity."}],"covers":["LR000146","LR003695"]},"LR005510":{"pair":"C1QA -> DDR1","headline":"C1q is reported to activate DDR1 and drive HepG2 migration and invasion; direct binding is not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"C1q induced activation and upregulation of DDR1, and DDR1 knockdown attenuated C1q-induced migration and invasion of HepG2 cells [PMID:29559654]. C1q also activated MAPK and PI3K/Akt signalling [PMID:29559654].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HepG2 cells, with similar results in SUN182 cells; the mouse pair is ortholog-inferred [PMID:29559654].","localisation_and_range":"C1q annotated secreted [flag].","caveats":"The title and excerpts rest on DDR1 phosphorylation and siRNA assays; no physical binding assay is described. One paper only.","key_references":[{"PMID":"29559654","why":"C1q activates DDR1 in hepatocellular cells"}],"covers":["LR002196","LR005510"]},"LR002216":{"pair":"C1QL2 -> NRXN3","headline":"C1QL2 acts through direct interaction with the neurexin-3 splice variant Nrxn3(25b+) at mouse mossy fiber-CA3 synapses; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"C1ql2 regulates synaptic vesicle recruitment and long-term potentiation at mossy fiber-CA3 synapses; a non-binding C1ql2 mutant or Nrxn3 deletion in dentate gyrus granule neurons recapitulates major parts of the Bcl11b and C1ql2 mutant phenotypes [PMID:38358390].","molecular_requirements":"Requires a specific splice variant, Nrxn3(25b+) [PMID:38358390]; other variants are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse, in vivo and in vitro (the abstract says 'in mice'); the mouse pair is not ortholog-inferred, the human pair is [PMID:38358390].","localisation_and_range":"C1ql2 is described as a synaptic organizer; flags: ligand secreted, NRXN3 transmembrane [flag].","caveats":"Abstract and a few excerpts only; the binding assay itself is not described in our evidence, and no affinity is given.","key_references":[{"PMID":"38358390","why":"Bcl11b-C1ql2-Nrxn3(25b+) pathway in mouse mossy fiber synapses"}],"covers":["LR002216","LR005529"]},"LR000155":{"pair":"C3 -> C3AR1","headline":"C3a binds and activates C3aR; well supported by binding, cloning and potency data in human and mouse receptors.","interaction_type":"direct binding","direction_and_effect":"C3a is an agonist: cells expressing C3aR bound 125I-C3a and responded to human C3a with calcium mobilization [PMID:8702752]. C3a stimulated calcium mobilization in cells expressing human or mouse C3aR [PMID:9476119]. GtoPdb lists C3-C3AR1 as an agonist interaction [DB:GtoPdb].","molecular_requirements":"The active ligand is the cleavage fragment C3a, not intact C3; this is a curator caveat [PMID:20527893]. Reactome records C3AR1 binding anaphylatoxin C3a [DB:Reactome]. PDB structures contain both chains [DB:PDB 8HK2].","affinity_potency":[{"value":"EC50 0.24 nM","assay":"calcium mobilization","system":"RBL-2H3 cells expressing human C3aR","cite":"PMID:9476119"},{"value":"EC50 1.3 nM","assay":"calcium mobilization","system":"RBL-2H3 cells expressing mouse C3aR","cite":"PMID:9476119"}],"species_and_systems":"Human C3a on human C3aR (transfected cells, neutrophils); mouse receptor tested in transfected RBL-2H3 cells [PMID:9476119]. Mouse pair is ortholog-inferred.","localisation_and_range":"C3a is flagged secreted and C3AR1 transmembrane [flag]; acts on cells in the vicinity of complement activation (annotation-based).","caveats":"All papers read as abstracts only. A C3a analogue peptide was about 10-fold less active than C3a on human C3aR [PMID:9476119]. C4a did not clearly act on this receptor in that study; data were hard to interpret [PMID:9476119].","key_references":[{"PMID":"8702752","why":"Cloning of human C3aR with 125I-C3a binding"},{"PMID":"9476119","why":"Potency on human and mouse C3aR"},{"PMID":"11342658","why":"C3aR pharmacology and antagonist characterisation"}],"covers":["LR000155","LR003704"]},"LR003710":{"pair":"C3 -> LRP1","headline":"Activated C3 binds LRP1 with a Kd of 17 nM in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"125I-C3 bound a 600-kDa endosomal protein by ligand blotting, competed by receptor-associated protein, lactoferrin and Pseudomonas exotoxin, and uptake was abolished in LRP-deficient mouse fibroblasts [PMID:10608878].","molecular_requirements":"Binding was Ca2+-dependent [PMID:10608878]. Subunit requirements not reported in our evidence.","affinity_potency":[{"value":"Kd 17 nM","assay":"saturable uptake","system":"cells; human 125I-C3","cite":"PMID:10608878"}],"species_and_systems":"Human 125I-C3 on endosomal proteins; LRP-deficient mouse fibroblasts used as control [PMID:10608878]. Mouse pair is ortholog-inferred.","localisation_and_range":"LRP1 is an endocytic receptor; localisation is not described beyond the paper.","caveats":"Abstract only. Curator note: native plasma C3 is not internalised; binding applies to activated C3 [PMID:10608878]. Possible role is clearance rather than signalling.","key_references":[{"PMID":"10608878","why":"C3 binding and uptake via LRP1"}],"covers":["LR000161","LR003710"]},"LR000164":{"pair":"C4BPA -> CD40","headline":"Human C4BP alpha chain binds CD40 directly on B cells and acts as an agonist; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The alpha chain of human C4BP binds directly to CD40 on human B cells at a site different from CD40 ligand; it activates B cells (proliferation, CD54/CD86 upregulation, IL-4-dependent IgE switching) [PMID:12818164].","molecular_requirements":"Alpha chain; effects absent in CD40-deficient and IKKgamma/NEMO-deficient patient B cells [PMID:12818164].","affinity_potency":[],"species_and_systems":"Human proteins and primary human B cells [PMID:12818164].","localisation_and_range":"C4BPA flagged secreted; CD40 flagged transmembrane [flag]. C4BP colocalised with B cells in human tonsil germinal centres [PMID:12818164].","caveats":"Abstract only; no affinity reported in our evidence. Binds a distinct site from CD40L, so it is an additional agonist, not a CD40L mimic.","key_references":[{"PMID":"12818164","why":"Direct binding and genetic confirmation in patient B cells"}],"covers":["LR000164"]},"LR002225":{"pair":"C9 -> CD59","headline":"CD59 binds C9 and inhibits membrane attack complex assembly; one human abstract-level paper plus BioGRID and PDB.","interaction_type":"direct binding","direction_and_effect":"CD59 binds C8 alpha chain and C9 after their rearrangement during MAC assembly, regulating MAC formation (an inhibitory, protective role) [PMID:16844690]. UniProt states CD59 inhibits MAC assembly [DB:UniProt].","molecular_requirements":"Human C9 residues 365-371 are the primary CD59 recognition domain; C8alpha and C9 bind a similar or overlapping CD59 site [PMID:16844690].","affinity_potency":[],"species_and_systems":"Human peptides and proteins; peptide binding, functional assays and docking [PMID:16844690]. BioGRID lists reconstituted complex records [DB:BioGRID]; PDB 8B0G and 8B0H contain chains of P02748 and P13987 [DB:PDB 8B0G].","localisation_and_range":"CD59 flagged secreted and receptor [flag]; it is a membrane glycoprotein per the abstract [PMID:16844690], acting on cell membranes.","caveats":"Abstract only. This is a regulator/inhibitor relationship, not a classical signalling ligand-receptor pair. No affinity reported in our evidence.","key_references":[{"PMID":"16844690","why":"Defines C9 365-371 as CD59 recognition site"}],"covers":["LR002225"]},"LR005060":{"pair":"CADM3 -> NECTIN1","headline":"Heterophilic CADM3-nectin-1 adhesion shown in cell-aggregation assay; one abstract-level paper plus Reactome.","interaction_type":"functional only","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with nectin-1, but not nectin-2 or Necl-5 [PMID:15741237]. Reactome lists a Necl-1:Nectin-1 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell-aggregation assays; abstract only, human-labelled [PMID:15741237]. Both species pairs are ortholog-inferred.","localisation_and_range":"Membrane-bound [flag]; Necl-1 is neural-specific at axon-glia contact sites [PMID:15741237]. Trans, contact-dependent.","caveats":"Abstract only. Adhesion assays do not exclude other cell-surface mediators; curators labelled it direct binding. No affinity reported.","key_references":[{"PMID":"15741237","why":"Necl-1 heterophilic adhesion with nectin-1"}],"covers":["LR001684","LR005060"]},"LR002234":{"pair":"CADM4 -> CADM1","headline":"CADM4 binds CADM1 directly by SPRi, a newly reported heterophilic interaction with a cell-spreading readout; one paper.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance imaging showed CADM1 interacts with CADM4, which had not been reported previously [PMID:30131958]. ATN1 leukemia cells (CADM1-expressing) spread on CADM4-Fc-coated glass; CADM1 knockdown or a neutralizing CADM1 antibody blocked spreading [PMID:30131958]. The pair is adhesive and has no ligand/receptor polarity in the paper; the 'agonist' label is the curator's.","molecular_requirements":"SPRi detects only direct two-molecule interactions [PMID:30131958]. No accessory subunit is reported. Co-culture immunoprecipitation of CADM4-FLAG and CADM1-GFP cells also pulled down CADM1 [PMID:30131958].","affinity_potency":[{"value":"Kd 192.7 nM","assay":"SPRi, CADM1-Fc with CADM4-Fc (Table 1)","system":"recombinant Fc proteins","cite":"PMID:30131958"}],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"Both are annotated as transmembrane [flag]; the paper describes a trans-heterophilic interaction between neighbouring cells, i.e. contact-dependent (juxtacrine) [PMID:30131958].","caveats":"Single paper. Earlier affinity chromatography and cell-adhesion assays could not detect this interaction, and the authors suggest it may give too little adhesion activity [PMID:30131958]. The curator's assay_class here is 'structural' with read depth abstract_only, although full text is available.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002234","LR005544"]},"LR000173":{"pair":"CALCA -> RAMP2","headline":"alpha-CGRP shows weaker cAMP signalling at RAMP2-containing receptors than at RAMP1; evidence is two abstract-level functional papers.","interaction_type":"functional only","direction_and_effect":"alpha-CGRP binding and signalling were markedly weaker with CTR2/RAMP2 than with CTR2/RAMP1 or CRLR/RAMP1 in HEK-293 cells [PMID:14722252]. With CTRa, chimeras carrying the RAMP2 C-terminal domain did not increase CGRP potency [PMID:16531504]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"Activity is seen only as RAMP/receptor heterodimers (CTR2/RAMP2 [PMID:14722252], CTRa chimeras [PMID:16531504]); RAMP2 alone is not shown to bind CGRP. Structure 7TYH exists with chains P01258 and O60895 [DB:PDB 7TYH].","affinity_potency":[{"value":"pEC50 6.2 to 9.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human CTR2/CTRa with RAMP2 expressed in HEK-293 [PMID:14722252] or COS-7 cells [PMID:16531504]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Both papers were read as abstracts only. The signal is weak relative to RAMP1, and the RAMP2 result in [PMID:16531504] is a lack of potentiation. No binding to RAMP2 by CGRP itself is reported in our evidence.","key_references":[{"PMID":"14722252","why":"CGRP signalling weaker at CTR2/RAMP2 than RAMP1"},{"PMID":"16531504","why":"RAMP2 C-terminus does not raise CGRP potency"}],"covers":["LR000173","LR003718"]},"LR002243":{"pair":"CBLN1 -> NRXN1","headline":"CBLN1 links GluRdelta2 to presynaptic neurexins; supported by one abstract-read paper in mouse neurons.","interaction_type":"direct binding","direction_and_effect":"The GluRdelta2 N-terminal domain interacts with presynaptic neurexins through Cbln1; the extracellular domain of NRXN1beta suppressed Cbln1's synaptogenic activity [PMID:20537373].","molecular_requirements":"The complex is a three-part bridge: Cbln1 is required, since GluRdelta2 synaptogenic activity was abolished in Cbln1-knockout cultures and restored by recombinant Cbln1 [PMID:20537373]. NRXN knockdown also hindered it.","affinity_potency":[],"species_and_systems":"Mouse cerebellar primary cultures and in vivo, per the abstract (Cbln1 knockout mice); curators recorded human [PMID:20537373]. The human pair is ortholog-inferred.","localisation_and_range":"CBLN1 is flagged secreted and NRXN1 transmembrane [flag]; action across the synapse.","caveats":"Abstract read only. Direct CBLN1-NRXN1 binding is not measured in the abstract; the evidence is competitive suppression and knockdown. The NRXN1beta (not alpha) isoform is the one named. A second confirmed paper was not shown.","key_references":[{"PMID":"20537373","why":"Cbln1 bridges GluRdelta2 NTD and presynaptic neurexins"}],"covers":["LR002243","LR005553"]},"LR002252":{"pair":"CCL1 -> ACKR1","headline":"Direct but weak binding of CCL1 to human Duffy antigen (ACKR1) on erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CCL1 displaced radiolabelled chemokine on human red blood cells; signalling or scavenging effect is not reported in our evidence [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 309.3 nM","assay":"radioligand displacement","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes, native receptor [PMID:15358176]. Human only.","localisation_and_range":"CCL1 flagged secreted, ACKR1 transmembrane [flag].","caveats":"The paper defines strong binding as Ki < 100 nM and weak as 100 nM-1 uM, so 309.3 nM falls in the weak class [PMID:15358176].","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of the Duffy antigen"}],"covers":["LR002252"]},"LR000182":{"pair":"CCL11 -> ACKR2","headline":"CCL11 binds the atypical receptor ACKR2 (D6) with relatively low affinity and is taken up by it; atypical scavenger, two confirming papers.","interaction_type":"direct binding","direction_and_effect":"Human D6 binds eotaxin (detectable but relatively lower affinity than other beta-chemokines) and does not flux calcium [PMID:9405404]. In human trophoblasts and HEK-ACKR2 cells, excess unlabeled CCL11 reduced CCL2 uptake, consistent with ACKR2-mediated scavenging [PMID:25297873]. UniProt lists CCL11 among ACKR2 chemokine ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor; primary human trophoblasts and HEK cells; Ackr2-deficient mice used for phenotypes [PMID:25297873]. Mouse pair is projected.","localisation_and_range":"CCL11 flagged secreted, ACKR2 transmembrane [flag].","caveats":"The first paper notes the physiological relevance of the eotaxin interaction remains to be determined [PMID:9405404]. CCL11 evidence in the second paper is competition for uptake, not direct binding. No affinity numbers in our evidence.","key_references":[{"PMID":"9405404","why":"Cloning of human D6 and chemokine binding profile"},{"PMID":"25297873","why":"ACKR2 scavenging in human trophoblasts, competed by CCL11"}],"covers":["LR000182","LR003727"]},"LR000191":{"pair":"CCL13 -> CCR3","headline":"CCL13 (MCP-4) activates CCR3 on eosinophils and basophils in vitro; functional evidence is good, direct CCL13 affinity is not reported.","interaction_type":"functional only","direction_and_effect":"MCP-4 elicits basophil migration similar to RANTES and MCP-3 [PMID:9276730]. More than 95% of eosinophil response to MCP-4 and other chemokines is mediated by CCR3 [PMID:9005985]; MCP-4-induced eosinophil shape change is inhibited by an antagonist [PMID:10854442]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Primary human eosinophils and basophils [PMID:9005985][PMID:9276730].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"No independent CCL13 binding data in our evidence; CCL13 is only background in one paper [PMID:16339911]. Truncated MMP-processed forms bind CCR3 but are antagonists [PMID:12149192]. Abstract-only reads.","key_references":[{"PMID":"9276730","why":"MCP-4 drives basophil migration via CCR3"},{"PMID":"9005985","why":"CCR3 mediates over 95% of eosinophil response to MCP-4"},{"PMID":"10854442","why":"Antagonist blocks MCP-4 eosinophil shape change"}],"covers":["LR000191"]},"LR000236":{"pair":"CCL2 -> CCR2","headline":"Strongly supported, the canonical CCL2 receptor, with picomolar binding and an agonist role, from five papers and several databases.","interaction_type":"direct binding","direction_and_effect":"CCL2 (MCP-1) is the agonist; calcium mobilization through CCR2 was as efficient with CCL2 as with vCCL4, with cross-desensitisation [PMID:12554737]; CHO-CCR2 cells treated CCL2 as primary agonist [PMID:15207250]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"The 35 N-terminal residues of CCR2 bound MCP-1 with affinity similar to intact receptor and were necessary and sufficient for high-affinity binding [PMID:9287323].","affinity_potency":[{"value":"35 pM","assay":"alanine-scanning binding of wild-type MCP-1","system":"THP-1 and CCR2-transfected CHL cells","cite":"PMID:10529171"},{"value":"Kd 60 nm","assay":"spiropiperidine blocking MCP-1 binding (antagonist)","system":"CCR2","cite":"PMID:10770925"}],"species_and_systems":"Human ligand and receptor in recombinant cell lines [PMID:10529171][PMID:15207250]; mouse pair is ortholog-inferred. PDB 7XA3 holds a structure of the two chains [DB:PDB 7XA3]; UniProt records CCR2 as the key functional CCL2 receptor [DB:UniProt].","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"All papers abstract only. The 60 nm value describes a small-molecule inhibitor, not CCL2 affinity [PMID:10770925]. CCL2 also acts on CCR3 as agonist [PMID:15207250], so it is not CCR2-exclusive.","key_references":[{"PMID":"10529171","why":"Mutagenesis, wild-type affinity 35 pM"},{"PMID":"9287323","why":"N-terminal CCR2 domain needed for high-affinity binding"},{"PMID":"12554737","why":"Calcium mobilization and cross-desensitisation"}],"covers":["LR000236","LR003757"]},"LR000218":{"pair":"CCL22 -> CCR4","headline":"CCL22 is a high-affinity agonist ligand of CCR4, shown by direct binding and calcium signalling in transfected cells.","interaction_type":"direct binding","direction_and_effect":"CCL22 (MDC) acts as an agonist: it bound CCR4-transfected L1.2 cells with high affinity, competed with TARC, and induced calcium flux only in CCR4-transfected cells among seven CC receptors tested [PMID:9430724]. N-terminal truncation by two residues impaired CCR4 binding and abolished T-cell chemotaxis but kept monocyte attraction [PMID:9743322]; CD26/DPP IV-processed MDC(5-69) gave impaired CCR4 calcium mobilisation [PMID:9933589].","molecular_requirements":"Single receptor (CCR4) was sufficient in transfectants [PMID:9430724]. The intact N-terminus matters: MDC(1-69) is the active form, truncated forms are weaker at CCR4 [PMID:9743322][PMID:9933589].","affinity_potency":[{"value":"Kd 0.18 nM","assay":"binding of MDC-secreted alkaline phosphatase fusion","system":"CCR4-transfected L1.2 cells","cite":"PMID:9430724"}],"species_and_systems":"Experiments used human ligand and human receptor in transfected L1.2 cells and primary cells [PMID:9430724][PMID:9743322]. The mouse pair is ortholog-inferred, with no mouse experiments in our evidence. BioGRID and GtoPdb records point to PMID 9430724 [DB:BioGRID][DB:GtoPdb].","localisation_and_range":"Ligand is flagged secreted, receptor transmembrane [flag]; so paracrine signalling to CCR4-bearing cells.","caveats":"All papers were read as abstracts only. A possible additional MDC receptor on monocytes is suggested [PMID:9743322].","key_references":[{"PMID":"9430724","why":"Kd, competition and calcium flux for CCL22-CCR4"},{"PMID":"9743322","why":"N-terminal truncation impairs CCR4 binding"},{"PMID":"9933589","why":"DPP IV processing reduces CCR4 activity"}],"covers":["LR000218","LR003745"]},"LR000227":{"pair":"CCL26 -> CCR3","headline":"CCL26 is a functional CCR3 agonist, roughly tenfold less potent than eotaxin; direct binding and calcium data in L1.2 cells.","interaction_type":"direct binding","direction_and_effect":"Agonist: eotaxin-3 induced calcium mobilisation specifically in CCR3-expressing L1.2 cells and was chemotactic for eosinophils and basophils at high concentrations [PMID:10488147]. Described as a primary CCR3 ligand [PMID:15207250]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR3 alone in L1.2 cells was sufficient [PMID:10488147].","affinity_potency":[{"value":"EC50 3 nM","assay":"calcium mobilisation","system":"CCR3-expressing L1.2 cells","cite":"PMID:10488147"},{"value":"IC50 13 nM","assay":"competition of 125I-eotaxin binding","system":"CCR3-expressing L1.2 cells","cite":"PMID:10488147"},{"value":"pIC50 7.9-8.9","assay":"GtoPdb range, unspecified assay","system":"database record","cite":"PMID:15207250"}],"species_and_systems":"Human ligand and receptor in L1.2 transfectants and primary human cells [PMID:10488147]; CHO line [PMID:15207250].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"Potency about 10-fold below eotaxin [PMID:10488147]. PMID 16339911 mentions CCL26 only as background [PMID:16339911]. Abstracts only.","key_references":[{"PMID":"10488147","why":"Identified eotaxin-3 as CCR3 ligand with EC50 and IC50"},{"PMID":"15207250","why":"High-expression CCR3 line with eotaxins"}],"covers":["LR000227"]},"LR002261":{"pair":"CCL26 -> CCR5","headline":"CCL26 binds CCR5 and antagonises it, based on one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Antagonist: eotaxin-3 bound CCR5-transfected cells and monocytes and inhibited chemotaxis, calcium release and actin polymerisation stimulated by known CCR1 and CCR5 agonists [PMID:15039444].","molecular_requirements":"CCR5 transfectants bound the ligand; monocytes express both CCR1 and CCR5 [PMID:15039444].","affinity_potency":[],"species_and_systems":"Experiment species not recorded in the curator row; transfected cells and monocytes [PMID:15039444].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"One paper, abstract only; no affinity reported in our evidence. Not an activating pair.","key_references":[{"PMID":"15039444","why":"Eotaxin-3 binds and antagonises CCR5"}],"covers":["LR002261"]},"LR000245":{"pair":"CCL3 -> ACKR2","headline":"Human D6/ACKR2 binds many beta-chemokines, but the only verified paper tested murine MIP-1a, not human CCL3; support is weak and indirect.","interaction_type":"direct binding","direction_and_effect":"D6 (ACKR2) is a promiscuous beta-chemokine receptor binding most beta-chemokines [PMID:9405404]. UniProt lists CCL3 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 expressed in transduced cells; binding was measured by displacement of radioiodinated murine MIP-1a, and the highest-affinity ligands included murine MIP-1a and MIP-1b [PMID:9405404]. Both human and mouse pairs here are ortholog-inferred.","localisation_and_range":"ACKR2 is flagged as a receptor and transmembrane [flag]; CCL3 as secreted [flag].","caveats":"The paper does not report a human CCL3 value in our excerpts; the human and mouse pairs rest on murine ligand against human receptor. Other papers are review-only or abstract-insufficient. No affinity numbers are in our evidence.","key_references":[{"PMID":"9405404","why":"Cloning of human D6 with displacement binding of beta-chemokines"}],"covers":["LR000245","LR003762"]},"LR000254":{"pair":"CCL4 -> CCR8","headline":"Functional evidence only: CCL4 (MIP-1 beta) induced chemotaxis in CCR8 Jurkat stable transfectants in one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"MIP-1 beta (and TARC) were identified as CCR8 ligands because they induced chemotaxis in CCR8 Jurkat stable transfectants [PMID:9521068].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CCR8 stably expressed in Jurkat cells; chemotaxis readout [PMID:9521068].","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"Single paper read as abstract only; no direct binding or affinity reported, and no database record supports the pair.","key_references":[{"PMID":"9521068","why":"MIP-1 beta as a functional CCR8 ligand"}],"covers":["LR000254"]},"LR000263":{"pair":"CCL5 -> SDC4","headline":"One abstract-level paper reports RANTES co-immunoprecipitating with syndecan-4 on human macrophages; proteoglycan binding, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"RANTES associated with syndecan-1 and syndecan-4 but not syndecan-2 or betaglycan in co-immunoprecipitation from human monocyte-derived macrophages [PMID:14637022]. Glycosaminidase pre-treatment strongly reduced RANTES binding to syndecan-4 [PMID:14637022]. BioGRID lists Affinity Capture-Western [DB:BioGRID].","molecular_requirements":"Glycosaminoglycan chains are implicated; the authors suggest such binding facilitates subsequent RANTES-CCR5 interaction [PMID:14637022]. No signalling through syndecan-4 reported.","affinity_potency":[],"species_and_systems":"Human macrophages, endogenous proteins [PMID:14637022]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL5 flagged secreted; syndecan-4 flagged as a receptor only, with no transmembrane flag [flag].","caveats":"Abstract only; association by co-IP, no affinity. Entirely dependent on one paper and its BioGRID record.","key_references":[{"PMID":"14637022","why":"RANTES co-IPs with syndecan-4 on human macrophages"}],"covers":["LR000263","LR003773"]},"LR000272":{"pair":"CCL8 -> ACKR2","headline":"Human ACKR2 (D6) is a promiscuous CC-chemokine binder; the paper lists MCP2 (CCL8) among the highest-affinity ligands, without an affinity value.","interaction_type":"direct binding","direction_and_effect":"The full text states the highest-affinity ligands for human D6 appear to include murine MIP-1a, MIP-1b, murine JE and human MCP2 [PMID:9405404]. D6 did not flux calcium on ligand binding [PMID:9405404]. BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt lists CCL8 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 stably expressed in CHO cells, 125I-MIP-1a tracer [PMID:9405404]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL8 flagged secreted; ACKR2 flagged transmembrane receptor [flag].","caveats":"No numeric affinity for MCP2 in our evidence; the dossier does not state that MCP2 is CCL8, which is the curators' mapping.","key_references":[{"PMID":"9405404","why":"D6/ACKR2 binds MCP2 with high affinity"}],"covers":["LR000272","LR003782"]},"LR002270":{"pair":"CCN1 -> TLR4","headline":"CCN1 binds TLR4 directly and activates MyD88-dependent signalling; supported by one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CCN1 acts as an agonist: it binds TLR4 directly and drives MyD88-dependent cytokine expression and neutrophil mobilization [PMID:32144270]. Induction of Tnfa and Il6 was reduced in Tlr4-knockout BMDMs [PMID:32144270].","molecular_requirements":"Recombinant TLR4 lacking MD2 bound immobilized CCN1 in a solid-phase assay; CD14 control did not bind [PMID:32144270]. A CCN1-DM mutant that cannot bind LPS still bound TLR4 and induced signalling, so activation was independent of LPS binding [PMID:32144270]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"KD 291 nM","assay":"SPR, TLR4 immobilized, CCN1 as analyte","system":"recombinant human TLR4","cite":"PMID:32144270"}],"species_and_systems":"Human recombinant proteins for binding; signalling shown in mouse bone-marrow-derived macrophages (wild-type, Myd88 and Tlr4 knockout) [PMID:32144270]. The mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag]; the authors propose it acts as a DAMP in sterile inflammation after tissue injury [PMID:32144270].","caveats":"Single study. Affinity is moderate (hundreds of nM), similar to its alphavbeta3 binding in the same paper [PMID:32144270]. No independent replication in our evidence.","key_references":[{"PMID":"32144270","why":"SPR, solid-phase binding and knockout BMDM signalling for CCN1-TLR4"}],"covers":["LR002270","LR005571"]},"LR001703":{"pair":"CD177 -> PECAM1","headline":"CD177 binds PECAM-1 directly (SPR, cation-dependent) and supports neutrophil transmigration; well supported in human.","interaction_type":"direct binding","direction_and_effect":"CD177 is a heterophilic counter-receptor for PECAM-1; blocking antibodies to CD177 or PECAM-1 domain 6 inhibited U937 adhesion and human neutrophil transendothelial migration [PMID:17580308]. Recombinant CD177-Fc suppressed antibody-induced PECAM-1 tyrosine phosphorylation more in LSR-allele cells [PMID:20194726].","molecular_requirements":"Binding is mediated by the heterophilic domains of PECAM-1, notably membrane-proximal IgD 6, and is cation-dependent [PMID:17580308][PMID:20194726].","affinity_potency":[],"species_and_systems":"Human neutrophils, U937 cells and HUVECs; the mouse pair is ortholog-inferred [PMID:17580308][PMID:20194726].","localisation_and_range":"Both flagged membrane receptors, with CD177 also carrying a secreted flag [flag]; PECAM-1 is on endothelial junctions, so interaction is contact-dependent [PMID:20194726].","caveats":"The first paper was read as an abstract only. The PECAM-1 S536N allele changes the response [PMID:20194726]. No affinity value reported. Reactome and IntAct records agree [DB:Reactome R-HSA-202702][DB:IntAct].","key_references":[{"PMID":"17580308","why":"Identifies PECAM-1 as CD177 partner; SPR"},{"PMID":"20194726","why":"PECAM-1 S536N dimorphism modulates CD177 effects"}],"covers":["LR001703","LR005072"]},"LR000281":{"pair":"CD24 -> SELP","headline":"Three papers support CD24 binding to P-selectin, including bead and cell-binding assays; Ca2+-dependent and glycan-dependent.","interaction_type":"direct binding","direction_and_effect":"CD24 from carcinoma cells and neutrophils on latex beads bound P-selectin-IgG specifically; carcinoma cells and CD24 beads bound activated platelets or P-selectin CHO cells in a P-selectin-dependent manner and soluble CD24 blocked this [PMID:9129046]. Brain HSA bound P-selectin but not E-selectin [PMID:9048906].","molecular_requirements":"Binding needed divalent cations and was abolished by O-sialoglycoprotein endopeptidase but not endoglycosidase F or sialidase [PMID:9129046]. Both SN3b-epitope-positive and -negative CD24 glycoforms bound P-selectin [PMID:20351695].","affinity_potency":[],"species_and_systems":"Human tumour cells and neutrophils [PMID:9129046]; mouse brain HSA [PMID:9048906]; human affinity-purified glycoforms [PMID:20351695].","localisation_and_range":"Both partners flagged transmembrane [flag]; adhesive contact.","caveats":"All three papers read as abstract only; PMID:20351695 uses P-selectin binding as a readout for antibody work. No affinity. BioGRID and IntAct also list the pair [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"9129046","why":"CD24 as P-selectin ligand on tumour cells"},{"PMID":"9048906","why":"Brain HSA binds P-selectin"},{"PMID":"20351695","why":"CD24 glycoforms support P-selectin binding"}],"covers":["LR000281"]},"LR001712":{"pair":"CD244 -> CD48","headline":"Well supported direct binding of 2B4 (CD244) to CD48 by recombinant protein and SPR, with weak (micromolar) affinity.","interaction_type":"direct binding","direction_and_effect":"2B4 was identified as a ligand for CD48: recombinant mouse 2B4 on beads bound rodent cells and binding was fully blocked by anti-CD48 mAbs; human CD48 bound human 2B4 [PMID:9841922]. Curators label the effect as agonist, but the paper reports binding rather than a signalling outcome [PMID:9841922]. Reactome, IntAct and UniProt also record the binding [DB:Reactome][DB:IntAct][DB:UniProt].","molecular_requirements":"The extracellular region of 2B4 was sufficient for binding; no co-receptor requirement reported [PMID:9841922]. 2B4 and CD2 are both CD48 ligands in mouse, with 2B4 binding 6- to 9-fold more tightly [PMID:9841922].","affinity_potency":[{"value":"Kd approximately 8 microM","assay":"surface plasmon resonance (Biacore)","system":"soluble human CD48 with human 2B4-CD4d3+4","cite":"PMID:9841922"}],"species_and_systems":"Mouse and human proteins, recombinant, plus rodent cells (full text read) [PMID:9841922]. The mouse Kd was approximately 16 microM at 37 degreesC [PMID:9841922].","localisation_and_range":"Both partners are flagged membrane-bound; UniProt describes CD48 as GPI-anchored [DB:UniProt], so interaction is cell-contact (juxtacrine) [flag].","caveats":"Low affinity, typical of leukocyte surface interactions. One primary paper; other support is from databases. The paper notes in vivo relevance needs further experiments [PMID:9841922].","key_references":[{"PMID":"9841922","why":"Original identification of 2B4-CD48 binding with SPR affinity"}],"covers":["LR001712"]},"LR001721":{"pair":"CD47 -> SIRPG","headline":"CD47 binds SIRPG with lower affinity than SIRPA, shown by soluble-protein binding and database records.","interaction_type":"direct binding","direction_and_effect":"Soluble SIRPgamma extracellular region binds CD47, like SIRPalpha but more weakly [PMID:15294972]. IntAct records an FACS-based interaction and Reactome has a SIRP gamma:CD47 complex [DB:IntAct Q9P1W8-Q08722][DB:Reactome R-HSA-391166].","molecular_requirements":"SIRPgamma has a short cytoplasmic tail without known signalling motifs and lacks the lysine needed for DAP12 interaction, so the authors propose signalling via CD47 only; it is expressed without DAP12 [PMID:15294972].","affinity_potency":[{"value":"Kd approximately 23 microM","assay":"soluble SIRPgamma extracellular region binding to CD47","system":"human proteins","cite":"PMID:15294972"}],"species_and_systems":"Human proteins; SIRPgamma is on most T cells and some B cells, not myeloid cells [PMID:15294972].","localisation_and_range":"Both partners carry transmembrane flags [flag].","caveats":"One paper, abstract-only. The Kd of approximately 23 microM is weak versus approximately 2 microM for SIRPalpha [PMID:15294972]. A second paper was abstract_insufficient.","key_references":[{"PMID":"15294972","why":"SIRPgamma binds CD47 with Kd approximately 23 microM"}],"covers":["LR001721"]},"LR001730":{"pair":"CD80 -> CTLA4","headline":"CD80 binds CTLA-4, the inhibitory partner, with structural database support and two functional or binding papers; no affinity in our evidence.","interaction_type":"direct binding","direction_and_effect":"Recombinant s1CD80 bound CD152 (CTLA-4)-Ig and inhibited T-cell proliferation, suggesting a decoy-like effect [PMID:17953528]. Interaction of CTLA-4 with CD80 or CD86 inhibits human T-cell activation; blocking anti-CTLA-4 antibodies enhanced activation in CD80- or CD80/CD86-dependent assays [PMID:10583602]. The interaction record's Stimulatory annotation does not match this inhibitory function.","molecular_requirements":"Not reported in our evidence beyond a co-crystal structure [DB:PDB 1I8L] and a PP2A:CTLA4:B7-1/B7-2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human cells and proteins [PMID:17953528] [PMID:10583602]. Databases include a co-crystal structure [DB:BioGRID] [DB:PDB 1I8L] and surface plasmon resonance [DB:IntAct]. The mouse pair is ortholog-inferred.","localisation_and_range":"CD80 is membrane-bound on antigen-presenting cells with a soluble spliced form [PMID:17953528]; flags show secreted for both partners [flag].","caveats":"Both papers were read as abstracts only. The functional paper uses antibody blockade rather than direct binding. Two pending rows are not shown.","key_references":[{"PMID":"10583602","why":"CTLA-4 interaction with CD80/CD86 inhibits human T-cell activation"},{"PMID":"17953528","why":"Soluble CD80 binds CTLA-4-Ig"}],"covers":["LR001730","LR005095"]},"LR005600":{"pair":"CDH1 -> ITGA2","headline":"Pentameric E-cadherin binds integrin alpha2beta1; this entry names the alpha2 chain only.","interaction_type":"direct binding","direction_and_effect":"Pentameric but not monomeric E-cadherin bound purified alpha2beta1 and the recombinant A-domain of alpha2 in a divalent cation-dependent manner [PMID:12392763]. HT1080 adhesion was blocked by anti-alpha2 and anti-beta1 antibodies [PMID:12392763].","molecular_requirements":"alpha2beta1 heterodimer is the receptor; alpha2 A-domain binds on its own; beta1 role shown by antibody block [PMID:12392763].","affinity_potency":[],"species_and_systems":"Human HT1080 fibrosarcoma cells and purified integrin [PMID:12392763].","localisation_and_range":"Membrane-bound; adhesion.","caveats":"Abstract only; needs multivalent (pentameric) E-cadherin, suggesting low affinity; one paper.","key_references":[{"PMID":"12392763","why":"E-cadherin binds integrin alpha2beta1"}],"covers":["LR002302","LR005600"]},"LR000290":{"pair":"CDH1 -> ITGAE","headline":"E-cadherin is a direct ligand for integrin alphaE (CD103) beta7, well supported by binding, adhesion, structure and Reactome.","interaction_type":"direct binding","direction_and_effect":"E-cadherin-Fc binds directly to soluble recombinant alphaEbeta7; IELs or transfected cells adhere to it and antibodies block [PMID:9425167]. T-cell/epithelial adhesion is mediated by E-cadherin and alphaEbeta7 [PMID:7969453]; E-cadherin expression on pancreatic cancer cells affected T-cell adhesion [PMID:12434297]. UniProt: ITGAE/ITGB7 is a receptor for E-cadherin [DB:UniProt].","molecular_requirements":"alphaE pairs with beta7; this entry names the alphaE chain only [PMID:9425167]. P-cadherin needed over 100-fold more fusion protein [PMID:9425167].","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:9425167] [PMID:12434297]; mouse pair ortholog-inferred. PDB 9P99 has a structure [DB:PDB 9P99].","localisation_and_range":"Membrane-bound; contact-dependent adhesion.","caveats":"Mostly abstract-only. PMID 9233649 was confirmed on a background sentence about a beta7 mapping study.","key_references":[{"PMID":"9425167","why":"Direct E-cadherin-alphaEbeta7 binding"},{"PMID":"7969453","why":"Epithelial-IEL adhesion"},{"PMID":"12434297","why":"CD103 and E-cadherin in T-cell adhesion"}],"covers":["LR000290","LR003799"]},"LR003800":{"pair":"CDH1 -> ITGB7","headline":"E-cadherin is a direct ligand of integrin alphaEbeta7, supported by binding assays, mutagenesis and curated database records.","interaction_type":"direct binding","direction_and_effect":"Human E-cadherin-Fc bound directly to soluble recombinant alphaEbeta7 and to alphaEbeta7 from intraepithelial T lymphocytes, with adhesion blocked by antibodies to either partner [PMID:9425167]. Epithelial cell to intraepithelial T cell adhesion is mediated by this pair [PMID:7969453]. The interaction is annotated Stimulatory [flag].","molecular_requirements":"Requires the alphaE chain with beta7: mutating the MIDAS (D190A) or F298A in the alphaE A-domain abolished E-cadherin binding [PMID:10837471]. UniProt describes ITGAE/ITGB7 as a receptor for E-cadherin [DB:UniProt]. Beta7 alone is not shown to bind.","affinity_potency":[],"species_and_systems":"Recombinant human proteins and human intraepithelial T lymphocytes [PMID:9425167,PMID:10837471]; the 1994 adhesion study does not state species in our evidence [PMID:7969453]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound on both sides, so cell-cell contact signalling [flag]. Reactome lists the complex and a PDB structure (9P99) exists [DB:Reactome][DB:PDB 9P99].","caveats":"Two of the three papers were read as abstracts only. One further paper is still pending in our curation. No affinity reported.","key_references":[{"PMID":"9425167","why":"Direct binding of E-cadherin-Fc to recombinant alphaEbeta7"},{"PMID":"10837471","why":"alphaE A-domain mutations abolish E-cadherin binding"},{"PMID":"7969453","why":"Epithelial-T cell adhesion via E-cadherin and alphaEbeta7"}],"covers":["LR000291","LR003800"]},"LR002306":{"pair":"CDH10 -> CDH6","headline":"Type II cadherin heterophilic pair: cadherin-6 analyte bound a cadherin-10 surface strongly in SPR (mouse proteins).","interaction_type":"direct binding","direction_and_effect":"On cadherin-10-coated surfaces, cadherin-6 analyte gave the strongest response, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 share a specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002306","LR005604"]},"LR002315":{"pair":"CDH4 -> CDH4","headline":"R-cadherin homophilic adhesion is supported by one 1991 abstract-level report in chicken cells; weak evidence.","interaction_type":"functional only","direction_and_effect":"Cells expressing R-cadherin adhere to N-cadherin cells but form homotypic clusters in chimeric aggregates, indicating homotypic preference [PMID:1712604].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chicken R-cadherin cDNA cloned from retina; curators record mouse as the experimental species while the abstract concerns chicken, and both human and mouse pairs are ortholog-inferred [PMID:1712604].","localisation_and_range":"Membrane-bound, contact-dependent [flag].","caveats":"The evidence sentence is a whole-abstract summary rather than a homophilic binding result, and the human row was propagated from the mouse row, not re-read. Abstract only.","key_references":[{"PMID":"1712604","why":"R-cadherin cloning and homotypic adhesion"}],"covers":["LR002315","LR005613"]},"LR002324":{"pair":"CEACAM1 -> CEACAM5","headline":"Heterophilic CEACAM1-CEA binding that inhibits NK killing, from one abstract-level paper plus IntAct records.","interaction_type":"direct binding","direction_and_effect":"Heterophilic interactions of CEA (CEACAM5) with CEACAM1 inhibit killing by NK cells [PMID:15905509]. Direction is inhibitory (antagonist label in curation).","molecular_requirements":"The N domains of both CEACAM1 and CEA are necessary but not sufficient for the heterophilic and homophilic interactions; additional domains are implicated [PMID:15905509].","affinity_potency":[],"species_and_systems":"Human proteins and NK killing assays [PMID:15905509]. IntAct lists protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Not reported in our evidence beyond cell-surface interaction.","caveats":"Abstract only. Curation notes the same N-domain determinants drive homophilic CEACAM1 binding, so competition between modes is possible.","key_references":[{"PMID":"15905509","why":"CEA-CEACAM1 interaction inhibits NK killing"}],"covers":["LR002324"]},"LR002333":{"pair":"CEACAM8 -> CEACAM6","headline":"Heterophilic CEACAM8-CEACAM6 adhesion shown in one cell-adhesion study, backed by structures and database records.","interaction_type":"functional only","direction_and_effect":"CHO cells expressing CEACAM6 adhered to CEACAM8 on opposing cells via the N-domain; CEACAM8 showed only heterophilic, not homophilic, adhesion to CEACAM6 [PMID:11590190]. No activating or inhibitory effect reported.","molecular_requirements":"The N-terminal domain is critical, mapped by mutant and chimeric CEACAM6/CEACAM8 proteins [PMID:11590190].","affinity_potency":[],"species_and_systems":"Human proteins expressed in CHO transfectants [PMID:11590190].","localisation_and_range":"Trans cell-cell (juxtacrine) adhesion between opposing cells [PMID:11590190]. Both carry secreted/transmembrane flags [flag].","caveats":"Abstract only for the paper. Databases add IntAct isothermal titration calorimetry and solid phase assay, and PDB 4WTZ and 4YIQ structures with chains of both proteins [DB:IntAct] [DB:PDB 4WTZ] [DB:PDB 4YIQ]. Direction is symmetric adhesion rather than ligand to receptor.","key_references":[{"PMID":"11590190","why":"CEACAM6/CEACAM8 heterophilic adhesion mapped to the N-domain"}],"covers":["LR002333"]},"LR011153":{"pair":"CGA:CGB7 -> LHCGR","headline":"Heterodimer CGB7 with CGA on LHCGR is supported only by database records, mostly for CGA; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CGA-LHCGR as a full agonist; pKd range 9.899999618530273 to 11.800000190734863 [DB:GtoPdb]. Reactome records LH receptor:LH complexes [DB:Reactome]. Cryo-EM structures of chorionic gonadotropin-LHCGR-Gs exist [DB:PDB 7FIG] [DB:PDB 7FII].","molecular_requirements":"Ligand is a CGA:CGB7 heterodimer; the records name CGA and LH or CG, not this specific beta gene; no CGB7 record shown.","affinity_potency":[],"species_and_systems":"Human; species of experiments not reported in our evidence.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Two pending rows, no curated paper. Database records are not specific to CGB7. BioGRID lists LHCGR-CGA affinity capture-western [DB:BioGRID].","key_references":[],"covers":["LR011153"]},"LR002342":{"pair":"CGB7 -> LHCGR","headline":"Single abstract-level paper on hCG/LH binding to LHR; no CGB7-specific evidence.","interaction_type":"direct binding","direction_and_effect":"hCG acts as an agonist at the LH receptor [PMID:12727981].","molecular_requirements":"Deleting exon 10 impairs LH but not hCG action; binding affinities of LH and hCG to wild-type and exon-10-deleted receptor were similar [PMID:12727981].","affinity_potency":[],"species_and_systems":"Human; stable COS-7 cells expressing LH receptor [PMID:12727981].","localisation_and_range":"Not reported in our evidence beyond the ligand flagged secreted [flag].","caveats":"One paper, abstract only; it concerns hCG and LH in general and not CGB7 specifically. No PDB or other database support listed for this pair. No affinity value in our evidence.","key_references":[{"PMID":"12727981","why":"LH and hCG binding to LHR wt and -ex10"}],"covers":["LR002342"]},"LR002351":{"pair":"CLEC4G -> PILRA","headline":"Database-asserted only: Reactome lists CLEC4G among PILRA binding partners; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond the Reactome binding reaction [DB:Reactome R-HSA-8862090].","molecular_requirements":"Reactome describes a single binding reaction: PILRA binds PIANP, COLLEC12 trimer, NPDC1, CLEC4G [DB:Reactome R-HSA-8862090].","affinity_potency":[],"species_and_systems":"Human (Reactome human entry); experimental system not reported in our evidence.","localisation_and_range":"PILRA is flagged both secreted and transmembrane receptor [flag]; CLEC4G not flagged secreted [flag].","caveats":"No paper passed curation: outcome counts show one 'different_entity' and one 'abstract_insufficient' row. The support rests on Reactome records citing three PMIDs (14970179, 21241660, 22396535), which we did not verify.","key_references":[],"covers":["LR002351"]},"LR002360":{"pair":"CLU -> TREM2","headline":"Clusterin/apoJ is a TREM2 ligand from a protein microarray screen with uptake assays; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CLU/APOJ was identified as a TREM2 ligand; wild-type TREM2 overexpression enhanced CLU uptake in heterologous cells; Trem2 knockout microglia showed reduced CLU internalization [PMID:27477018].","molecular_requirements":"Binding was abolished or reduced by disease-associated TREM2 mutations [PMID:27477018]. TYROBP/DAP12 role is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"Protein microarray, heterologous cells, Trem2-knockout microglia and human macrophages [PMID:27477018].","localisation_and_range":"Clusterin is flagged secreted [flag]; TREM2 is flagged both secreted and receptor [flag].","caveats":"Abstract only; no affinity given. UniProt and BioGRID cite the same paper [DB:UniProt Q9NZC2][DB:BioGRID 2593475]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"27477018","why":"TREM2 binds apolipoproteins including CLU; mutations reduce binding and uptake"}],"covers":["LR002360","LR005640"]},"LR000308":{"pair":"CNTF -> LIFR","headline":"CNTF signals via LIFR as one beta chain of a CNTFR/gp130/LIFR complex; functional evidence plus database records.","interaction_type":"functional only","direction_and_effect":"CNTF acts as an agonist; GtoPdb lists Agonist [DB:GtoPdb]. In cells, CNTF signalling was abolished by a LIFR mutant lacking the N-terminal cytokine binding domain, while LIF and OSM signalling was not [PMID:16051226].","molecular_requirements":"CNTF signals through a receptor complex of CNTFR with gp130 (IL6ST) and LIFR [PMID:10966616][PMID:16051226]. The LIFR N-terminal cytokine binding domain is required for CNTF but not LIF or OSM signalling [PMID:16051226]. UniProt says ligand binding to CNTFR induces dimerization of gp130 and LIFR [DB:UniProt]. A PDB structure has chains of CNTFR and LIFR [DB:PDB 8D74]; IntAct records electron microscopy and molecular sieving [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human proteins, overexpressing cells and receptor reconstitution [PMID:16051226][PMID:10966616]. Mouse pair is projected from human evidence.","localisation_and_range":"CNTF is flagged secreted [flag].","caveats":"Both confirmed papers are abstract-only. LIFR engagement requires CNTFR and gp130; direct CNTF-LIFR binding alone is not shown in our evidence.","key_references":[{"PMID":"16051226","why":"LIFR N-terminal domain needed for CNTF signalling"},{"PMID":"10966616","why":"CNTFR complex with gp130 and LIFR"}],"covers":["LR000308","LR003814"]},"LR000317":{"pair":"COL18A1 -> GPC1","headline":"Endostatin (collagen XVIII fragment) binds glypicans as a low-affinity, heparan sulfate-dependent receptor in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Alkaline phosphatase-tagged endostatin bound glypican-1 and glypican-4 overexpressed in NIH 3T3 cells; glypicans were identified as lower-affinity endostatin receptors, with antisense data suggesting they mediate endostatin activity [PMID:11336704]. The authors propose glypican acts as a presenting co-receptor passing endostatin to a high-affinity receptor [PMID:11336704]. Curator records agonist.","molecular_requirements":"Heparan sulfate chains are critical for binding; heparinase or salt treatment reduced binding, and GPI-linkage matters (PI-PLC reduces binding) [PMID:11336704]. The ligand acting is endostatin, the collagen XVIII fragment, not intact COL18A1 [PMID:11336704].","affinity_potency":[{"value":"Kd 200 pM","assay":"Scatchard analysis of AP-endostatin binding (lower-affinity site)","system":"cow pulmonary arterial endothelial (CPAE) cells","cite":"PMID:11336704"}],"species_and_systems":"Human and mouse endostatin tested; curator records human ligand and human GPC4 sequence. Binding quantified in cow endothelial cells and NIH 3T3 overexpressing cells; human and mouse pair rows partly ortholog-projected [PMID:11336704].","localisation_and_range":"Receptor is a GPI-anchored cell-surface proteoglycan [PMID:11336704] (entity flag lists it as secreted [flag]). Ligand is a secreted fragment, so action is paracrine or autocrine.","caveats":"Low affinity and glycan-mediated, so other heparan sulfate proteoglycans may bind similarly. The paper contrasts earlier work showing heparinase-resistant binding in situ [PMID:11336704]. Only one paper.","key_references":[{"PMID":"11336704","why":"Glypicans identified as low-affinity endostatin receptors"}],"covers":["LR000317","LR003823"]},"LR005114":{"pair":"COL18A1 -> PTPRS","headline":"Collagen XVIII binds chicken PTPsigma in vitro, dependent on heparan sulfate chains; one abstract-read paper in avian system.","interaction_type":"direct binding","direction_and_effect":"Collagen XVIII and agrin interact with high affinity with chicken cPTPsigma in vitro [PMID:11865065]. Effect on receptor signalling is not reported in our evidence.","molecular_requirements":"Binding depends entirely on the heparan sulfate chains of the ligand; the binding site maps to the first immunoglobulin-like domain of cPTPsigma [PMID:11865065].","affinity_potency":[],"species_and_systems":"Experiments used the avian orthologue cPTPsigma/CRYPalpha, not human or mouse PTPRS, so the human and mouse pairs are inferred [PMID:11865065].","localisation_and_range":"Ligand is a basal-lamina proteoglycan; receptor is a transmembrane phosphatase (entity flags list both as secreted [flag]).","caveats":"Glycan-mediated rather than protein-specific; other heparan sulfate proteoglycans would be expected to bind similarly (curator note). Avian species only; abstract-only read; no affinity value.","key_references":[{"PMID":"11865065","why":"HSPGs including collagen XVIII bind chicken PTPsigma"}],"covers":["LR001756","LR005114"]},"LR000326":{"pair":"COL1A1 -> ITGA11","headline":"Integrin alpha11beta1 binds collagen type I-Sepharose; one abstract-read cloning paper.","interaction_type":"direct binding","direction_and_effect":"Alpha11beta1 bound collagen type I-Sepharose in affinity binding [PMID:10464311]. Effect: not reported in our evidence.","molecular_requirements":"The binder shown is the alpha11beta1 heterodimer, not alpha11 alone; collagen I is the COL1A1/COL1A2 heterotrimer (curator note) [PMID:10464311].","affinity_potency":[],"species_and_systems":"Human fetal muscle cell integrin; abstract only [PMID:10464311].","localisation_and_range":"Receptor is a membrane integrin; collagen is matrix.","caveats":"Abstract-only read; no affinity; heterodimer evidence applied to a single chain.","key_references":[{"PMID":"10464311","why":"Cloning of alpha11 and binding of alpha11beta1 to collagen I"}],"covers":["LR000326","LR003832"]},"LR011009":{"pair":"COL1A1 -> ITGA3:ITGB1","headline":"Single abstract-only functional report; the paper names ITGB1 rather than ITGA3, so support for this complex is weak.","interaction_type":"functional only","direction_and_effect":"Fibroblast-derived COL1A1 activated AKT phosphorylation by binding to integrin beta1 (ITGB1) in ovarian cancer cells [PMID:32589888].","molecular_requirements":"The paper names ITGB1 only; the ITGA3 alpha subunit is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ovarian cancer cells; species not reported in our evidence [PMID:32589888].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract-only; assay_class functional_in_vitro. BioGRID record is for COL1A1-ITGB1 co-purification (PMID 2156854), not ITGA3 [DB:BioGRID]. Two other papers were judged abstract_insufficient.","key_references":[{"PMID":"32589888","why":"COL1A1 binds ITGB1 and activates AKT in ovarian cancer cells"}],"covers":["LR011009"]},"LR010613":{"pair":"COL3A1 -> MAG","headline":"Soluble MAG binds several collagens including type III in a 1987 solid-phase assay; promiscuous matrix binding.","interaction_type":"direct binding","direction_and_effect":"Soluble MAG binds several collagens (types G, I, II, III, IV, V, VI, IX) [PMID:2446864]. Effect not reported in our evidence.","molecular_requirements":"Both MAG forms bind heparin; heparan sulfate and dextran sulfate block binding to collagen G [PMID:2446864].","affinity_potency":[],"species_and_systems":"Adult mouse brain MAG with purified collagens [PMID:2446864].","localisation_and_range":"MAG flagged secreted and receptor [flag].","caveats":"Abstract read only. Reported Kd values were for collagens IX (5.7 X 10(-8) M) and IV (2.0 X 10(-7)), not type III. Whole-collagen assay cannot resolve the COL3A1 chain. BioGRID record: Reconstituted Complex [DB:BioGRID].","key_references":[{"PMID":"2446864","why":"MAG solid-phase binding to collagens"}],"covers":["LR010613"]},"LR000344":{"pair":"COL4A1 -> ITGA1","headline":"Collagen IV (alpha1/alpha2 chains) recognised by alpha1beta1 integrin in a structural study; abstract only.","interaction_type":"direct binding","direction_and_effect":"A collagen IV fragment contains the alpha1beta1 recognition site; modifying Arg and Asp residues abolished binding [PMID:8223488]. Database effect label is stimulatory.","molecular_requirements":"The binding site needs Arg(461) in alpha2(IV) and Asp(461) in alpha1(IV), so both COL4A1 and COL4A2 chains contribute [PMID:8223488]. The receptor is the alpha1beta1 heterodimer, ITGB1 being required as partner [PMID:8223488].","affinity_potency":[],"species_and_systems":"Purified type IV collagen fragments; ligand and receptor species not stated in our evidence [PMID:8223488].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; no affinity reported. The ITGA1 record stands for alpha1beta1; COL4A1 alone is not shown to be sufficient.","key_references":[{"PMID":"8223488","why":"Maps alpha1beta1 recognition site on collagen IV"}],"covers":["LR000344","LR003850"]},"LR000362":{"pair":"COL8A1 -> ITGA1","headline":"Antibody-blocking evidence that alpha1 integrin contributes to smooth muscle cell attachment to type VIII collagen; functional only.","interaction_type":"functional only","direction_and_effect":"Antibodies against alpha1 or alpha2 integrins reduced attachment of SMCs to type VIII collagen by 29% and 77%, respectively; anti-beta1 antibodies prevented attachment and migration [PMID:10666376]. Type VIII collagen signaled through integrins to stimulate MMP production [PMID:10666376].","molecular_requirements":"Beta1 integrin is implicated by antibody blocking; alpha1 and alpha2 were tested together as a pair of antibodies, so the effect of this chain alone is not separable in the evidence [PMID:10666376].","affinity_potency":[{"value":"29% and 77%","assay":"reduction of SMC attachment to type VIII collagen by anti-alpha1 or anti-alpha2 integrin antibodies, respectively","system":"smooth muscle cells","cite":"PMID:10666376"}],"species_and_systems":"Experiments used smooth muscle cells, with neointimal SMCs grown from rat [PMID:10666376]; the human and mouse pairs are ortholog-inferred from this evidence.","localisation_and_range":"Ligand flagged secreted [flag]; the paper describes matrix-deposited type VIII collagen [PMID:10666376].","caveats":"Abstract only; antibody blocking is indirect and does not show direct binding. A second confirmed paper exists but is not shown; one review-only and one abstract-insufficient row.","key_references":[{"PMID":"10666376","why":"Antibody blocking implicates alpha1/alpha2/beta1 integrins in SMC attachment to type VIII collagen"}],"covers":["LR000362","LR003868"]},"LR002432":{"pair":"COMP -> ITGA7","headline":"COMP pulls down alpha7 integrin and alpha7 blockade reduces VSMC adhesion to COMP; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Alpha7 integrin co-immunoprecipitated with COMP in rat VSMCs and vessels; neutralizing antibody or siRNA against alpha7 inhibited VSMC adhesion to COMP, so alpha7beta1 is proposed as a potential COMP receptor. Blocking alpha7 abolished COMP's effect on preserving the contractile phenotype [PMID:20019333].","molecular_requirements":"The authors name alpha7beta1 as the receptor, implying a beta1 partner; subunit requirement is otherwise not reported in our evidence [PMID:20019333].","affinity_potency":[],"species_and_systems":"Rat vascular smooth muscle cells and vessels; human pair, mouse pair ortholog-inferred [PMID:20019333].","localisation_and_range":"COMP is a vascular extracellular matrix protein per the abstract and carries a secreted flag [flag][PMID:20019333].","caveats":"Described only as a potential receptor; co-IP and adhesion blockade, no purified binding or affinity. Abstract only; evidence is rat, projected to human.","key_references":[{"PMID":"20019333","why":"Co-IP and adhesion blockade implicate alpha7beta1 as COMP receptor"}],"covers":["LR002432","LR005711"]},"LR000371":{"pair":"CORT -> SSTR5","headline":"Cortistatin binds SSTR5 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 10.33","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst5 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.5-10.2","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR5 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID]; a PDB structure 8X8L has chains for both proteins [DB:PDB 8X8L].","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000371","LR003877"]},"LR002441":{"pair":"CRP -> FCAR","headline":"CRP binding to Fc\u03b1RI was seen by SPR but was weak, the lowest tier in a single study.","interaction_type":"direct binding","direction_and_effect":"CRP bound Fc\u03b1RI with lower relative affinity than Fc\u03b3RIa, Fc\u03b3RIIa/b and Fc\u03b3RIIIa; binding was 'particularly low' and in the same tier as Fc\u03b3RIIIb [PMID:33790888]. No functional effect through Fc\u03b1RI is reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond a single receptor chain.","affinity_potency":[],"species_and_systems":"Human proteins; SPR array of recombinant human Fc receptors [PMID:33790888].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Single study; binding too weak to quantify a KD for Fc\u03b1RI in the excerpts we have. The functional blocking experiments concern Fc\u03b3Rs, not Fc\u03b1RI [PMID:33790888]. No database support.","key_references":[{"PMID":"33790888","why":"SPR profiling of CRP against all human Fc\u03b3Rs and Fc\u03b1RI"}],"covers":["LR002441"]},"LR008012":{"pair":"CSF1:IL34 -> CSF1R","headline":"A putative CSF1/IL-34 heteromer is reported to act on CSF1R, resting on one abstract-read paper plus database complexes.","interaction_type":"functional only","direction_and_effect":"Simultaneous M-CSF and IL-34 gave a specific M-CSFR activation pattern with higher tyrosine phosphorylation at low concentrations, and additive effects on proliferation or viability [PMID:26095744]. M-CSF was reported to bind IL-34 by BIAcore, with a proximity ligation assay confirming the cytokine interaction; docking predicted a heteromer [PMID:26095744].","molecular_requirements":"The heteromer is proposed to contain both cytokines; whether a mixed dimer, rather than the two separate homodimers, acts on CSF1R is not settled in our evidence.","affinity_potency":[],"species_and_systems":"Human cells expressing M-CSFR; recombinant cytokines [PMID:26095744].","localisation_and_range":"Both ligands are annotated secreted; IL-34 is flagged non-transmembrane and CSF1 as transmembrane as well [flag].","caveats":"Single paper, read as abstract only. Its binding data concern the cytokines with each other, not the heteromer with CSF1R. Curators classed the assay as direct_binding, but the evidence sentence describes only IL-34 and M-CSFR in general terms. Reactome lists a IL34:CSF1:CSF1R complex citing this paper, and other Reactome, PDB and IntAct records cover CSF1 and IL-34 separately with CSF1R [DB:Reactome] [DB:PDB 4DKD]. GtoPdb lists IL34-CSF1R as agonist [DB:GtoPdb].","key_references":[{"PMID":"26095744","why":"Only paper reporting an M-CSF/IL-34 heteromer acting on M-CSFR"}],"covers":["LR008012"]},"LR002450":{"pair":"CST3 -> LRP2","headline":"Cystatin C binds megalin (LRP2) directly and is endocytosed via it; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Cystatin C binds directly to megalin in a Ca-dependent manner by quartz-crystal microbalance; it is endocytosed specifically via megalin in L2 cells, and kidney-specific megalin knockout mice show megalin mediates proximal tubular uptake [PMID:17462596]. Megalin acts as an endocytic (clearance) receptor.","molecular_requirements":"Calcium is required [PMID:17462596]; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Quartz-crystal microbalance with unspecified species; rat L2 cells; kidney-specific megalin knockout mice [PMID:17462596]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"CST3 flagged secreted [flag]; uptake occurs in proximal tubule cells [PMID:17462596]. UniProt also records the interaction [DB:UniProt].","caveats":"One paper, read as abstract only; no affinity reported in our evidence.","key_references":[{"PMID":"17462596","why":"QCM binding plus megalin-dependent endocytosis of cystatin C"}],"covers":["LR002450","LR005726"]},"LR000380":{"pair":"CTF1 -> IL6ST","headline":"CTF1 signals through gp130 (IL6ST) with LIFR; support is functional blockade in canine cells plus database records.","interaction_type":"functional only","direction_and_effect":"Exogenous CT-1 stimulated thymidine and proline incorporation in cardiac fibroblasts; blockade of gp130 or LIF receptor inhibited CT-1-stimulated growth, so CT-1 is an agonist [PMID:11834704]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"The receptor is the gp130/LIFR complex; gp130 alone is not shown sufficient in our evidence [PMID:11834704]. Reactome lists an OSM, LIF, CTF1 receptor complex binding gp130 [DB:Reactome R-HSA-6783524].","affinity_potency":[],"species_and_systems":"Cultured adult canine cardiac fibroblasts, not human or mouse; the human and mouse pairs are ortholog-inferred [PMID:11834704].","localisation_and_range":"CTF1 flagged secreted; IL6ST flagged transmembrane [flag]; secreted cytokine acting on cell-surface receptor.","caveats":"Evidence is receptor blockade, not binding; abstract only; the receptor identity is background in the study. IL6ST alone inherits complex-level evidence.","key_references":[{"PMID":"11834704","why":"CT-1 growth effect blocked by gp130 or LIFR blockade in canine fibroblasts"}],"covers":["LR000380","LR003886"]},"LR005123":{"pair":"CX3CL1 -> ITGB3","headline":"Direct binding of CX3CL1 chemokine domain to integrin alphavbeta3 (beta3 chain) is reported, with a sub-nanomolar K(D) and integrin activation without CX3CR1.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(v)beta(3) at K(D) of 3.0 \u00d7 10(-10) M in 1 mM Mn(2+) [PMID:23125415]. FKN-CD activated recombinant alphavbeta3 in cell-free conditions, and the integrin-binding-defective mutant K36E/R37E did not [PMID:24789099]. UniProt describes ITGAV:ITGB3 as a coreceptor in CX3CR1-dependent signalling [DB:UniProt].","molecular_requirements":"Binding was tested on the alphavbeta3 heterodimer; the specificity loop of beta3 is described as involved in recognition of FKN-CD in the full-text excerpts, via a beta1 chimera [PMID:23125415]. A ternary complex with CX3CR1 is reported for signalling [PMID:24789099].","affinity_potency":[{"value":"Kd 3.0 x 10(-10) M","assay":"direct binding, ELISA-type, 1 mM Mn(2+)","system":"human FKN-CD with recombinant soluble alphavbeta3","cite":"PMID:23125415"}],"species_and_systems":"Human ligand and human receptor, recombinant protein and K562/CHO cells. Mouse pair ortholog-inferred. IntAct has co-IP, ELISA and pull-down records [DB:IntAct].","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; membrane-bound fractalkine also bound the integrins [PMID:23125415].","caveats":"Both papers are from the same group. Authors state the result contradicts earlier studies that found no direct integrin binding [PMID:23125415]. Receptor is one chain of a heterodimer; beta3 alone not tested.","key_references":[{"PMID":"23125415","why":"Direct binding and co-receptor model"},{"PMID":"24789099","why":"Integrin activation independent of CX3CR1"}],"covers":["LR001765","LR005123"]},"LR000407":{"pair":"CXCL1 -> CXCR2","headline":"CXCL1 (GROalpha) is a well-supported agonist of CXCR2, with binding and potency measured in recombinant human-receptor systems.","interaction_type":"direct binding","direction_and_effect":"Agonist at CXCR2: GROalpha bound CXCR2 with high affinity and CXCR2 responded to GROalpha with calcium and chemotaxis readouts [PMID:10188995][PMID:8137938][PMID:8702798]. CXCR2 is selective for IL-8, GROalpha and NAP-2, whereas CXCR1 is selective only for IL-8 [PMID:8550564]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single-chain GPCR; no co-receptor or extra subunit is reported in our evidence. PDB lists structures with the two proteins [DB:PDB 8XWA][DB:PDB 8XWV].","affinity_potency":[{"value":"pKi 9.66","assay":"radioligand competition binding","system":"recombinant CHO cells expressing HA-tagged CXCR2","cite":"PMID:10188995"},{"value":"Kd approximately 2 nM","assay":"MGSA (GROalpha) binding to IL-8R-B","system":"human receptor expressed in mammalian cells","cite":"PMID:1379593"},{"value":"EC50 5 nM","assay":"calcium flux potency","system":"receptor-transfected HEK293 cells","cite":"PMID:8702798"}],"species_and_systems":"Human ligand and human receptor, in transfected cells (CHO, HEK293, Jurkat) [PMID:10188995][PMID:8702798][PMID:8137938]. In vivo evidence is not reported in our evidence.","localisation_and_range":"CXCL1 is flagged secreted and CXCR2 transmembrane [flag]; this implies a paracrine soluble ligand acting on a cell-surface receptor.","caveats":"Most confirming papers were read as abstracts only. The same dossier shows CXCR1 binds GROalpha only weakly, so do not infer CXCR1 usage [PMID:1379593].","key_references":[{"PMID":"10188995","why":"CXCR2 binding and signalling by GROalpha in CHO cells"},{"PMID":"8702798","why":"Potency rank order of ELR+ chemokines at CXCR2"},{"PMID":"1379593","why":"GROalpha affinity at the two IL-8 receptors"}],"covers":["LR000407"]},"LR000416":{"pair":"CXCL6 -> CXCR1","headline":"Well supported: CXCL6 is an agonist at CXCR1 by binding and signalling in human and mouse receptor assays, with GtoPdb and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Agonist: GCP-2/CXCL6 induced calcium rise in CXCR1 cells, minimum effective concentration 3 nM [PMID:9692902]; GtoPdb full agonist [DB:GtoPdb]. Mouse CXCR1 is engaged by mouse and human GCP-2 by binding, GTPgammaS exchange and chemotaxis [PMID:17197447]. Neutrophil data: only IL-8 and GCP-2 bind CXCR-1 with high affinity [PMID:10593335].","molecular_requirements":"No co-receptor requirement reported. Reactome lists CXCR1 binding CXCL6 and CXCL8 [DB:Reactome R-HSA-373791].","affinity_potency":[{"value":"3 nM","assay":"minimal effective concentration, calcium rise","system":"CXCR1-transfected cells","cite":"PMID:9692902"}],"species_and_systems":"Human CXCR1 transfectants and neutrophils [PMID:9692902][PMID:10593335]; mouse CXCR1 with human and mouse GCP-2 [PMID:17197447].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"Abstract-only reads. The 'pKi 7.0' attached to PMID:9692902 in curation is not stated in the abstract and is not reported here.","key_references":[{"PMID":"9692902","why":"CXCL6 potency at CXCR1 and CXCR2"},{"PMID":"17197447","why":"CXCL6 engages mouse CXCR1"},{"PMID":"10593335","why":"High-affinity CXCR-1 binding on neutrophils"}],"covers":["LR000416"]},"LR000425":{"pair":"DCN -> EGFR","headline":"Decorin binds the EGFR ectodomain directly; reported both as an activator and as an EGFR antagonist, with a measured Kd.","interaction_type":"direct binding","direction_and_effect":"Reports differ: decorin induced EGFR dimerisation, autophosphorylation and MAPK/p21-driven growth suppression [PMID:9988678]; a later paper labels it an antagonist competing in part with EGF [PMID:12105206].","molecular_requirements":"Decorin binds the EGFR L2 ligand-binding domain, requires decorin leucine-rich repeat 6, and His394-Ile402 is essential for both decorin and EGF while K465 is needed for EGF but not decorin [PMID:12105206]. Binding is via the decorin protein core [PMID:9988678].","affinity_potency":[{"value":"Kd~87nM","assay":"radioligand binding","system":"EGFR ectodomain or purified EGFR","cite":"PMID:9988678"}],"species_and_systems":"Human systems: squamous carcinoma cells, cell-free purified EGFR, expression cloning and yeast two-hybrid [PMID:9988678] [PMID:12105206].","localisation_and_range":"Decorin is flagged secreted; EGFR transmembrane receptor [flag]. Paracrine/matrix ligand by annotation.","caveats":"Both papers read as abstracts. Agonist versus antagonist labelling conflicts. BioGRID lists reconstituted complex and two-hybrid records [DB:BioGRID 288891].","key_references":[{"PMID":"9988678","why":"Radioligand binding, Kd~87nM, EGFR activation"},{"PMID":"12105206","why":"Epitope mapping on EGFR"}],"covers":["LR000425","LR003922"]},"LR005132":{"pair":"DCN -> TLR4","headline":"Decorin acts as a TLR2/TLR4 ligand in macrophages in one paper; functional evidence with a pull-down in HEK cells.","interaction_type":"functional only","direction_and_effect":"Decorin activated MAPKs p44/p42 and p38 and increased TNFalpha and IL-12p70 release in a TLR2- and TLR4-dependent manner; binding assays in HEK cells indicated decorin could pull down TLR2 and TLR4 [PMID:22087031].","molecular_requirements":"TLR2 and TLR4 both implicated; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse macrophages, septic and tumour mouse models; HEK cells expressing TLR4 [PMID:22087031]. Human pair is ortholog-projected from the mouse data.","localisation_and_range":"Decorin flagged secreted; TLR4 flagged receptor [flag].","caveats":"Single paper, no affinity; same evidence as DCN-TLR2 [PMID:22087031].","key_references":[{"PMID":"22087031","why":"Decorin as endogenous TLR2/TLR4 ligand"}],"covers":["LR001775","LR005132"]},"LR000434":{"pair":"DEFB4B -> CCR6","headline":"Human beta-defensin chemotaxis through CCR6 and LARC displacement, plus GtoPdb agonist record; abstract-level.","interaction_type":"functional only","direction_and_effect":"Human beta-defensin was selectively chemotactic for CCR6-transfected cells, sensitive to pertussis toxin and to anti-CCR6 antibodies, and displaced iodinated LARC (CCL20) from CCR6-transfected cells [PMID:10521347]. GtoPdb lists a full agonist [DB:GtoPdb]; UniProt also records the ligand-receptor link [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human CCR6-transfected cells [PMID:10521347].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"The 1999 abstract refers to 'human beta-defensin' without naming DEFB4B, and the locus is not distinguished from DEFB4A. Abstract only. No affinity reported; GtoPdb gives none [DB:GtoPdb]. The second paper (20483750) mentions CCR6 only as background [PMID:20483750].","key_references":[{"PMID":"10521347","why":"Human beta-defensin chemotaxis via CCR6"}],"covers":["LR000434"]},"LR000443":{"pair":"DKK1 -> LRP6","headline":"Very well supported direct, high-affinity binding with crystal structures; DKK1 inhibits Wnt signalling through LRP6.","interaction_type":"direct binding","direction_and_effect":"Dkk1 is a high-affinity ligand for LRP6 and inhibits Wnt signalling by preventing Wnt-induced Fz-LRP6 complex formation, binding neither Wnt nor Fz [PMID:11448771]. LRP6 is a specific high-affinity receptor for Dkk1 and Dkk2 [PMID:11357136]. Dkk1 competes with Wnt3a and Wnt9b for LRP6 binding [PMID:20093360].","molecular_requirements":"A single Dkk1 molecule can bind both LRP6(1-2) and LRP6(3-4); the C-terminal domain binds LRP6(3-4) and the N-terminal domain binds LRP6(1-2) [PMID:22000856]. Dkk1 binding is independent of Fz [PMID:11433302]. Reconstituted complex and X-ray records exist [DB:BioGRID] [DB:IntAct].","affinity_potency":[{"value":"K(D) = 0.39 nM","assay":"cell surface binding with [125I] Dkk-1","system":"human Dkk-1, cell surface site","cite":"PMID:11433302"},{"value":"Kd of 67 nM","assay":"isothermal titration calorimetry","system":"Dkk1 with LRP6(3-4), 1:1 complex","cite":"PMID:22000856"}],"species_and_systems":"Recombinant proteins in vitro: human LRP6 ectodomain and mouse Fz8 CRD in insect cells [PMID:20093360], Xenopus embryos [PMID:11357136]; cell-based assays elsewhere. Mouse pair is ortholog-inferred.","localisation_and_range":"DKK1 is flagged secreted; LRP6 as a transmembrane receptor [flag].","caveats":"The two affinity values come from different assays and constructs, so they are not directly comparable. Most papers were read as abstracts. Two review-only and two abstract-insufficient rows are not shown.","key_references":[{"PMID":"11448771","why":"Dkk-1 is a high-affinity LRP6 ligand and blocks Fz-LRP6 complex"},{"PMID":"11433302","why":"K(D) = 0.39 nM binding; LRP6 is the receptor"},{"PMID":"22000856","why":"Structure and Kd 67 nM for Dkk1-LRP6(3-4)"}],"covers":["LR000443","LR003935"]},"LR000452":{"pair":"DLL4 -> NOTCH2","headline":"Supported by an ELISA binding assay and functional assays; DLL4 activates NOTCH2 less than NOTCH1.","interaction_type":"direct binding","direction_and_effect":"Dll4 binding to Notch2 EGF1-12 was recapitulated in an ELISA-based assay [PMID:22842086]. In cell assays DLL4 activates NOTCH2 less than NOTCH1 [PMID:30289388]; DLL4-NOTCH1 activation was more than twice that of DLL4-NOTCH2 without Fringes, and LFNG enhanced NOTCH2 activation by DLL1 and DLL4 [PMID:32820046].","molecular_requirements":"Notch2 EGF repeats 1-12 sufficed for Dll4 binding in the ELISA [PMID:22842086]. Reactome lists DLL4 binding NOTCH2 and a DLL4:NOTCH2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human and mouse ligand/receptor material used in the ELISA and cell assays; the human record is ortholog-inferred, the mouse record is not [PMID:22842086][PMID:30289388].","localisation_and_range":"Both partners annotated transmembrane, DLL4 not secreted [flag].","caveats":"Abstracts only for two of three papers. The antibody paper was a methods study; the binding assay was used as a tool, not characterised as a primary finding [PMID:22842086]. Affinity not reported in our evidence.","key_references":[{"PMID":"22842086","why":"ELISA binding of Notch2 EGF1-12 to Dll4"},{"PMID":"30289388","why":"Ectodomain-dependent DLL4 selectivity"},{"PMID":"32820046","why":"Fringe and ligand effects on NOTCH2"}],"covers":["LR000452","LR003944"]},"LR005141":{"pair":"DSC1 -> DSG3","headline":"Heterophilic DSC1-DSG3 binding inferred from a family-wide study; no database records.","interaction_type":"direct binding","direction_and_effect":"All Dsgs form adhesive dimers with all Dscs with characteristic affinities, which includes DSC1:DSG3 [PMID:27298358].","molecular_requirements":"Strand-swap binding; opposite-charge attraction promotes Dsg:Dsc pairing [PMID:27298358]. Dsg3 crystal structure was reported [PMID:27298358].","affinity_potency":[],"species_and_systems":"Human ectodomains; mouse record ortholog-inferred [PMID:27298358].","localisation_and_range":"Annotated transmembrane [flag]; trans-cellular adhesion [PMID:27298358].","caveats":"Abstract read only; the pair is covered by a family-level statement. No pair-specific affinity and no database records.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc binding"}],"covers":["LR001785","LR005141"]},"LR005150":{"pair":"DSC3 -> DSG4","headline":"DSC3 -> DSG4: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001794","LR005150"]},"LR002504":{"pair":"DSG3 -> DSC2","headline":"Heterophilic DSG3:DSC2 adhesive binding supported by one abstract-only structural/biophysical paper.","interaction_type":"direct binding","direction_and_effect":"Per the paper, all desmogleins form adhesive dimers with all desmocollins, including DSG3:DSC2; this is an adhesive pair, not a classical agonist signal [PMID:27298358].","molecular_requirements":"Binding is via a strand-swap mechanism between ectodomains; opposite-charge attraction promotes heterophilic Dsg:Dsc binding while same-charge repulsion blocks Dsg:Dsg and Dsc:Dsc pairing [PMID:27298358]. Crystal structures were of Dsg2/Dsg3 and Dsc1/Dsc2 ectodomains.","affinity_potency":[],"species_and_systems":"Human proteins; solution biophysics and coated-bead aggregation. Mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Both partners are flagged as non-secreted receptors, so this is membrane-bound, contact-dependent (juxtacrine) adhesion [flag].","caveats":"Read as abstract only. The paper covers a 25-pair Dsg:Dsc matrix; a DSG3:DSC2-specific affinity is not reported in our evidence.","key_references":[{"PMID":"27298358","why":"Systematic Dsg:Dsc heterophilic binding with crystal structures"}],"covers":["LR002504","LR005772"]},"LR000461":{"pair":"EDN1 -> EDNRB","headline":"Endothelin-1 binds and activates the ETB receptor; supported by binding papers read as abstracts plus structures.","interaction_type":"direct binding","direction_and_effect":"ET-1 is an agonist of ETB: iodinated ET-1 binds ETB-transfected cells and is internalised to lysosomes [PMID:12972292]; ET-1 and ET-3 had approximately equal potencies in displacing 125I-ET-1 and in eliciting [Ca2+]i transients [PMID:1713452]. Ligand effect is flagged Stimulatory in the interaction record.","molecular_requirements":"Not reported in our evidence beyond the single receptor; GtoPdb/Reactome-style complex records list EDN1, EDN3:EDNRB [DB:Reactome R-HSA-9825404].","affinity_potency":[],"species_and_systems":"Human cDNA expressed in COS cells and transfected cells [PMID:1713452][PMID:12972292]; the mouse pair is ortholog-inferred, not tested in our evidence. Structures with both chains exist [DB:PDB 5GLH][DB:PDB 8IY5]; an IntAct scintillation proximity assay is also listed [DB:IntAct].","localisation_and_range":"ET-1 is annotated secreted and ETB transmembrane [flag], so a paracrine/endocrine ligand acting on a membrane receptor.","caveats":"All three papers were read as abstracts only. One is mainly a receptor-trafficking study [PMID:12972292]. Endothelins are non-selective at ETB, so this receptor does not discriminate ET-1 from ET-3 [PMID:1713452].","key_references":[{"PMID":"1713452","why":"cloned human ETB, binding and Ca2+ response"},{"PMID":"2175397","why":"original cloning of the non-isopeptide-selective receptor"},{"PMID":"12972292","why":"ET-1 binding and lysosomal fate of ETB"}],"covers":["LR000461","LR003952"]},"LR000470":{"pair":"EFNA1 -> EPHA4","headline":"Ephrin-A1 binds EphA4 in rat tissue and drives EphA4 signalling in human cells; plus database binding records.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 selectively bind EphA4 but not EphA7 in striatal lysates [PMID:10366629]; ephrin-A1 stimulation induces EphA4-mediated phosphorylation of Vsm-RhoGEF and RhoA activation [PMID:12775584]. Stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat striatal tissue binding [PMID:10366629]; human cells [PMID:12775584]. Human pair ortholog-inferred, mouse not. Database records: BioGRID affinity capture-western [DB:BioGRID], IntAct ELISA and surface plasmon resonance [DB:IntAct].","localisation_and_range":"EFNA1 annotated secreted and transmembrane, EPHA4 transmembrane [flag].","caveats":"Most papers read as abstracts only. A third paper reads B61 binding as decreasing across receptors but the EphA4 value is not in our excerpt [PMID:8755474]. No affinity values reported.","key_references":[{"PMID":"10366629","why":"ephrin-A1 binds EphA4 in rat striatum"},{"PMID":"12775584","why":"ephrin-A1 via EphA4 activates RhoA"}],"covers":["LR000470","LR003961"]},"LR002513":{"pair":"EFNA3 -> EPHA10","headline":"Supported only by a UniProt statement that EPHA10 binds EFNA3; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 'Binds to EFNA3, EFNA4 and EFNA5' [DB:UniProt]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental species or system reported in our evidence; the dossier covers human and a mouse pair projected from human (ortholog-inferred).","localisation_and_range":"EFNA3 is flagged membrane-bound (transmembrane) [flag]; EPHA10 is flagged secreted [flag]. These are annotation flags only.","caveats":"No paper-level evidence; both judged papers were review-only. Rests on a single database annotation.","key_references":[],"covers":["LR002513","LR005781"]},"LR002522":{"pair":"EFNA5 -> EPHA10","headline":"Only a UniProt note that EPHA10 binds EFNA5; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 'Binds to EFNA3, EFNA4 and EFNA5' [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; EPHA10 flagged secreted [flag].","caveats":"Both judged papers were review-only; a single database annotation supports it.","key_references":[],"covers":["LR002522","LR005790"]},"LR000506":{"pair":"EFNA5 -> EPHA8","headline":"Functional evidence only: EphA8-driven adhesion depends on ephrin A binding; EFNA5 itself is not named as the tested ligand.","interaction_type":"functional only","direction_and_effect":"EphA8 expression enhanced cell adhesion to fibronectin via integrins, and this required ephrin A binding to the EphA8 extracellular domain [PMID:11416136]. Annotated effect is stimulatory.","molecular_requirements":"Adhesion needed the EphA8 extracellular domain plus the juxtamembrane segment, but not kinase activity (a kinase-inactive mutant still promoted attachment) [PMID:11416136].","affinity_potency":[],"species_and_systems":"NIH 3T3 and HEK293 cells; ligand and receptor species not specified. The pair is listed for human (projected from ortholog evidence) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Read from the abstract only. 'Ephrin A' is not resolved to EFNA5; ephrin A5-Fc was used only to strip endogenous ligands from cells [PMID:11416136]. No binding data in our evidence.","key_references":[{"PMID":"11416136","why":"EphA8 adhesion depends on ephrin A binding to the ectodomain"}],"covers":["LR000506","LR003997"]},"LR000515":{"pair":"EFNB2 -> EPHA3","headline":"Old cloning paper reports LERK-5 (ephrin-B2) as a ligand for hek and elk with receptor phosphorylation; BioGRID lists reconstituted complexes.","interaction_type":"direct binding","direction_and_effect":"LERK-5 is a ligand for both elk and hek and induces receptor phosphorylation [PMID:8559144]. Annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and murine LERK-5 cDNAs were isolated (97% amino acid identity) [PMID:8559144]. Pair listed for human and mouse, both ortholog-inferred. BioGRID: reconstituted complex [DB:BioGRID].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). The receptor is also flagged secreted [flag].","caveats":"Abstract only; no affinity. The hek/elk to EPHA3/EPHB1 mapping is curator-made; the same sentence supports two pairs. Another judged paper was abstract_insufficient.","key_references":[{"PMID":"8559144","why":"LERK-5 cloned as ligand for hek and elk"}],"covers":["LR000515","LR004006"]},"LR004007":{"pair":"EFNB2 -> EPHA4","headline":"Cross-class pair with ELISA binding, rat neurite-repulsion data and structures (PDB, IntAct).","interaction_type":"direct binding","direction_and_effect":"Ephrin-B2 Fc bound EphA4, which can bind both A and B class ephrins [PMID:22568954]. In rat spiral ganglion explants, anti-ephrin-B2 or anti-ephrin-B3 antibodies each reduced repulsion by an EphA4 stripe; used together neurites crossed with no repulsion [PMID:12761826]. Annotated stimulatory.","molecular_requirements":"Ephrin-B2 and ephrin-B3 are redundant ligands for EphA4 in that system [PMID:12761826].","affinity_potency":[],"species_and_systems":"ELISA with Fc proteins, species unspecified [PMID:22568954]; rat neonatal explants [PMID:12761826]. Pair listed for human (ortholog-inferred) and mouse. Structures: PDB 2WO2, 3GXU [DB:PDB 2WO2] [DB:PDB 3GXU].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No numeric affinity in our evidence (ELISA 'apparent KD' not given as a value). ELISA quote was browser-read and unverified. IntAct has NMR and X-ray records [DB:IntAct].","key_references":[{"PMID":"22568954","why":"ELISA: ephrin-B2 Fc binds EphA4"},{"PMID":"12761826","why":"Ephrin-B2/B3 mediate EphA4 repulsion in rat explants"}],"covers":["LR000516","LR004007"]},"LR004016":{"pair":"EFNB3 -> EPHA4","headline":"Established pair with genetic and functional evidence in rodents; structures and binding records in databases.","interaction_type":"direct binding","direction_and_effect":"Lateral thalamic explants (EphA4+) had axonal growth inhibited on ephrin-B3 membranes, medial ones did not [PMID:12383247]. Mice lacking EphA4 or ephrinB3 lose left-right limb alternation and show synchrony [PMID:12649481]. Annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat brain explants [PMID:12383247]; mouse knockouts [PMID:12649481]. Pair listed for human (ortholog-inferred) and mouse. PDB 4BKF; BioGRID and IntAct records [DB:PDB 4BKF] [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"The rat explant result is correlative; EphA4 was not blocked [PMID:12383247]. The knockout paper does not measure binding [PMID:12649481]. Abstract level.","key_references":[{"PMID":"12649481","why":"EphA4 and ephrinB3 knockouts lose limb alternation"},{"PMID":"12383247","why":"Ephrin-B3 inhibits EphA4+ thalamic axons"}],"covers":["LR000525","LR004016"]},"LR000533":{"pair":"EGF -> ERBB3","headline":"Native EGF does not bind ERBB3 alone in our evidence; the paper judged is evidence against.","interaction_type":"conflicting","direction_and_effect":"EGF gains high affinity for ErbB-2/ErbB-3 only after N-terminal replacement by NRG-1 or TGF-alpha sequences, and such chimeras weakly bind ErbB-3 alone [PMID:12093292].","molecular_requirements":"ErbB-3 alone is not enough for wild-type EGF; ErbB-2/ErbB-3 heterodimers are involved only with engineered variants [PMID:12093292].","affinity_potency":[],"species_and_systems":"Human cells and phage-display variants [PMID:12093292].","localisation_and_range":"EGF is secreted and ERBB3 is transmembrane [flag].","caveats":"Two pair_absent rows, plus 4 abstract_insufficient and 2 review_only rows not shown. The BioGRID record rests on the same paper that curators judged as negative [DB:BioGRID].","key_references":[{"PMID":"12093292","why":"Native EGF does not bind ErbB-3; engineered variants do"}],"covers":["LR000533","LR004024"]},"LR001802":{"pair":"ENHO -> GPR19","headline":"Adropin (ENHO) activates GPR19 in one abstract-only paper that confirms an earlier report; GtoPdb lists it as agonist.","interaction_type":"functional only","direction_and_effect":"Adropin-mediated GPR19 activation activates MAPK/ERK1/2, which the paper reports as essential for E-cadherin upregulation in breast cancer cells; adropin is described as an endogenous ligand, agonist [PMID:28476646][DB:GtoPdb].","molecular_requirements":"Subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor recorded [PMID:28476646]; the human pair is ortholog-inferred and a mouse pair is also listed. Overexpression in breast cancer cells.","localisation_and_range":"ENHO is flagged secreted and GPR19 as a receptor [flag]; range is not described in the paper text we hold.","caveats":"Abstract only; the paper confirms a previous report rather than showing binding, so evidence is functional. GtoPdb lists pEC50 as the affinity unit but no value is in our dossier [DB:GtoPdb].","key_references":[{"PMID":"28476646","why":"Confirms adropin as GPR19 ligand and shows ERK1/2 activation"}],"covers":["LR001802","LR005158"]},"LR002540":{"pair":"EPHA2 -> EFNA1","headline":"EPHA2-EFNA1 is well supported by structure and binding databases, but no curated paper was verified in this dossier.","interaction_type":"direct binding","direction_and_effect":"UniProt states EFNA1 activates EPHA2, regulating migration, adhesion, proliferation and angiogenesis [DB:UniProt]. Structures of the EphA2-ephrin-A1 complex exist [DB:PDB 3CZU]. BioGRID lists affinity capture-MS and -Western [DB:BioGRID]; IntAct lists x-ray crystallography and coimmunoprecipitation [DB:IntAct].","molecular_requirements":"Subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; PDB 3CZU is titled as a human ephrin A2-ephrin A1 complex [DB:PDB 3CZU].","localisation_and_range":"EPHA2 is flagged non-secreted; EFNA1 secreted [flag], likely reflecting a soluble form but not confirmed here. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Evidence is database records only; four review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002540","LR005808"]},"LR002603":{"pair":"EPHB6 -> EPHB2","headline":"Receptor-receptor heterodimerisation of EPHB6 with EPHB2 in breast cancer cells, abstract only; not a classical ligand-receptor binding.","interaction_type":"functional only","direction_and_effect":"The paper reports that EPHB6, a kinase-deficient receptor, interacts with EPHB2 in mammalian cells (within-class B-type heterodimer), and proposes that EPHB6 suppresses tumour invasiveness by sequestering kinase-sufficient oncogenic EPH receptors [PMID:21737611]. The curator labels this antagonist. EPHB6 does not interact with EPHA10 [PMID:21737611].","molecular_requirements":"Not reported beyond the two partners; EPHB6 is described as kinase-deficient [PMID:21737611].","affinity_potency":[],"species_and_systems":"Human breast carcinoma cell lines, mammalian cell co-expression; abstract only [PMID:21737611].","localisation_and_range":"EPHB6 carries secreted and transmembrane flags; EPHB2 is transmembrane-flagged [flag]. Heterodimerisation is within the membrane (cis or on the same cell); range is not reported.","caveats":"Abstract-only reading. This is a receptor-receptor association, so a ligand-to-receptor direction is not shown. The BioGRID record is Affinity Capture-Western [DB:BioGRID 3496525]. Direct physical binding is not distinguished from complex formation in our evidence.","key_references":[{"PMID":"21737611","why":"EPHB6 heterodimerises with EPHB2 in breast carcinoma cell lines."}],"covers":["LR002603","LR005871"]},"LR010802":{"pair":"EREG -> EGFR:ERBB2","headline":"Epiregulin binds EGFR directly, but the EGFR:ERBB2 complex is only partly supported; ERBB2 itself was not bound.","interaction_type":"direct binding","direction_and_effect":"[125I]epiregulin directly bound EGFR but not ErbB-2 or ErbB-3 in human breast carcinoma lines [PMID:9419975]. Epiregulin still stimulated tyrosine phosphorylation of all four ErbB receptors, with the main signal through ErbB-4 and/or EGFR [PMID:9419975].","molecular_requirements":"Binding evidence is for the EGFR chain only; ErbB2 phosphorylation without direct binding suggests activation by heterodimerisation, which the abstract does not test. A structure PDB 8HGP is mentioned for EREG with EGFR and HER2 chains (on the EREG-HER2 pair) [DB:PDB 8HGP].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, four human breast carcinoma lines [PMID:9419975].","localisation_and_range":"Both partners annotated transmembrane [flag]; secreted form of EREG also flagged.","caveats":"Abstract-only. In a CCC tool scoring the complex by its weakest subunit, ERBB2 has no direct binding support here. Affinity not reported.","key_references":[{"PMID":"9419975","why":"EGFR bound directly, ErbB-2 explicitly not bound"}],"covers":["LR010802"]},"LR000542":{"pair":"F13A1 -> ITGA9","headline":"Factor XIII A subunit supports alpha9beta1-mediated cell adhesion in transfected SW480 cells; functional evidence.","interaction_type":"functional only","direction_and_effect":"SW480 cells expressing alpha9beta1, but not mock cells, adhered to FXIII [PMID:10816592]; the authors identify FXIII as a shared ligand for alpha9beta1 and alpha4beta1 [PMID:10816592].","molecular_requirements":"Integrin alpha9beta1 pair is needed; alpha9 alone not tested separately.","affinity_potency":[],"species_and_systems":"Human SW480 transfectants and G-361 melanoma cells [PMID:10816592].","localisation_and_range":"FXIII flagged secreted [flag].","caveats":"Adhesion assay only; no purified binding or affinity.","key_references":[{"PMID":"10816592","why":"FXIII adhesion via alpha9beta1"}],"covers":["LR000542","LR004033"]},"LR004034":{"pair":"F13A1 -> ITGB1","headline":"Factor XIII supports cell adhesion via beta1 integrins alpha9beta1 and alpha4beta1; ITGB1 evidence is heterodimer-level.","interaction_type":"functional only","direction_and_effect":"SW480 cells expressing alpha9beta1 adhered to FXIII [PMID:10816592], and FXIII promoted adhesion through alpha9beta1 or alpha4beta1 in G-361 or MOLT-3 cells [PMID:10816592].","molecular_requirements":"ITGB1 acts as the shared beta chain; its sole contribution is not tested.","affinity_potency":[],"species_and_systems":"Human cells [PMID:10816592]; mouse pair ortholog-inferred [flag].","localisation_and_range":"FXIII flagged secreted; ITGB1 non-secreted [flag].","caveats":"Chain-only caveat: ITGB1 evidence is inherited from alpha-beta heterodimers; adhesion assays only.","key_references":[{"PMID":"10816592","why":"FXIII adhesion via beta1 integrins"}],"covers":["LR000543","LR004034"]},"LR000551":{"pair":"F8 -> LDLR","headline":"The LDLR ligand-binding domain binds FVIII in vitro and LDLR contributes to FVIII clearance in mice.","interaction_type":"direct binding","direction_and_effect":"The extracellular ligand-binding domain of LDLR interacted with FVIII in vitro and binding was inhibited by RAP; in the absence of hepatic LRP, LDLR played a dominant role in FVIII clearance, and adenovirus-mediated LDLR transfer accelerated clearance [PMID:15840700]. This is an endocytic clearance receptor role.","molecular_requirements":"Only the extracellular ligand-binding domain was tested; no co-receptor requirement is reported. The authors propose LDLR acts with LRP [PMID:15840700].","affinity_potency":[],"species_and_systems":"In vitro binding plus mouse models (LDLR and hepatic LRP deficiency) [PMID:15840700].","localisation_and_range":"Endocytic receptor per the abstract; secretion flags: F8 secreted [flag].","caveats":"Single abstract-only paper; no affinity reported. RAP inhibition is not specific to LDLR.","key_references":[{"PMID":"15840700","why":"LDLR binds FVIII in vitro and affects FVIII clearance in mice"}],"covers":["LR000551","LR004042"]},"LR004043":{"pair":"F8 -> LRP1","headline":"FVIII binds LRP (cluster II) with high affinity by SPR; a clearance receptor interaction.","interaction_type":"direct binding","direction_and_effect":"In SPR with LRP cluster II, FVIII light chain showed high-affinity binding while the FVa light chain did not [PMID:12522143]. Annotation lists the effect as stimulatory; curator notes describe LRP1 as an endocytic clearance receptor.","molecular_requirements":"The FVIII a3-A3-C1 fragment bound LRP; peptide and antibody-fragment competition implicated the A3 region Lys(1804)-Ala(1834), notably Glu(1811)-Lys(1818); an FVIII/FV chimera retained reduced binding [PMID:12522143]. Both FVIII chains contribute to high-affinity interaction; a C2-domain site has lower affinity [PMID:12522143].","affinity_potency":[],"species_and_systems":"Purified FVIII fragments and LRP cluster II, species not stated in the abstract [PMID:12522143]; BioGRID reconstituted complex [DB:BioGRID 282746].","localisation_and_range":"F8 is annotated secreted [flag].","caveats":"Abstract-only; no numeric affinity in our evidence, and only LRP cluster II was tested rather than full-length LRP1.","key_references":[{"PMID":"12522143","why":"SPR mapping of FVIII A3 region binding to LRP cluster II"}],"covers":["LR000552","LR004043"]},"LR002612":{"pair":"FAM3B -> FGFR4","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR4-specific evidence is thin.","interaction_type":"functional only","direction_and_effect":"The paper shows FAM3B as an FGFR ligand in Xenopus, with ERK activation via FGFR1 [PMID:33975953]. Purified human FAM3B was incubated with Fc-tagged human FGFR1-4 ectodomains, with FGFR4-Ecto-Fc one of the panels; the excerpts do not show the FGFR4 result itself [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR4 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is secreted [flag] and detected in HEK293T medium [PMID:33975953].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002612","LR005879"]},"LR000560":{"pair":"FBN1 -> ITGB1","headline":"Fibrillin-1 acts through beta1 integrins (alpha5 beta1) in endothelial cells; one abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"Microfibrils and fibrillin-1 fragments induced integrin-mediated signaling in HUVECs; PF14 action was mediated by alpha v beta 3 and alpha 5 beta 1 integrins, and PF14 enhanced proliferation and migration [PMID:20686071]. UniProt says ITGA5:ITGB1 acts as a fibrillin-1 receptor [DB:UniProt].","molecular_requirements":"ITGB1 acts as part of alpha 5 beta 1, not alone [PMID:20686071] [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human umbilical venous endothelial cells, with bovine aortic endothelial cells as confirmation; the mouse pair is ortholog-inferred [PMID:20686071].","localisation_and_range":"FBN1 is flagged secreted, not transmembrane [flag]; microfibrils are extracellular [PMID:20686071].","caveats":"Single paper, abstract only; pathway/inhibition evidence, no direct binding. Affinity not reported in our evidence.","key_references":[{"PMID":"20686071","why":"Fibrillin-1 signaling in endothelial cells via beta1 and beta3 integrins."}],"covers":["LR000560","LR004051"]},"LR004052":{"pair":"FBN1 -> ITGB3","headline":"Fibrillin-1 supports adhesion through integrin alphaVbeta3 in human cell assays; curated databases agree, but no purified-protein binding data for this pair.","interaction_type":"functional only","direction_and_effect":"Fibrillin-1 acts as an adhesion ligand for alphaVbeta3: human fibroblast adhesion to fibrillin-1 fragments involved alpha v beta 3 (and mainly alpha 5 beta 1) [PMID:12807887], and A375-SM melanoma cells bound RGD-containing fibrillin-1 fragments mainly through alpha v beta 3 [PMID:12807887]. In HUVECs, fibrillin-1 fragment PF14 signalled via alphav beta3 and alpha5 beta1 integrins, raising calcium and enhancing proliferation and migration [PMID:20686071]. UniProt and Reactome describe ITGAV:ITGB3 as an RGD-dependent fibrillin-1 receptor [DB:UniProt] [DB:Reactome R-HSA-265416].","molecular_requirements":"The receptor is the alphaV/beta3 heterodimer (ITGAV:ITGB3), so both chains are needed [DB:Reactome R-HSA-265416]. The RGD-containing fibrillin-1 fragment PF14 was active, PF9 was not [PMID:20686071]. Adhesion was Arg-Gly-Asp and cation dependent [PMID:12807887].","affinity_potency":[],"species_and_systems":"Human cells (dermal fibroblasts, melanoma lines, HUVECs) with human fibrillin-1 fragments or microfibrils. The mouse pair is projected from human evidence only; no mouse experiments in our evidence.","localisation_and_range":"Fibrillin-1 is flagged secreted [flag]; it is described as a microfibril component, so signalling is likely local/contact with matrix (from paper text [PMID:12807887]).","caveats":"All three papers were read as abstracts only. Evidence is cell adhesion/signalling, with antibody or fragment dependence, not direct binding of purified FBN1 to ITGB3; no affinity for alphaVbeta3 reported. Fibrillin-1 binding to alpha5beta1 was stronger in fibroblasts [PMID:12807887].","key_references":[{"PMID":"12807887","why":"Fibroblast and melanoma adhesion to fibrillin-1 via alphaVbeta3 and alpha5beta1"},{"PMID":"20686071","why":"alphaVbeta3/alpha5beta1-mediated signalling by fibrillin-1 fragment in HUVECs"}],"covers":["LR000561","LR004052"]},"LR002621":{"pair":"FCER2 -> ITGB5","headline":"CD23-derived RKC peptides bind purified alphav-beta5 integrin by SPR; direct but peptide-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"CD23 binds alphav-beta3 and alphav-beta5 integrins through an RKC (arg-lys-cys) motif starting at arg172; effect direction is agonist: RKC peptides drove TNFa release from monocytes and pre-B cell growth [PMID:22560905].","molecular_requirements":"The receptor is the alphav-beta5 heterodimer; ITGB5 as a lone chain was not tested. The RKC motif is required: replacing both basic residues abolished binding and activity, one residue only reduced it [PMID:22560905].","affinity_potency":[],"species_and_systems":"Human CD23-derived peptides, purified integrins (SPR), SMS-SB and THP-1 cells; full text read [PMID:22560905].","localisation_and_range":"CD23 carries secreted, receptor and transmembrane flags [flag], so soluble and membrane forms are both plausible; the paper used soluble CD23 and peptides [PMID:22560905].","caveats":"Binding was shown with CD23-derived peptides and cells; the full-length protein with purified integrin is not shown beyond cell competition. No affinity reported in our evidence. Binding is biphasic and chloride-sensitive, unlike RGD ligands [PMID:22560905].","key_references":[{"PMID":"22560905","why":"SPR and cell binding of RKC peptides to avb3/avb5"}],"covers":["LR002621"]},"LR001811":{"pair":"FGA -> TLR4","headline":"Fibrinogen is called an endogenous TLR4 ligand in monocytes of pre-eclamptic patients; functional only, plus a Reactome record.","interaction_type":"functional only","direction_and_effect":"Fibrinogen exposure increased inflammatory cytokine production by monocytes from pre-eclamptic patients but not from normotensive pregnant women, and the authors propose a fibrinogen-TLR4 axis [PMID:24661950].","molecular_requirements":"Not reported in our evidence; whole fibrinogen was used and TLR4 dependence is inferred. Reactome lists cleaved fibrinogen products binding TLR4:LY96 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human monocytes from patients [PMID:24661950].","localisation_and_range":"FGA flagged secreted [flag].","caveats":"Abstract only; direct binding is not shown in the abstract. A review-only row is not shown. The effect appeared only in pre-eclamptic monocytes.","key_references":[{"PMID":"24661950","why":"fibrinogen activates PE monocytes via TLR4"}],"covers":["LR001811"]},"LR007013":{"pair":"FGA:FGB:FGG -> ITGA2B:ITGB3","headline":"Fibrinogen binds purified platelet integrin alphaIIbbeta3 in single-molecule force measurements; fibrin binds more strongly.","interaction_type":"direct binding","direction_and_effect":"Both fibrinogen and monomeric fibrin interact with purified alphaIIbbeta3; fibrin showed a higher probability of interaction and greater binding strength [PMID:26867579].","molecular_requirements":"Full fibrinogen hexamer with the alphaIIbbeta3 heterodimer. Partly inhibited by RGD peptides; alphaD97E and alphaD574E variants support RGD involvement; fibrin from a gamma'/gamma' fibrinogen lacking the gammaC alphaIIbbeta3 site was more reactive [PMID:26867579].","affinity_potency":[],"species_and_systems":"Purified alphaIIbbeta3 with bead-coupled ligand, laser trap (curator fields human) [PMID:26867579]. BioGRID and IntAct hold chain-level records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Annotation flags mark the ligand complex not secreted and not transmembrane [flag], which does not describe plasma fibrinogen well; receptor complex is_receptor flag 0 [flag].","caveats":"Abstract only; no numeric affinity in our evidence. Fibrin binds more reactively than fibrinogen and is less sensitive to abciximab and eptifibatide [PMID:26867579].","key_references":[{"PMID":"26867579","why":"fibrinogen vs fibrin binding to alphaIIbbeta3"}],"covers":["LR007013"]},"LR004061":{"pair":"FGF16 -> FGFR2","headline":"FGF16 activates FGFR2c in BaF3 cells, and genetic data suggest FGFR1/FGFR2 act redundantly for FGF signals in the heart.","interaction_type":"functional only","direction_and_effect":"FGF9, FGF16 and FGF20 activated FGFRc isoforms with high activity [PMID:16597617]. In mouse heart, endocardial and epicardial FGF signals are received by FGFR1 and FGFR2 acting redundantly in cardiomyoblasts [PMID:15621532]. Agonist.","molecular_requirements":"c-isoform specific in BaF3 [PMID:16597617]. In vivo, FGFR1 and FGFR2 are redundant [PMID:15621532].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human. The mouse knockout study used Fgf9/Fgf16/Fgf20 knockouts and heart organ culture [PMID:15621532].","localisation_and_range":"FGF16 flagged secreted [flag]; paracrine signalling from endo/epicardium to myocardium [PMID:15621532].","caveats":"The heart paper is genetic and acts on FGF9, FGF16 and FGF20 jointly, so FGF16-FGFR2 specificity is inferred, not measured; abstract-only [PMID:15621532]. Panel paper is functional only [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFRc activation"},{"PMID":"15621532","why":"FGF9/16/20 signal via redundant FGFR1/2 in mouse heart"}],"covers":["LR000577","LR004061"]},"LR004070":{"pair":"FGF18 -> FGFR3","headline":"FGF18 signals through FGFR3 to promote chondrogenesis, supported by mouse genetics and a BaF3 panel.","interaction_type":"functional only","direction_and_effect":"FGF18 was a selective ligand for FGFR3 in limb bud mesenchymal cells, where it suppressed proliferation and promoted differentiation and cartilage matrix production [PMID:15781473]. FGF18 also activated FGFR3c in BaF3 cells [PMID:16597617]. Agonist.","molecular_requirements":"c isoform of FGFR3 in BaF3 [PMID:16597617]; FGFR3-/- cultures had impaired response to FGF18 and altered FGFR1/FGFR2 expression [PMID:15781473].","affinity_potency":[],"species_and_systems":"Mouse limb bud mesenchymal cultures from FGFR3-/- vs +/+ [PMID:15781473]; BaF3 panel [PMID:16597617]. Human and mouse pairs listed, neither projected.","localisation_and_range":"FGF18 flagged secreted; paracrine action is inferred [flag].","caveats":"Evidence is genetic and functional, with no direct binding measurement in the dossier. FGF18 suppresses proliferation here, an unusual FGF effect. Abstract-only for the chondrogenesis paper [PMID:15781473].","key_references":[{"PMID":"15781473","why":"FGF18-FGFR3 in limb bud chondrogenesis"},{"PMID":"16597617","why":"BaF3 FGFR3c activation"}],"covers":["LR000586","LR004070"]},"LR002630":{"pair":"FGF2 -> ITGAV","headline":"FGF2 binds integrin alphavbeta3 (SPR) and binding-defective FGF2 mutants antagonise FGF2 signalling; evidence is for the heterodimer.","interaction_type":"direct binding","direction_and_effect":"WT FGF2 bound immobilised soluble \u03b1v\u03b23 by SPR; FGF2 mutants K119E/R120E and K125E have reduced integrin binding, fail to drive ERK1/2 activation and DNA synthesis, and suppress WT FGF2 signalling in endothelial cells, acting as antagonists [PMID:28302677]. UniProt states ITGAV:ITGB3 binds FGF2 and this is essential for FGF2 signalling [DB:UniProt].","molecular_requirements":"The data concern the \u03b1v\u03b23 heterodimer, not \u03b1v alone; K562 adhesion also suggested binding to \u03b15\u03b21 [PMID:28302677]. FGF2 was modelled as able to bind FGFR1 and \u03b1v\u03b23 simultaneously [PMID:28302677].","affinity_potency":[{"value":"Kd 7.75 \u00d7 10\u22128 M","assay":"SPR, WT FGF2 on immobilised soluble \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"},{"value":"Kd 1.1 \u00d7 10\u22126 M","assay":"SPR, K125E FGF2 mutant on \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"}],"species_and_systems":"Cell work used NIH3T3 mouse fibroblasts and HUVECs; ligand and receptor species are recorded as human [PMID:28302677]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF2 is flagged secreted and the receptor a membrane integrin [flag]; paracrine ligand to cell-surface integrin is implied, not tested as such.","caveats":"The curator evidence sentence is background citing earlier work; this paper's own data are the SPR and mutant results. Docking is predictive only, and the authors note mutations could act through conformational changes. Paper read at abstract level for the curated row.","key_references":[{"PMID":"28302677","why":"SPR Kd of FGF2 for \u03b1v\u03b23 and integrin-binding-defective antagonist mutants"}],"covers":["LR002630","LR005896"]},"LR000614":{"pair":"FGF2 -> NRP1","headline":"FGF2 binds immobilised NRP1 by optical biosensor, largely through ionic, heparin-sensitive interaction, and NRP1 potentiates FGF2 action.","interaction_type":"direct binding","direction_and_effect":"FGF2 interacts with Npn-1 immobilised on a biosensor and in a solution assay. Npn-1 potentiated FGF-2 growth stimulation of HUVECs [PMID:15695515]. A BioGRID FRET record is also listed [DB:BioGRID].","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"270,000-1,600,000 M-1s-1","assay":"association rate constants for FGF-2, FGF-4 and HGF/SF binding to Npn-1 (optical biosensor)","system":"recombinant, in vitro","cite":"PMID:15695515"}],"species_and_systems":"Human proteins; HUVEC growth assay [PMID:15695515]. Mouse and human pairs are ortholog-inferred.","localisation_and_range":"NRP1 is flagged both secreted and transmembrane, and FGF2 secreted [flag].","caveats":"Binding is largely electrostatic and Npn-1 binds many heparin-binding proteins, so specificity is limited; rate range covers FGF-2, FGF-4 and HGF/SF together, not FGF2 alone [PMID:15695515]. The BioGRID record cites a different paper than the one in our evidence [DB:BioGRID].","key_references":[{"PMID":"15695515","why":"Biosensor binding of FGF-2 to Npn-1 and potentiation of FGF-2 activity"}],"covers":["LR000614","LR004098"]},"LR007202":{"pair":"FGF23 -> FGFR1:KL","headline":"Database-asserted complex: FGF23 with FGFR1c and alpha-Klotho resolved in structures; no curated paper judged.","interaction_type":"database-asserted only","direction_and_effect":"No papers were judged; support is from databases. PDB holds a 1:1:1 FGF23-FGFR1c-aKlotho ternary complex [DB:PDB 5W21] and a cryo-EM quaternary complex with heparan sulfate [DB:PDB 7YSH]. Reactome has FGF23 bound to Klotho and FGFR1c [DB:Reactome R-HSA-190218].","molecular_requirements":"Both FGFR1c and Klotho are in the structures [DB:PDB 5W21]; heparan sulfate appears in the cryo-EM complex [DB:PDB 7YSH].","affinity_potency":[],"species_and_systems":"BioGRID affinity-capture-Western records exist for FGF23 with FGFR1 and with KL [DB:BioGRID]; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Database only; one review-only row is not shown.","key_references":[],"covers":["LR007202"]},"LR000605":{"pair":"FGF23 -> FGFR3","headline":"FGF23 binds FGFR3c with high affinity in opossum kidney cells and activates c isoforms in other assays.","interaction_type":"direct binding","direction_and_effect":"FGF-23 binds FGF receptor 3c with high affinity in opossum kidney cells [PMID:12032146]; FGF23 binds and activates c isoforms of FGFR1-3 and FGFR4 [PMID:16081635, PMID:16597617]. Stimulatory.","molecular_requirements":"c isoform needed, not b [PMID:16081635]; heparin-like molecules were required for FGF-23 activity [PMID:12032146].","affinity_potency":[],"species_and_systems":"Opossum kidney cells [PMID:12032146]; human reagents for SPR [PMID:16081635]; BaF3 screen species unspecified [PMID:16597617]. Human pair is not ortholog-inferred; mouse also direct.","localisation_and_range":"FGF23 secreted [flag].","caveats":"No numeric affinity in the dossier. Abstract-only reading for two papers. One review-only row not shown.","key_references":[{"PMID":"12032146","why":"FGF-23 binds FGFR3c in opossum kidney cells"},{"PMID":"16081635","why":"SPR and mitogenesis on c isoforms"},{"PMID":"16597617","why":"BaF3 screen"}],"covers":["LR000605","LR004089"]},"LR001820":{"pair":"FGF23 -> KL","headline":"Database-asserted only: Klotho-FGF23 appears in structures and Reactome; no paper confirmed.","interaction_type":"database-asserted only","direction_and_effect":"No papers confirmed the pair (two rows judged abstract_insufficient). PDB shows FGF23 with alpha-Klotho in a ternary complex [DB:PDB 5W21] and cryo-EM complex [DB:PDB 7YSH]; Reactome has Klotho bound to FGF23 [DB:Reactome R-HSA-190208]; BioGRID has an affinity-capture-Western record [DB:BioGRID].","molecular_requirements":"Structures include FGFR1c as well, so KL binding may depend on FGFR1c [DB:PDB 5W21].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on databases; both human and mouse pairs are ortholog-inferred.","key_references":[],"covers":["LR001820","LR005175"]},"LR004106":{"pair":"FGF4 -> FGFR2","headline":"FGF4 activates FGFR2 IIIc, not IIIb, in mitogenic screens; structural and functional evidence.","interaction_type":"functional only","direction_and_effect":"FGF4 binds and activates IIIc forms of FGFR1-3 [PMID:11486033]; FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms in BaF3 cells [PMID:8663044]. Stimulatory.","molecular_requirements":"IIIc isoform; heparin as cofactor [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human FGF4 structure [PMID:11486033]; BaF3 species unspecified [PMID:8663044]. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The structural paper's FGFR2-specific assignment is medium confidence per curators [PMID:11486033]. Abstract-only readings.","key_references":[{"PMID":"11486033","why":"FGF4 structure"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000622","LR004106"]},"LR000623":{"pair":"FGF4 -> FGFR3","headline":"FGF4 activates FGFR3 IIIc, not IIIb, in a BaF3 screen; structural paper supports isoform specificity.","interaction_type":"functional only","direction_and_effect":"FGF4 binds and activates IIIc forms of FGFR1-3 [PMID:11486033]; FGFs 4, 5, 6 and 8 activate c receptor splice forms in BaF3 cells [PMID:8663044]. No numeric affinity.","molecular_requirements":"IIIc isoform required [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human FGF4 structure [PMID:11486033]; BaF3 species unspecified [PMID:8663044].","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only readings; gene-level row hides isoform specificity.","key_references":[{"PMID":"11486033","why":"FGF4 structure"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000623","LR004107"]},"LR004115":{"pair":"FGF6 -> FGFR2","headline":"Weakly supported by one BaF3 survey and database records; FGFR2-specific data are not shown.","interaction_type":"functional only","direction_and_effect":"The pair is annotated stimulatory. The BaF3 survey states FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms [PMID:8663044].","molecular_requirements":"c splice-form selectivity is described [PMID:8663044]. Reactome and BioGRID records exist [DB:Reactome][DB:BioGRID]; the Reactome example concerns FGFR2b mutants binding an expanded ligand range, not FGF6 specifically [DB:Reactome].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"One abstract-only paper with browser-read quote pending spot-check; no direct binding data; database records are generic.","key_references":[{"PMID":"8663044","why":"BaF3 survey, FGF6 activates c splice forms"}],"covers":["LR000631","LR004115"]},"LR000632":{"pair":"FGF6 -> FGFR3","headline":"Database-asserted only; no curated paper supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect is reported in our evidence; UniProt lists FGF6 among interactors of FGFR3 [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our evidence. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"No papers were shown (0 papers judged; abstract_insufficient and review_only rows only). The sole support is a UniProt subunit statement.","key_references":[],"covers":["LR000632","LR004116"]},"LR004124":{"pair":"FGF8 -> FGFR4","headline":"FGF8 binds immobilised FGFR4 ectodomain and activates FGFR4 (4\u0394) in BaF3; binding not seen in solution.","interaction_type":"direct binding","direction_and_effect":"Immobilised recombinant human FGFR4 extracellular domain bound FGF-8 [PMID:10736564]. FGF8 subfamily members activated the two Ig-like domain form of FGFR4 (4\u0394) in BaF3 cells [PMID:16597617].","molecular_requirements":"FGFR4 shows strong dependence on heparin-like material for activation [PMID:10736564]. A two Ig-like domain form of FGFR4 was the responsive form [PMID:16597617].","affinity_potency":[],"species_and_systems":"Insect-cell-expressed human FGFR4 ectodomain on a biosensor chip, abstract only [PMID:10736564]; BaF3 cells with unspecified species [PMID:16597617][PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"FGF-8 binding was seen only with immobilised receptor, not in solution [PMID:10736564]. No affinity is reported. The PMID:8663044 sentence concerns c splice forms and does not name FGFR4.","key_references":[{"PMID":"10736564","why":"FGF-8 binds immobilised FGFR4 ectodomain"},{"PMID":"16597617","why":"FGF8 subfamily activates FGFR4 (4\u0394)"}],"covers":["LR000640","LR004124"]},"LR000641":{"pair":"FGF9 -> FGFR1","headline":"FGF9 activates FGFR1c in BaF3 assays; structure and database interaction records exist.","interaction_type":"functional only","direction_and_effect":"FGF9 subfamily members activated FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. FGFs 2 and 9 preferentially activate c splice forms [PMID:8663044].","molecular_requirements":"c splice form is the preferred responder [PMID:8663044]. PDB 5W59 has a chain of each partner [DB:PDB 5W59]; IntAct records surface plasmon resonance [DB:IntAct]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:16597617][PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Both papers use the same BaF3 readout with browser-read quotes pending spot-check; neither sentence names FGFR1 explicitly. No affinity in our evidence.","key_references":[{"PMID":"16597617","why":"FGF9 subfamily activates FGFRc isoforms"},{"PMID":"8663044","why":"FGF9 preferentially activates c forms"}],"covers":["LR000641","LR004125"]},"LR004142":{"pair":"FN1 -> ITGA3","headline":"Fibronectin binding to integrin alpha3beta1 is supported by one SPR paper; ITGA3 evidence is for the alpha3beta1 dimer.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance was used to determine binding kinetics of integrin alpha3beta1 to Fn fragments, and binding depended on the ninth type III repeat [PMID:26318455]. BioGRID lists a reconstituted complex between FN1 and ITGA3 [DB:BioGRID].","molecular_requirements":"alpha3beta1 is the tested form; ITGA3 alone is not reported in our evidence. Dependence on the ninth type III repeat is reported in the paper title [PMID:26318455].","affinity_potency":[],"species_and_systems":"Recombinant Fn fragments; the abstract mentions epithelial cell responses; species not stated in our evidence.","localisation_and_range":"FN1 flagged secreted, ITGA3 flagged receptor [flag]; matrix-to-cell contact.","caveats":"Single paper read as an abstract; kinetic values are not in our evidence. 1 paper pending.","key_references":[{"PMID":"26318455","why":"SPR kinetics of alpha3beta1 binding fibronectin fragments"}],"covers":["LR000658","LR004142"]},"LR007022":{"pair":"FN1 -> ITGA4:ITGB7","headline":"Mouse lymphoma cells adhered to fibronectin through alpha4beta7; evidence is one functional paper.","interaction_type":"functional only","direction_and_effect":"TK-1 cells, which lack alpha4beta1, adhered to intact fibronectin and the CS-1 fragment but not an RGD fragment, and adhesion was inhibited by anti-alpha4 antibodies, suggesting alpha4beta7 is a fibronectin receptor [PMID:1372909]. BioGRID lists FN1-ITGB7 affinity capture-Western [DB:BioGRID].","molecular_requirements":"Beta7 was the only subunit associated with alpha4 in these cells [PMID:1372909].","affinity_potency":[],"species_and_systems":"Mouse TK-1 T lymphoma cells [PMID:1372909].","localisation_and_range":"FN1 flagged secreted; integrin complex flagged transmembrane [flag]; matrix-to-cell contact.","caveats":"The conclusion is inferential (antibody inhibition), not a binding assay. The pair is human but the experiments were in mouse cells. 2 papers judged different entity.","key_references":[{"PMID":"1372909","why":"alpha4beta7 on mouse TK-1 cells mediates adhesion to fibronectin CS-1"}],"covers":["LR007022"]},"LR004151":{"pair":"FN1 -> ITGB7","headline":"Fibronectin binds alpha4beta7 (via the CS-1 region) in mouse T lymphoma cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Mouse TK-1 cells adhered to intact fibronectin and a CS-1 fragment, blocked by anti-alpha4 antibodies, and alpha4beta7 bound the CS-1 region by affinity chromatography [PMID:1372909]. Adhesion was increased by brief PMA stimulation [PMID:1372909].","molecular_requirements":"The receptor is the alpha4-beta7 heterodimer; beta7 was the only subunit associated with alpha4 in these cells [PMID:1372909]. Cells did not adhere to the RGD-containing fragment [PMID:1372909].","affinity_potency":[],"species_and_systems":"Mouse TK-1 T lymphoma cells; human and mouse rows are ortholog-inferred [PMID:1372909].","localisation_and_range":"Fibronectin flagged secreted [flag]; adhesion of lymphocytes to matrix (contact), from paper text.","caveats":"One paper, read as abstract. No affinity reported. Experiments are in mouse; the human pair is inferred.","key_references":[{"PMID":"1372909","why":"alpha4beta7 binds fibronectin CS-1 in mouse TK-1 cells"}],"covers":["LR000667","LR004151"]},"LR004160":{"pair":"GAL -> GALR1","headline":"Galanin is a well-supported agonist of GALR1, with direct binding in human cells and nanomolar-to-picomolar affinity.","interaction_type":"direct binding","direction_and_effect":"Galanin acts as an agonist: the cloned human receptor binds galanin with high affinity and mediates galanin inhibition of adenylate cyclase [PMID:7524088]. GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"Mutagenesis implicates His264, His267 (TM-VI), Phe282 (TM-VII) and Glu271 (extracellular loop III) of the receptor in galanin binding [PMID:8617199]. Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 0.07 nM","assay":"125I-galanin binding","system":"CHP-212 human neuroblastoma cells, galanin receptors like GALR1","cite":"PMID:9168941"},{"value":"<1 nM","assay":"binding affinity","system":"Bowes cells expressing hGalR1","cite":"PMID:11600206"},{"value":"Kd in the nanomolar range","assay":"radioligand binding","system":"COS cells expressing cloned receptor","cite":"PMID:7524088"}],"species_and_systems":"Binding studies used human receptor in cells (COS, Bowes, HEK-293E, CHP-212); an in vivo rat study supports GalR1 involvement in antiallodynic effects of high-dose galanin [PMID:11481429]. The mouse pair is projected from human evidence.","localisation_and_range":"Galanin is flagged as secreted and GALR1 as a transmembrane receptor [flag]; a secreted peptide acting at a distance is plausible but not directly tested in our evidence.","caveats":"Most papers were read as abstracts only. The rat in vivo assignment to GalR1 is pharmacological and inferential, not a binding measurement [PMID:11481429]. Two-state binding (picomolar high-affinity and nanomolar low-affinity) was reported in HEK-293E cells [PMID:9808667].","key_references":[{"PMID":"7524088","why":"Cloning of human GALR1 with high-affinity galanin binding"},{"PMID":"9168941","why":"Kd 0.07 nM galanin binding in CHP-212 cells"},{"PMID":"9808667","why":"Two-state affinity characterisation of human GALR1"}],"covers":["LR000676","LR004160"]},"LR007211":{"pair":"GAL -> GALR1:GPR151","headline":"No primary evidence for a GALR1:GPR151 complex; only GALR1 alone is supported by a database.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the complex. GtoPdb lists galanin as a full agonist at GALR1 alone [DB:GtoPdb].","molecular_requirements":"Whether GPR151 is needed is not reported in our evidence; the complex is not shown to be required.","affinity_potency":[],"species_and_systems":"No experiments for this complex in our evidence. Two papers were judged review-only (no primary evidence).","localisation_and_range":"GAL is flagged as secreted; the receptor entry is flagged as a transmembrane receptor [flag].","caveats":"Support rests on GALR1 records (GtoPdb) and the HGNC name for GALR1, not on evidence for GPR151 participation [DB:GtoPdb]. Treat as the single-receptor GAL -> GALR1 pair.","key_references":[],"covers":["LR007211"]},"LR011216":{"pair":"GDF10 -> ACVR1C","headline":"Database-asserted only: a single GtoPdb agonist record; no papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF10 as agonist of ACVR1C [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"No papers were judged; support rests entirely on one database record. Affinity not reported.","key_references":[],"covers":["LR011216"]},"LR011234":{"pair":"GDF15 -> TGFBR2","headline":"Weak: one abstract-only melanoma paper claims GDF15 binds TGFBR2; two other papers had insufficient abstracts.","interaction_type":"functional only","direction_and_effect":"CAF-derived GDF15, whose secretion is regulated by FOXP1, is reported to bind TGFBR2 on melanoma cells and drive proliferation and metastasis [PMID:40555562].","molecular_requirements":"Not reported in our evidence; the same paper also describes GDF15 acting on GFRAL and RET [PMID:40555562].","affinity_potency":[],"species_and_systems":"Melanoma cells and mouse models; species of binding experiments not stated in the abstract [PMID:40555562].","localisation_and_range":"Paracrine from cancer-associated fibroblasts to melanoma cells [PMID:40555562].","caveats":"Abstract-only; the binding assay behind the claim is unclear (co-immunoprecipitation is listed generally). No affinity. Single paper.","key_references":[{"PMID":"40555562","why":"Reports GDF15 binding TGFBR2 in melanoma"}],"covers":["LR011234"]},"LR011207":{"pair":"GDF2 -> BMPR1B","headline":"One abstract-level functional report for ALK6 (BMPR1B) plus a GtoPdb agonist record; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"GDF2 robustly activated SMAD1/5 signalling by increasing complex formation between ALK3 and ALK6 and the type-II receptor BMPRII in ovarian and breast epithelial cells [PMID:26678910]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Requires the type-II receptor BMPRII in the reported complex [PMID:26678910].","affinity_potency":[],"species_and_systems":"Ovarian and breast epithelial cells; species not stated in our evidence [PMID:26678910].","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"Single paper, abstract only [PMID:26678910]. It reports increased receptor complex formation, not direct ligand binding. ALK3 and ALK6 are described together, so it is not specific to BMPR1B.","key_references":[{"PMID":"26678910","why":"GDF2 increases ALK3/ALK6-BMPRII complex formation, SMAD1/5 activation"}],"covers":["LR011207"]},"LR000704":{"pair":"GDF6 -> BMPR2","headline":"GDF6 binds BMPR2 directly (KD 28.1 nM for rhBMP13) and BMPRII knockdown suppresses its signalling; binding is weaker than for type I receptors.","interaction_type":"direct binding","direction_and_effect":"Agonist-type binding: rhBMP13 (GDF6) bound BMPR2, as well as ALK3, ALK6, ACVR2A and ACVR2B [PMID:21702718]. BMPRII shRNA suppressed GDF6 signalling in MC3T3 cells [PMID:16049014]. CDMP-2 (GDF6) had affinity for BMPR-II [PMID:9525338]. BioGRID lists a reconstituted GDF6-BMPR2 complex [DB:BioGRID].","molecular_requirements":"BMPR2 acts with a type I receptor: ALK3 or ALK6 conferred GDF6 signalling [PMID:16049014]; BMPR-IB with BMPR-II transduced the CDMP-2 signal [PMID:9525338].","affinity_potency":[{"value":"KD 28.1 nM","assay":"surface plasmon resonance, KD (kin), rhBMP13 (GDF6) vs BMPR2 ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human ligands and receptors in binding assays [PMID:21702718]; MC3T3 cells with shRNA [PMID:16049014]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"BMPR2 and ACVR2A binding was more than 10-fold weaker than type I receptor binding [PMID:21702718]. rhBMP13 did not detectably activate SMAD1/5/8 in C3H10T1/2 cells [PMID:21702718] although Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. Two papers are abstract-only.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP13 (GDF6) to BMPR2 and other receptors."},{"PMID":"16049014","why":"BMPRII shRNA suppresses GDF6 signalling."},{"PMID":"9525338","why":"CDMP-2 receptor binding."}],"covers":["LR000704","LR004188"]},"LR000713":{"pair":"GH1 -> GHR","headline":"Well established agonist-receptor pair with structures and dimerisation data; affinity values are not in our evidence.","interaction_type":"direct binding","direction_and_effect":"GH induced GHR dimerisation in human IM-9 cells, with JAK2 association and STAT5 phosphorylation [PMID:10551877]. hGH bound GHRs in binding and cross-linking assays [PMID:7862673]. GtoPdb records an agonist interaction [DB:GtoPdb].","molecular_requirements":"GH-induced GHR dimerisation is critical for signalling; disulfide linkage is not required [PMID:10551877]. PDB complexes (e.g. 1A22) and BioGRID reconstituted complexes support this [DB:PDB 1A22][DB:BioGRID].","affinity_potency":[{"value":"ED50 of 3 nM","assay":"GHBP inhibition of hGH adipogenesis (hGH fixed at 0.45 nM)","system":"mouse 3T3-F442A preadipocytes","cite":"PMID:2387255"}],"species_and_systems":"Human IM-9 cells [PMID:10551877]; bovine GHR and rat GHBP in mouse L cells with hGH [PMID:7862673]; 3T3-F442A mouse adipocytes with recombinant hGHBP [PMID:2387255].","localisation_and_range":"GH1 is flagged secreted [flag]; a soluble GHBP (receptor ectodomain) can dampen GH action [PMID:2387255].","caveats":"Soluble GHR ectodomain (GHBP) inhibits GH bioactivity, with an ED50 of 3 nM [PMID:2387255]. All papers were read as abstracts. 7862673 concerns species cross-reactivity rather than human receptor binding.","key_references":[{"PMID":"7862673","why":"hGH binding to GHRs and species specificity"},{"PMID":"10551877","why":"GH-induced GHR dimerisation in human cells"},{"PMID":"2387255","why":"GHBP inhibits GH action"}],"covers":["LR000713"]},"LR009020":{"pair":"GNAI2 -> DRD2","headline":"GNAI2-DRD2 is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says DRD2 interacts with G(i) proteins including GNAI2, by similarity [DB:UniProt][PMID:15857609]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009020"]},"LR000722":{"pair":"GPC3 -> CD81","headline":"GPC3 binds CD81 (yeast two-hybrid, co-IP) in liver; two abstract-read papers, with GPC3 binding reducing CD81-Hhex binding.","interaction_type":"direct binding","direction_and_effect":"Antagonist (curator label): GPC3 binding to CD81 lowers CD81-Hhex binding, giving nuclear translocation of Hhex and transcriptional repression [PMID:23665349]. GPC3 interacts with CD81 in yeast two-hybrid, and co-immunoprecipitation validated it [PMID:19574424]. GPC3-CD81 binding decreased at the peak of hepatocyte proliferation [PMID:23665349].","molecular_requirements":"Not reported in our evidence beyond the two partners; Hhex competes for CD81 [PMID:23665349].","affinity_potency":[],"species_and_systems":"Mouse liver regeneration and hepatocytes (partial hepatectomy, GPC3 transgenic mice) [PMID:23665349][PMID:19574424]; curators recorded 'human' for one and 'unspecified' for the other. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"GPC3 is GPI-anchored to the cell surface [PMID:19574424]; GPC3 is annotated non-secreted [flag]. CD81 is a tetraspanin and co-localises with GPC3 in liver [PMID:19574424].","caveats":"Both papers read as abstracts only. Binding was shown by yeast two-hybrid and co-IP, which do not prove direct binding in a ligand-receptor sense. A fourth judged row was 'review_only'. No affinity reported in our evidence.","key_references":[{"PMID":"19574424","why":"Yeast two-hybrid and co-IP of GPC3 with CD81"},{"PMID":"23665349","why":"GPC3-CD81 binding controls Hhex release"}],"covers":["LR000722","LR004204"]},"LR004205":{"pair":"GPC3 -> IGF1R","headline":"GPC3 binds IGF-1R through its N-terminal proline-rich region and enhances IGF-II-triggered IGF-1R phosphorylation, in cell lines; one paper.","interaction_type":"direct binding","direction_and_effect":"GPC3 bound specifically through its N-terminal proline-rich region to both IGF-II and IGF-1R, and stimulated IGF-1R and ERK phosphorylation in an IGF-II-dependent way [PMID:18413366]. GPC3 knockdown in HCC cells reduced IGF-1R and ERK phosphorylation [PMID:18413366].","molecular_requirements":"N-terminal proline-rich region of GPC3 (P25-29A mutant weakened responses); IGF-II is required for the activation, and convertase digestion is needed for GPC3 to interact with IGF-II [PMID:18413366]. The authors suggest GPC3 joins a ligand-receptor multiprotein complex, possibly via heparan sulfate [PMID:18413366].","affinity_potency":[],"species_and_systems":"Human HCC cell lines (HuH-7), NIH3T3 and HEK293/HEK293T cells, by co-IP and pull-down [PMID:18413366]; mouse pair is ortholog-inferred.","localisation_and_range":"GPC3 is annotated non-secreted [flag] (cell-surface); IGF1R is a transmembrane receptor [flag].","caveats":"Abstract plus excerpts from one paper. Binding was shown by co-IP in cells, so it may be bridged by IGF-II or heparan sulfate; no affinity reported in our evidence.","key_references":[{"PMID":"18413366","why":"GPC3 binds IGF-1R and enhances IGF-II signalling"}],"covers":["LR000723","LR004205"]},"LR002702":{"pair":"GPC6 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC6 evidence is class-level.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Evidence is for 'glypican' as a class. GPC6 was detected in the LRRTM4-Fc sample but is not named in the abstract; direct cell-free binding was shown for GPC4 only [PMID:23911103].","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002702","LR005967"]},"LR011162":{"pair":"GZMA -> F2RL1","headline":"Granzyme A is reported to activate PAR2 more weakly than GzmK in one in vitro study.","interaction_type":"functional only","direction_and_effect":"GzmK and, to a lesser extent, GzmA were reported to activate PAR1 and PAR2; cleavage at the canonical arginine P1 residue [PMID:35881628]. The IL-6/IL-8 release result in A549 cells is given for GzmK [PMID:35881628].","molecular_requirements":"Exosite interactions between protease and receptor [PMID:35881628].","affinity_potency":[],"species_and_systems":"Peptides, full-length proteins and A549 cells [PMID:35881628].","localisation_and_range":"F2RL1 is flagged as a receptor [flag].","caveats":"Single abstract-only paper centred on GzmK; GzmA data are not detailed. Protease-cleavage activation.","key_references":[{"PMID":"35881628","why":"GzmK and GzmA activate PAR1/PAR2"}],"covers":["LR011162"]},"LR000740":{"pair":"HCRT -> HCRTR2","headline":"Orexin-A (HCRT) activates OX2 (HCRTR2); supported by many functional assays in recombinant human cells plus a structure record.","interaction_type":"direct binding","direction_and_effect":"Agonist. Orexin-A stimulates OX2 signalling in CHO and HEK-293 cells: phospholipases A2, C and D, calcium elevation and cAMP effects [PMID:26582739], ERK1/2 and p38 activation [PMID:18599270]. [125I]orexin-A binding was used in the CHO study [PMID:26582739]. Orexin-A and orexin-B are described as near-equipotent at OX2 [PMID:12606634][PMID:12208495]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor. Coupling is promiscuous: Gq/PLC/PKC, Gs and Gi routes contribute to ERK1/2 [PMID:18599270]; cAMP inhibition is pertussis-toxin sensitive [PMID:12890892]. Narcolepsy-associated OX2R mutants severely affect ERK1/2 activation [PMID:18599270]. A PDB entry (7L1U) has chains of O43612 and O43614 [DB:PDB 7L1U]; Reactome has the HCRTR2:HCRT(70-97) complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Recombinant human OX2 in CHO, HEK-293 and nerve-like cells [PMID:26582739][PMID:18599270][PMID:12890892]; the 1998 discovery work used rat brain tissue [PMID:9491897]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag]; no tissue-range data beyond this in our evidence.","caveats":"No affinity value for the OX2 pair is reported in the shown papers. All papers were read as abstracts only. Potency of orexin-B versus orexin-A at OX2 varies by report: one HEK-293 study found orexin-B more potent [PMID:18599270].","key_references":[{"PMID":"9491897","why":"Discovery of orexins as ligands of both receptors"},{"PMID":"26582739","why":"OX2 signalling with orexin-A in CHO cells, including binding"},{"PMID":"12606634","why":"Compares orexin-A and orexin-B at OX1 and OX2"}],"covers":["LR000740","LR004222"]},"LR004223":{"pair":"HCRT -> NPFFR2","headline":"Single binding paper suggests orexin interacts with NPGPR, a receptor variant related to NPFFR2; weak, with gene-identity uncertainty.","interaction_type":"direct binding","direction_and_effect":"Direction and effect not reported in our evidence. A radioligand displacement assay showed [125I]orexin B displaced by orexin B with an IC50 of 415 +/- 195 nM, and the authors conclude that orexins interact with NPGPR [PMID:12609745].","molecular_requirements":"Not reported in our evidence. The receptor studied is NPGPR, described as a splice variant of the NPFF receptor family, distinct from the shorter variant lacking exon 1 that was named NPFF2 [PMID:12609745].","affinity_potency":[{"value":"IC50 415 nM","assay":"[125I]orexin B displacement by orexin B","system":"NPGPR (species not stated in the dossier)","cite":"PMID:12609745"}],"species_and_systems":"Experimental species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"One paper, abstract only. The displacement used orexin B, not orexin-A, and the curators note uncertain identity of NPGPR versus NPFFR2 [PMID:12609745]. The abstract also states NPFF binds NPGPR about 100-fold weaker than the NPFF2 receptor. No database record supports the pair.","key_references":[{"PMID":"12609745","why":"Only study; radioligand displacement of orexin B at NPGPR"}],"covers":["LR000741","LR004223"]},"LR002711":{"pair":"HGF -> NRP1","headline":"HGF binds neuropilin-1 in vitro and NRP1 knockdown reduces HGF signalling; two papers, direct binding, likely a co-receptor role.","interaction_type":"direct binding","direction_and_effect":"HGF binds NRP1 immobilised on an optical biosensor [PMID:15695515]. In HUVECs, NRP1 or NRP2 knockdown decreased HGF-induced c-Met phosphorylation, and NRP1 was essential for HGF-mediated angiogenesis in a mouse Matrigel model [PMID:18065694]. NRP1 therefore acts as a co-receptor that potentiates c-Met signalling, not as a stand-alone receptor [PMID:18065694].","molecular_requirements":"The N-terminal domain of HGF is involved in the NRP binding [PMID:18065694]. Binding is ionic-strength-dependent and inhibited by heparin, suggesting a heparin-mimetic site on NRP1 [PMID:15695515]. Dependence on c-Met is implied by the knockdown data [PMID:18065694].","affinity_potency":[],"species_and_systems":"Human proteins and human cells (biosensor, HUVECs); in vivo angiogenesis was tested in a mouse Matrigel model [PMID:15695515][PMID:18065694].","localisation_and_range":"NRP1 is flagged as both secreted and transmembrane [flag]; the experiments used cell-surface or immobilised NRP1.","caveats":"The biosensor binding is largely electrostatic and heparin-competable, and the same assay detected many other heparin-binding proteins, so specificity is limited [PMID:15695515]. Only one paper has full text; the other was read as an abstract [PMID:18065694].","key_references":[{"PMID":"18065694","why":"HGF binds NRP1/NRP2; knockdown reduces c-Met signalling and angiogenesis"},{"PMID":"15695515","why":"Biosensor binding of HGF/SF to Npn-1"}],"covers":["LR002711","LR005976"]},"LR002720":{"pair":"HLA-B -> KIR3DS1","headline":"Moderate support: binding to HLA-Bw4 and HLA-B*51 recognition shown for the activating receptor, allotype-dependent.","interaction_type":"direct binding","direction_and_effect":"KIR3DS1 is activating. KIR3DS1 mediates positive signals on recognition of HLA-B*51 (Bw4-I80) surface molecules, and this occurs only in Bw4-I80neg individuals [PMID:28603523]. KIR3DS1*014+ cells bound HLA-Bw4, described as the first direct binding evidence [PMID:21804024].","molecular_requirements":"Binding depends on the KIR3DS1 allotype: *014 binds HLA-Bw4 but *013 does not, with position 138 and positions 199 and 138 together involved [PMID:21804024].","affinity_potency":[],"species_and_systems":"Human KIR3DS1 constructs (HEK293T) [PMID:21804024]; human NK cells and clones from donors of different HLA-B types [PMID:28603523].","localisation_and_range":"Both partners are flagged transmembrane [flag]; contact-dependent.","caveats":"Binding is allotype-specific, so not all KIR3DS1 variants bind. The HLA-B*51 paper is functional, not physical binding, and was read as an abstract [PMID:28603523]. The binding paper was also an abstract read [PMID:21804024]. No database records.","key_references":[{"PMID":"21804024","why":"Direct binding of KIR3DS1*014 cells to HLA-Bw4"},{"PMID":"28603523","why":"KIR3DS1 activation on recognition of HLA-B*51"}],"covers":["LR002720"]},"LR004232":{"pair":"HSP90B1 -> TLR2","headline":"Gp96 activates dendritic cells through TLR2 in mouse experiments; functional evidence only.","interaction_type":"functional only","direction_and_effect":"The Gp96-TLR2/4 interaction activates NF-kappaB reporters and MAPK/MSK, and induces IkappaBalpha degradation; bone-marrow dendritic cells from TLR4-mutant C3H/HeJ mice, and more markedly from C3H/HeJ TLR2-/- mice, fail to respond [PMID:11912201].","molecular_requirements":"Response requires Gp96 endocytosis; the paper names TLR2 and TLR4 together as a pathway [PMID:11912201].","affinity_potency":[],"species_and_systems":"Mouse dendritic cells and TLR-expressing cell lines [PMID:11912201]. The mouse pair is ortholog-inferred.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; described as an ER-resident protein acting after release [PMID:11912201].","caveats":"Abstract-only reading; no direct binding or affinity reported, and the effect is not separated between TLR2 and TLR4.","key_references":[{"PMID":"11912201","why":"Gp96 activates DCs via TLR2/4; knockout cells fail to respond"}],"covers":["LR000773","LR004232"]},"LR008021":{"pair":"IAPP -> CALCRL:RAMP3","headline":"No paper support for amylin acting on CALCRL:RAMP3; the evidence found concerns CALCR:RAMP3, so this pair is likely a gene mismatch.","interaction_type":"database-asserted only","direction_and_effect":"The one judged paper was marked pair_absent: its abstract names the calcitonin receptor (CALCR) with RAMP3 as the amylin receptor, not CALCRL [PMID:25409149]. GtoPdb records IAPP-RAMP3 as a full agonist (pEC50 8.6 to 10.8) [DB:GtoPdb].","molecular_requirements":"Not shown for CALCRL. PDB 8F0K and 8F2A are described as the human Amylin3 receptor with Gs and a pramlintide analogue [DB:PDB 8F0K], and UniProt describes RAMP3 acting together with CALCR as the amylin receptor [DB:UniProt]; neither names CALCRL.","affinity_potency":[{"value":"pEC50 8.6 to 10.8","assay":"GtoPdb IAPP-RAMP3 agonist record (not CALCRL-specific)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"The paper used human H1299 cells and p53-null mice [PMID:25409149]. Pair species: human.","localisation_and_range":"IAPP is flagged secreted [flag]; RAMP3 is flagged transmembrane [flag].","caveats":"Database records (GtoPdb, Reactome, PDB) concern CALCR:RAMP3 amylin receptors and may have been mapped onto CALCRL by name. Only the abstract was judged and it names CALCR. Treat as unsupported.","key_references":[{"PMID":"25409149","why":"Names CALCR plus RAMP3 as amylin receptor, not CALCRL"}],"covers":["LR008021"]},"LR006005":{"pair":"IBSP -> ITGB5","headline":"Integrin beta5 (alphaVbeta5) mediates BSP-RGD adhesion and proliferation in breast cancer cells; one abstract.","interaction_type":"functional only","direction_and_effect":"Blocking antibodies showed adhesion and proliferation responses to BSP-RGD were alpha(v)beta5-mediated, while migration used alpha(v)beta3 [PMID:9699501].","molecular_requirements":"Receptor is the alphaV/beta5 heterodimer; ITGB5 alone is not shown.","affinity_potency":[],"species_and_systems":"Human MDA-MB-231 breast cancer cells [PMID:9699501]. Mouse pair is ortholog-inferred.","localisation_and_range":"IBSP is flagged secreted [flag].","caveats":"Abstract only; antibody blocking is indirect. No database records for ITGB5 in our evidence.","key_references":[{"PMID":"9699501","why":"alpha(v)beta5 used for BSP-RGD adhesion and proliferation"}],"covers":["LR002758","LR006005"]},"LR007040":{"pair":"ICAM1 -> ITGAX:ITGB2","headline":"Complex-level row resting on one abstract-only SPR paper for ICAM-1 binding CD11c/CD18, plus BioGRID reconstituted-complex records.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 binds the CD11c/CD18 complex directly (surface plasmon resonance) and acts as agonist [PMID:16252253].","molecular_requirements":"Both chains are named: the evidence is for the alphaXbeta2 heterodimer; ICAM-1 domain D4 is required [PMID:16252253]. BioGRID lists ICAM1-ITGB2 reconstituted-complex records, which concern the shared beta2 chain [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the experiment [PMID:16252253]. Recombinant protein.","localisation_and_range":"ICAM1 is flagged secreted [flag], but the evidence concerns cell-surface adhesion (contact-dependent).","caveats":"Only one curated paper, abstract only. Reactome entries cited here describe ITGAL:ITGB2 (LFA-1) with ICAM1, not ITGAX [DB:Reactome]; the BioGRID records are for ITGB2, not specifically for CD11c.","key_references":[{"PMID":"16252253","why":"Direct ICAM-1 / CD11c-CD18 interaction by SPR"}],"covers":["LR007040"]},"LR004250":{"pair":"ICAM4 -> ITGA4","headline":"Single abstract-only study: alpha4beta1-dependent cell adhesion to ICAM-4-Fc, inferred from blocking experiments.","interaction_type":"functional only","direction_and_effect":"Adhesion of haemopoietic cell lines to ICAM-4-Fc was inhibited by LDV peptide and antibodies, identifying alpha4beta1 as the integrin; ICAM-4 is described as the first ICAM family member that is a ligand for non-beta2 integrins [PMID:11435317].","molecular_requirements":"The evidence points to the alpha4/beta1 heterodimer. Neither the LETS nor the LDV motif in ICAM-4 domain 1 was critical for integrin binding [PMID:11435317].","affinity_potency":[],"species_and_systems":"Human haemopoietic and non-haemopoietic cell lines with an ICAM-4-Fc construct [PMID:11435317]; the mouse pair is ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only, with no database support. Evidence is peptide and antibody inhibition of adhesion, not purified-protein binding. Affinity not reported.","key_references":[{"PMID":"11435317","why":"ICAM-4-Fc adhesion mediated by alpha4beta1"}],"covers":["LR000796","LR004250"]},"LR000803":{"pair":"ICAM5 -> ITGAL","headline":"Direct LFA-1 binding to ICAM-5 domain 1 is supported by human binding assays, a crystal structure record and UniProt.","interaction_type":"direct binding","direction_and_effect":"ICAM-5 domain 1 supports CD11a/CD18 interaction; deleting it abolishes binding, and antibodies to domain 1 block it [PMID:10741396]. LFA-1-mediated HL-60 adhesion to recombinant telencephalin was seen, curated as agonist [PMID:8995416]. PDB 3BN3 holds ICAM5 and ITGAL chains [DB:PDB 3BN3]; IntAct lists X-ray crystallography [DB:IntAct].","molecular_requirements":"The alphaL chain (LFA-1) is the partner. Only domain 1 of ICAM-5 is needed; domain 6 also supports leukocyte binding, possibly not via integrins [PMID:10741396]. Binding was divalent-cation- and PMA-independent, unlike canonical LFA-1 ligand binding [PMID:8995416].","affinity_potency":[{"value":"50 nM","assay":"lowest soluble ICAM-5 domain 1 concentration that inhibited T-cell binding to immobilized ICAM-5","system":"human T cells, immobilized ICAM-5","cite":"PMID:10741396"}],"species_and_systems":"Human ICAM-5 and LFA-1; human T cells binding rat hippocampal neurons [PMID:10741396]; HL-60 cells [PMID:8995416]. Mouse pair ortholog-inferred.","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; the cloning paper reports a single transmembrane region [PMID:8995416] and neuron-leukocyte adhesion is described in UniProt [DB:UniProt]: contact-dependent.","caveats":"Two papers shown are abstract only; two further confirmed rows and one pending row are not shown. The 50 nM figure is an inhibition concentration, not a Kd.","key_references":[{"PMID":"10741396","why":"Domain 1 of ICAM-5 binds CD11a/CD18; T cell-neuron assay"},{"PMID":"8995416","why":"LFA-1-mediated adhesion to human telencephalin"}],"covers":["LR000803","LR004257"]},"LR000812":{"pair":"IFNA17 -> IFNAR2","headline":"IFNA17 binds IFNAR2 on class-wide evidence from one abstract; IFNAR2 is the high-affinity chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR2 at 0.4-5 nM, except IFN-alpha1 at 220 nM [PMID:21856167]. GtoPdb lists IFNA17 as an agonist at IFNAR2 [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tighter-binding chain; IFNAR1 binds at 0.5-5 \u03bcM [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA17. Binding is to the isolated chain.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000812"]},"LR000821":{"pair":"IFNA5 -> IFNAR1","headline":"IFNA5 binds IFNAR1 only on class-wide evidence from one abstract; the chain is the weak-affinity subunit.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM [PMID:21856167]. GtoPdb lists IFNA5 as an agonist at IFNAR1 [DB:GtoPdb].","molecular_requirements":"IFNAR1 binds about 1000-fold more weakly than IFNAR2 per the curator's reading; IFNAR2 is the tighter chain [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA5. Binding is to the isolated chain, not the functional heterodimer.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000821"]},"LR011720":{"pair":"IFNA6 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA6 to an IFNA2:IFNAR1:IFNAR2 complex rests only on GtoPdb records for the individual chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA6 as an agonist at IFNAR1 and at IFNAR2 separately [DB:GtoPdb]. No paper in our evidence supports the complex as defined.","molecular_requirements":"The receptor entity contains IFNA2 (flagged secreted, not a receptor) plus IFNAR1 and IFNAR2 [flag]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experiments in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"No curator-verified paper; judged papers were abstract_insufficient or about a different entity. Support is database-only and the complex composition looks unusual.","key_references":[],"covers":["LR011720"]},"LR000830":{"pair":"IFNB1 -> IFNAR2","headline":"IFNB1 binds IFNAR2 directly; supported by several binding and functional papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"IFN-beta is an agonist at IFNAR2 [DB:GtoPdb]. Reactome lists the binding reaction IFN alpha/beta binds to IFNAR2 [DB:Reactome]. In mouse L929 cells expressing human IFNAR2 with mutations at E78, W101, I104 or D105, cells were unresponsive to hIFN-alpha2 but remained responsive to hIFN-beta [PMID:10395669].","molecular_requirements":"IFN-beta responsiveness persisted despite alpha2-binding-site mutations in IFNAR2, suggesting a distinct interface [PMID:10395669]. A glycan on IFN-\u03b2 mutein R27T at the IFNAR2 interface destabilised IFNAR2 binding and enhanced IFNAR1 binding [PMID:30733680]. Ternary complex formation with ifnar1-EC and ifnar2-EC was studied [PMID:17174979].","affinity_potency":[],"species_and_systems":"Human IFN and receptor ectodomains in vitro [PMID:17174979][PMID:30733680]; human IFNAR2 in mouse L929 cells [PMID:10395669]. Human and mouse pairs both listed.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"All three papers were read as abstracts or partial excerpts. The functional paper mainly characterises IFN-alpha2 and uses IFN-beta as a control [PMID:10395669]. No numeric affinity values are reported in our evidence.","key_references":[{"PMID":"17174979","why":"real-time binding of type I IFNs to ifnar1-EC and ifnar2-EC"},{"PMID":"30733680","why":"binary and ternary receptor-binding kinetics of IFN-\u03b2-1a and R27T"},{"PMID":"10395669","why":"IFNAR2 mutants responsive to IFN-beta but not IFN-alpha2"}],"covers":["LR000830","LR004270"]},"LR006014":{"pair":"IGF1 -> ITGB4","headline":"Integrin alpha6beta4 directly binds IGF1 in one verified study; ITGB4 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"alpha6beta4 directly bound IGF1 but not the R36E/R37E mutant, and IGF1 induced an alpha6beta4-IGF1-IGF1R ternary complex. In low-adhesion conditions IGF1 signaling, survival and soft-agar colony formation were alpha6beta4-dependent [PMID:22351760].","molecular_requirements":"Grafting the beta4 sequence WPNSDP (residues 167-172) onto integrin beta1 markedly enhanced IGF1 binding, implicating this beta4 loop in recognition [PMID:22351760]. The heterodimer was tested.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond a direct binding assay [PMID:22351760]. The mouse pair is ortholog-inferred.","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"Abstract-only read; no affinity value is reported in our evidence.","key_references":[{"PMID":"22351760","why":"alpha6beta4 binds IGF1; beta4 WPNSDP loop"}],"covers":["LR002768","LR006014"]},"LR006023":{"pair":"IGFBP7 -> IGF1R","headline":"One abstract-level study: IGFBP7 binds the IGF1R extracellular region competitively with IGF-1 and blocks activation.","interaction_type":"direct binding","direction_and_effect":"IGFBP7 pretreatment interfered with IGF1R activation and internalization by IGF-1/2, leaving inactive IGF1R on the cell surface and blocking PI3K-AKT signalling; binding of IGFBP7 and IGF-1 to IGF1R was mutually exclusive. Curator effect: antagonist [PMID:23250396].","molecular_requirements":"The N-terminal 97 amino acids of IGFBP7 were important for binding the extracellular portion of IGF1R and for preventing activation [PMID:23250396].","affinity_potency":[],"species_and_systems":"Human normal and breast cancer cells; curator notes human ligand and receptor [PMID:23250396]. The mouse pair is projected from human.","localisation_and_range":"IGFBP7 is annotated as secreted and IGF1R as transmembrane [flag].","caveats":"Abstract-only read; no affinity reported. Prolonged IGFBP7 exposure also activated 4E-BP1 and sensitised to apoptosis [PMID:23250396].","key_references":[{"PMID":"23250396","why":"IGFBP7 binds IGF1R competitively with IGF-1, blocks activation"}],"covers":["LR002777","LR006023"]},"LR005204":{"pair":"IL17C -> IL17RA","headline":"IL-17C binds a receptor complex of IL-17RA and IL-17RE; the evidence is one abstract-only paper, so IL-17RA alone is not shown.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17C bound a receptor complex of IL-17RA and IL-17RE on epithelial cells and stimulated proinflammatory cytokine, chemokine and antimicrobial peptide expression [PMID:21993848]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-17RA is needed with IL-17RE; the paper describes binding to the IL-17RA/IL-17RE complex, not IL-17RA alone [PMID:21993848]. Reactome lists IL17C dimer:IL17RA:IL17RE [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curators recorded human; the abstract does not name species for the imiquimod skin and DSS colitis models [PMID:21993848]. Mouse pair is ortholog-inferred.","localisation_and_range":"Autocrine action on epithelial cells is described [PMID:21993848]; IL-17C is annotated as secreted [flag].","caveats":"Abstract-only read. IL-17RA alone binding is not demonstrated. IL-17C was pro-inflammatory in skin but protective in colitis [PMID:21993848].","key_references":[{"PMID":"21993848","why":"IL-17C binds IL-17RA/IL-17RE complex on epithelial cells"}],"covers":["LR001858","LR005204"]},"LR012422":{"pair":"IL17RD -> FGFR2","headline":"Database-asserted only: UniProt says IL17RD (Sef) interacts with FGFR2; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt: interacts with FGFR1, FGFR2 and phosphorylated MAP2K1 or MAP2K2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners are annotated as receptors [flag].","caveats":"Three curated rows are still pending; no verified paper. Likely an intracellular receptor-receptor interaction rather than a ligand-receptor one.","key_references":[],"covers":["LR012422"]},"LR004304":{"pair":"IL18 -> IL18R1","headline":"IL-18 binds IL18R1 directly; supported by a co-crystal structure, binding assays and a Kd, all in human systems.","interaction_type":"direct binding","direction_and_effect":"IL-18 binds IL-18R alpha (IL18R1) and acts as an agonist: IL-1Rrp (IL18R1) conferred IL-18 binding and signal transduction on COS-1 cells [PMID:9325300], and GtoPdb lists IL18-IL18R1 as agonist [DB:GtoPdb].","molecular_requirements":"IL18R1 is the ligand-binding chain; a co-crystal structure shows IL-18 with both IL-18R alpha and beta ectodomains in a ternary complex [PMID:25500532], and IL-18R beta is needed for high affinity binding in cotransfected cells [PMID:11046021]. UniProt says IL18R1 binds IL18 but not IL1A or IL1B [DB:UniProt]. One paper reports CD48 associating with IL-18R alpha in KG-1 cells [PMID:15760905].","affinity_potency":[{"value":"Kd 18.5 nM","assay":"125I-IL-18 binding","system":"human L428 Hodgkin's line","cite":"PMID:9325300"},{"value":"Kd 11 nM (low affinity site)","assay":"binding after cotransfection with both receptor chains","system":"cotransfected cells; species human per curator","cite":"PMID:11046021"},{"value":"Kd 0.4 nM (high affinity site)","assay":"binding after cotransfection with both receptor chains","system":"cotransfected cells; species human per curator","cite":"PMID:11046021"}],"species_and_systems":"Experiments used human proteins and cells; the mouse pair is projected from human evidence (ortholog inferred) and not tested in our evidence.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"All four papers were read as abstracts (the structure paper also has full-text excerpts). Binding was inhibited by IL-18 but not IL-1beta [PMID:9325300]. The high affinity site needs the second chain, so IL18R1 alone is a lower-affinity receptor [PMID:11046021].","key_references":[{"PMID":"25500532","why":"Crystal structure of human IL-18 with both receptor ectodomains"},{"PMID":"9325300","why":"Receptor purification, Kd 18.5 nM, IL-18 binding in COS-1 cells"},{"PMID":"11046021","why":"Both chains needed for high affinity binding"}],"covers":["LR000874","LR004304"]},"LR007301":{"pair":"IL19 -> IL20RA:IL20RB","headline":"IL-19 binds and signals through the IL20RA:IL20RB (type I IL-20R) complex in human transfected cells.","interaction_type":"direct binding","direction_and_effect":"IL-19 binds the type I IL-20R complex (IL-20Ralpha/IL-20Rbeta), causing STAT3 phosphorylation and activation of a STAT-binding promoter [PMID:11564763]; agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"Both chains form the complex. IL-19 signals only through this type I complex and not through IL-22R/IL-20Rbeta [PMID:11564763]. Reactome lists IL19:IL20RA:JAK1:IL20RB [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human, receptor-transfected reporter cells [PMID:11564763].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Single paper, read as abstract only. Two other rows were review-only (not shown).","key_references":[{"PMID":"11564763","why":"IL-19 binds IL-20Ralpha/IL-20Rbeta and activates STAT3"}],"covers":["LR007301"]},"LR004313":{"pair":"IL1B -> IL1RAP","headline":"IL1RAP is an accessory chain needed for IL-1beta signalling and high-affinity binding; evidence is abstract-level plus database structures.","interaction_type":"direct binding","direction_and_effect":"IL-1 agonists bound IL-1R AcP-deficient cells through type I IL-1R but failed to activate NF-kappaB or AP-1 signalling, so IL1RAP is an essential signal-transducing component [PMID:9820540]. GtoPdb lists the pair as agonist [DB:GtoPdb].","molecular_requirements":"IL1RAP acts with IL1R1 in a ternary complex; IL-1RAcP contacts the back of IL-1R(I) wrapped around IL-1beta rather than binding IL-1beta alone (modelling) [PMID:11418113]. Reactome has IL1R1:IL1:IL1RAP [DB:Reactome]. PDB 3O4O and 4DEP contain IL1B and IL1RAP chains [DB:PDB 3O4O].","affinity_potency":[{"value":"70-fold reduced murine IL-1beta affinity without IL-1R AcP","assay":"binding to knockout fibroblasts","system":"IL-1R AcP-deficient mouse fibroblasts","cite":"PMID:9820540"}],"species_and_systems":"Fibroblasts and mice from IL-1R AcP-deficient animals with murine IL-1beta [PMID:9820540]; the abstract does not name the species for the other ligands beyond murine IL-1alpha and human IL-1Ra. Curated labels say human; the pair also exists for mouse.","localisation_and_range":"IL1B is flagged secreted and IL1RAP is flagged transmembrane (and secreted) [flag]; signalling is by a membrane receptor complex.","caveats":"Both papers were read as abstracts only. The 2001 paper is purely computational [PMID:11418113]. IL1RAP is a co-receptor, not a stand-alone receptor; IL-1alpha and IL-1Ra bound with only moderately reduced affinity without it [PMID:9820540].","key_references":[{"PMID":"9820540","why":"Knockout shows IL1RAP essential for signalling and for high-affinity IL-1beta binding"},{"PMID":"11418113","why":"Computational model of IL-1RAcP contacting the IL-1beta/IL-1R(I) complex"}],"covers":["LR000883","LR004313"]},"LR006032":{"pair":"IL1B -> ITGA5","headline":"IL-1beta binds integrin alpha5beta1 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alpha5beta1); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGA5:ITGB1 is a receptor for IL1B and binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002789","LR006032"]},"LR011225":{"pair":"IL1RN -> IL1RAP","headline":"Supported only by a GtoPdb antagonist record; no paper confirms direct IL1RN binding to IL1RAP.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists the interaction as Antagonist [DB:GtoPdb]; no affinity is given there.","molecular_requirements":"Not reported in our evidence; IL1RAP is generally a co-receptor chain, but our evidence does not say whether it binds IL1RN alone.","affinity_potency":[],"species_and_systems":"Human; no experimental system in our evidence.","localisation_and_range":"IL1RN flagged secreted; IL1RAP flagged transmembrane and secreted [flag].","caveats":"No papers judged; extraction found one different_entity and two abstract_insufficient rows. Database-only support.","key_references":[],"covers":["LR011225"]},"LR007310":{"pair":"IL2 -> IL2RA:IL2RB:IL2RG","headline":"The trimeric IL-2 receptor is the high-affinity form; support here is one background statement plus database records.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states IL-2 binds the high-affinity trimeric receptor [DB:UniProt]; GtoPdb lists agonist records for each chain [DB:GtoPdb]. The curated paper only states the composition as background [PMID:15265897].","molecular_requirements":"All three chains (IL2RA, IL2RB, IL2RG) are required for the high-affinity trimer; the lower-affinity form lacks IL2RA [DB:UniProt]. Crystal structures of IL2 with IL2RG chains exist [DB:PDB 3QAZ].","affinity_potency":[],"species_and_systems":"Human; no experiment on the trimer in the one paper, which studied soluble IL-15Ralpha [PMID:15265897].","localisation_and_range":"IL-2 flagged secreted; complex receptor flagged by member chains [flag].","caveats":"The only confirmed row is a background sentence rated low confidence by the curator [PMID:15265897]; read as abstract only. Effectively database-supported.","key_references":[{"PMID":"15265897","why":"States the composition of the high-affinity IL-2 receptor (background)"}],"covers":["LR007310"]},"LR004322":{"pair":"IL22 -> IL10RB","headline":"IL-22 signals through a receptor that includes IL10RB (CRF2-4) as the shared second chain; one abstract-level paper plus databases.","interaction_type":"functional only","direction_and_effect":"IL-22 is a ligand for CRF2-4 and, together with IL-22R, enables IL-22 signalling with STAT1, STAT3 and STAT5 activation [PMID:10875937]. GtoPdb lists an agonist (pEC50) [DB:GtoPdb]. No numeric value is given in our evidence.","molecular_requirements":"IL10RB works with IL22RA1; IL-22 signals through a heterodimer of IL22RA1 and shared IL10RB [DB:UniProt][PMID:10875937]. IL10RB alone is not shown sufficient.","affinity_potency":[],"species_and_systems":"Human, cell lines responsive to IL-22 [PMID:10875937]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-22 is flagged secreted [flag].","caveats":"The abstract asserts ligand status but reports no binding constant [PMID:10875937]. IntAct lists ELISA and SPR records [DB:IntAct]. Abstract only.","key_references":[{"PMID":"10875937","why":"IL-22 is a ligand for CRF2-4 (IL10RB)"}],"covers":["LR000892","LR004322"]},"LR000902":{"pair":"IL27 -> IL27RA","headline":"IL-27 acts through WSX-1 (IL27RA); evidence is functional attribution plus database records.","interaction_type":"functional only","direction_and_effect":"IL-27 (EBI3 plus p28) drives proliferation of naive CD4+ T cells and mediates its effects through the orphan receptor WSX-1/TCCR (agonist) [PMID:12121660]. UniProt describes IL27RA as the signal-transducing subunit for the p28/EBI3 heterodimer [DB:UniProt Q6UWB1]. GtoPdb lists IL-27 as an agonist [DB:GtoPdb].","molecular_requirements":"The active ligand is the p28+EBI3 heterodimer, not p28 alone [PMID:12121660]. IL27RA is described as a signal-transducing subunit [DB:UniProt Q6UWB1]; the co-receptor is not tested in this paper.","affinity_potency":[],"species_and_systems":"Human per the curator record [PMID:12121660]; the mouse pair is a separate non-inferred record. BioGRID lists Affinity Capture-Western from this paper [DB:BioGRID]. Structures 7U7N and 8D85 contain both chains [DB:PDB 7U7N].","localisation_and_range":"IL-27 is flagged secreted [flag].","caveats":"The paper was read as abstract only; the attribution to WSX-1 is a statement rather than a binding measurement [PMID:12121660]. The symbol IL27 corresponds to the p28 subunit, so the pair is really the heterodimer-receptor interaction. No affinity reported.","key_references":[{"PMID":"12121660","why":"Describes IL-27 and attributes its effects to WSX-1/TCCR."}],"covers":["LR000902","LR004331"]},"LR004331":{"pair":"IL27 -> IL27RA","headline":"IL-27 acts through WSX-1 (IL27RA); evidence is functional attribution plus database records.","interaction_type":"functional only","direction_and_effect":"IL-27 (EBI3 plus p28) drives proliferation of naive CD4+ T cells and mediates its effects through the orphan receptor WSX-1/TCCR (agonist) [PMID:12121660]. UniProt describes IL27RA as the signal-transducing subunit for the p28/EBI3 heterodimer [DB:UniProt Q6UWB1]. GtoPdb lists IL-27 as an agonist [DB:GtoPdb].","molecular_requirements":"The active ligand is the p28+EBI3 heterodimer, not p28 alone [PMID:12121660]. IL27RA is described as a signal-transducing subunit [DB:UniProt Q6UWB1]; the co-receptor is not tested in this paper.","affinity_potency":[],"species_and_systems":"Human per the curator record [PMID:12121660]; the mouse pair is a separate non-inferred record. BioGRID lists Affinity Capture-Western from this paper [DB:BioGRID]. Structures 7U7N and 8D85 contain both chains [DB:PDB 7U7N].","localisation_and_range":"IL-27 is flagged secreted [flag].","caveats":"The paper was read as abstract only; the attribution to WSX-1 is a statement rather than a binding measurement [PMID:12121660]. The symbol IL27 corresponds to the p28 subunit, so the pair is really the heterodimer-receptor interaction. No affinity reported.","key_references":[{"PMID":"12121660","why":"Describes IL-27 and attributes its effects to WSX-1/TCCR."}],"covers":["LR000902","LR004331"]},"LR006041":{"pair":"IL27 -> IL6ST","headline":"gp130 (IL6ST) is the signalling chain for IL-27 per databases; the one paper instead shows free p28 antagonising gp130.","interaction_type":"conflicting","direction_and_effect":"The paper reports that the heterodimeric IL-27 signals through IL-27R\u03b1 combined with gp130, but its own finding is that IL-27p28 alone, independent of EBI3, antagonised gp130-mediated signalling and IL-6-driven IL-17 and IL-10 production (antagonist) [PMID:21057510]. GtoPdb lists IL27-IL6ST as agonist [DB:GtoPdb].","molecular_requirements":"Gp130 works with IL-27R\u03b1; UniProt states gp130 engages site 3 of IL27 [DB:UniProt P40189]. Free p28 reduced STAT1/STAT3 phosphorylation by IL-6 and IL-27 and, in SPR, inhibited IL-6-sIL-6R\u03b1 interaction with chip-bound gp130; the IL-27p28-gp130 interaction itself was modelled, and its nature remains unclear [PMID:21057510].","affinity_potency":[],"species_and_systems":"Experiments used mouse cells and mice (bone-marrow macrophages and dendritic cells, CD4+ T cells, transgenic mice) [PMID:21057510]; the curator record lists human. The human pair is ortholog-inferred. Structures 7U7N and 8D85 contain both chains [DB:PDB 7U7N].","localisation_and_range":"IL-27 is flagged secreted and gp130 transmembrane [flag].","caveats":"Direction conflicts between sources: the database says agonist, the paper reports antagonism by free p28. The heterodimer-gp130 statement in the paper is background. Full-text excerpts show no direct measurement of IL-27-gp130 binding [PMID:21057510].","key_references":[{"PMID":"21057510","why":"IL-27p28 antagonises gp130 signalling; IL-27 background via IL-27R\u03b1 plus gp130."}],"covers":["LR002799","LR006041"]},"LR008030":{"pair":"IL31 -> IL31RA:OSMR","headline":"IL-31 signals through the IL31RA/OSMR heterodimer; supported by an abstract-level discovery paper and UniProt.","interaction_type":"functional only","direction_and_effect":"IL-31 signals through a receptor composed of IL-31 receptor A and oncostatin M receptor; the receptor mRNAs were induced in activated monocytes and constitutive in epithelial cells [PMID:15184896]. GtoPdb lists IL31 as agonist for both chains [DB:GtoPdb].","molecular_requirements":"Both chains are named: UniProt describes the IL31 receptor complex as a heterodimer of OSMR and IL31RA [DB:UniProt Q8NI17]. OSMRbeta is shared with oncostatin M, per the genetics paper [PMID:25054142].","affinity_potency":[],"species_and_systems":"Human per the curator record; IL-31-overexpressing transgenic mice developed pruritus and skin lesions [PMID:15184896]. PDB 22PL contains both chains [DB:PDB 22PL].","localisation_and_range":"IL-31 is flagged secreted [flag].","caveats":"Both papers read as abstract only. PMID:25054142 is a human OSMR mutation study (L613S) that names IL-31 as a ligand but does not test the interaction; it supports shared-chain use only. No binding data or affinity in our evidence.","key_references":[{"PMID":"15184896","why":"Discovery of IL-31 signalling via IL31RA and OSMR."}],"covers":["LR008030"]},"LR002801":{"pair":"IL36A -> IL1RAP","headline":"IL1RAP is a required co-receptor for IL-36 signalling in one functional paper; no direct ligand binding shown.","interaction_type":"functional only","direction_and_effect":"Antibodies against IL-1RAcP and a cytoplasmically deleted IL-1RAcP blocked NF-kappaB activation by IL-1F6, IL-1F8 and IL-1F9, so IL-1RAcP is required alongside IL-1Rrp2 [PMID:14734551]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"IL1RAP acts as co-receptor with IL-1Rrp2 (IL1RL2); IL1RAP alone is not shown to bind the ligand [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human cell lines (Jurkat, NCI/ADR-RES) [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Single abstract-only paper. It names the ligands IL-1F6/F8/F9; the abstract does not state which is IL36A. Reactome entry links the paper to IL36:IL1RL2 binding IL1RAP [DB:Reactome].","key_references":[{"PMID":"14734551","why":"IL-1RAcP required for IL-1F6/F8/F9 signalling"}],"covers":["LR002801","LR006043"]},"LR000911":{"pair":"IL4 -> IL13RA1","headline":"IL-4 engages IL-13Ralpha1 as second chain with IL-4Ralpha, weakly alone; supported by SPR and mouse knockout.","interaction_type":"direct binding","direction_and_effect":"IL-13Ralpha1 is required for IL-4-induced airway resistance, mucus, TGF-beta and eotaxin(s) in Il13ra1-/- mice [PMID:18480254]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"IL-13Ralpha1 is a second chain in the type II complex with IL-4Ralpha [PMID:23103943]. IL-4 on its own binds IL-13Ralpha1 with KD >1 uM [PMID:23103943].","affinity_potency":[{"value":"KD 4200 nM","assay":"SPR, IL-4/IL-4Ralpha complex binding IL-13Ralpha1","system":"recombinant human","cite":"PMID:23103943"}],"species_and_systems":"Recombinant human IL-4 [PMID:23103943]; mouse Il13ra1-/- allergen model [PMID:18480254]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-4 flagged secreted [flag].","caveats":"Paper 23103943 is partly an engineering study; excerpts used. 18480254 is dependence, not binding.","key_references":[{"PMID":"23103943","why":"SPR of IL-4 variants with IL-13Ralpha1"},{"PMID":"18480254","why":"IL-13Ralpha1 role in IL-4 responses in mice"}],"covers":["LR000911","LR004339"]},"LR004340":{"pair":"IL4 -> IL13RA2","headline":"No supporting paper; UniProt states IL13RA2 binds IL13 with high affinity but not IL4, so this pair looks unsupported.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence in our evidence. A UniProt note says the receptor interacts with high affinity with IL13 but not with IL4 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence (no experiments curated; mouse pair is ortholog-inferred).","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Papers judged: none confirmed (the curators' rows were different_entity or abstract_insufficient). The only database record argues against direct IL4 binding [DB:UniProt]. Treat as unsupported.","key_references":[],"covers":["LR000912","LR004340"]},"LR000920":{"pair":"IL7 -> IL7R","headline":"IL7 to IL7R supported by one confirmed functional paper plus databases; abstract-level.","interaction_type":"functional only","direction_and_effect":"IL-7 causes p85 of PtdIns 3-kinase to associate with IL-7R via phosphorylation of Tyr449 in the alpha chain [PMID:7522165]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL7R alpha chain acts with the common gamma chain [PMID:7522165]; the paper's result concerns the alpha chain only.","affinity_potency":[],"species_and_systems":"Human; mouse pair ortholog-inferred [PMID:7522165].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"One confirmed paper, read as abstract only, shows downstream signalling not binding. Four other papers were abstract_insufficient.","key_references":[{"PMID":"7522165","why":"IL-7-induced p85 association with IL-7R alpha, Tyr449"}],"covers":["LR000920","LR004348"]},"LR002810":{"pair":"IL9 -> IL2RB","headline":"IL9 to IL2RB rests only on a Reactome reaction that names IL2RG, not IL2RB; no papers.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence in our evidence. Reactome lists a reaction in which IL9 binds IL9R:JAK1 and IL2RG:JAK3 [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Secreted ligand [flag].","caveats":"Database-only; the Reactome reaction does not mention IL2RB. Three papers were judged a different entity.","key_references":[],"covers":["LR002810","LR006050"]},"LR006050":{"pair":"IL9 -> IL2RB","headline":"IL9 to IL2RB rests only on a Reactome reaction that names IL2RG, not IL2RB; no papers.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence in our evidence. Reactome lists a reaction in which IL9 binds IL9R:JAK1 and IL2RG:JAK3 [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Secreted ligand [flag].","caveats":"Database-only; the Reactome reaction does not mention IL2RB. Three papers were judged a different entity.","key_references":[],"covers":["LR002810","LR006050"]},"LR005213":{"pair":"JAM2 -> F11R","headline":"Genetic evidence in zebrafish suggests Jam1a-Jam2a interaction supports Notch signalling; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Zebrafish jam1a loss of function caused loss of Notch signalling and HSCs; activating Notch rescued HSCs in jam1a or jam2a deficient embryos [PMID:25119047]. The authors conclude Jam1a-Jam2a interactions facilitate Notch signal transduction [PMID:25119047].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Zebrafish embryos; the pair is ortholog-inferred for human and mouse [PMID:25119047].","localisation_and_range":"JAM2 flagged as not secreted, receptor transmembrane [flag]; the paper describes cell contact between somite and precursors [PMID:25119047].","caveats":"No binding assay, and zebrafish genes are mapped to human. The dossier lists experiment species as human, which the paper contradicts. No database records.","key_references":[{"PMID":"25119047","why":"Zebrafish Jam1a-Jam2a genetics"}],"covers":["LR001868","LR005213"]},"LR004403":{"pair":"LAMA1 -> ITGB8","headline":"Beta8-containing integrins mediate chick neuron interaction with laminin-1; functional, abstract-only, and by homology.","interaction_type":"functional only","direction_and_effect":"An anti-beta8 extracellular domain antibody blocked chick sensory neuron interactions with laminin-1, collagen IV and fibronectin, identifying the first ligands for beta8 integrins [PMID:7542940]. Record labelled Stimulatory [flag].","molecular_requirements":"Beta8-containing heterodimers mediate the interaction; the alpha partner is not specified in our evidence [PMID:7542940].","affinity_potency":[],"species_and_systems":"Chick embryonic sensory neurons; the human and mouse pairs are ortholog-inferred [PMID:7542940].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Abstract only; laminin-1 is a heterotrimer, so LAMA1 cannot be separated from its partner chains, and the integrin was stored per subunit instead of as a complex. No binding affinity reported.","key_references":[{"PMID":"7542940","why":"Beta8 integrins mediate neuron interaction with laminin-1"}],"covers":["LR000982","LR004403"]},"LR004412":{"pair":"LAMA4 -> ITGB1","headline":"Recombinant laminin alpha4 G domain binds alpha3beta1 with high affinity, and platelet adhesion to laminin-8 depends on beta1 integrins.","interaction_type":"direct binding","direction_and_effect":"alpha3beta1 bound with high affinity to recombinant G(919-1207) of laminin alpha4 [PMID:12454288]. Platelet adhesion to purified laminin-8 (alpha4beta1gamma1) was largely inhibited by anti-beta1 and anti-alpha6 antibodies [PMID:10585296]. Stimulatory per interaction record [flag].","molecular_requirements":"Receptors are alpha-beta1 heterodimers (alpha3beta1, and alpha6beta1 implicated), not ITGB1 alone [PMID:12454288][PMID:10585296].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to G(919-1207) (adhesion, not Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Human platelets and endothelial cells; recombinant G-domain [PMID:10585296][PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted; ITGB1 not secreted [flag]; laminin-8 is secreted by activated platelets [PMID:10585296].","caveats":"Both papers were read from abstracts only; the antibody result is indirect. One paper was review-only.","key_references":[{"PMID":"12454288","why":"alpha3beta1 binds alpha4 G domain"},{"PMID":"10585296","why":"Platelet adhesion to laminin-8 blocked by anti-beta1"}],"covers":["LR000993","LR004412"]},"LR004421":{"pair":"LAMB1 -> ITGB1","headline":"Laminin beta1-containing laminins engage integrin beta1 pairings (alpha3, alpha6, alpha7); many binding and blocking studies, chain-level only.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha3beta1 [PMID:16413178]; laminin-10/11 is a high-affinity alpha3beta1 ligand [PMID:15677332]. Anti-beta1 antibodies blocked platelet adhesion to laminin [PMID:10585296] and A549 adhesion to laminin-10/11 [PMID:9624186]; alpha7beta1 mediates myoblast migration on laminin-1/-2 [PMID:11278916]. Annotated stimulatory.","molecular_requirements":"ITGB1 works in alpha/beta heterodimers with specificity set by the alpha partner; ITGB1 alone and LAMB1 alone were not tested. A PDB entry has chains P07942 and P05556 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha3beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins, human A549 cells and platelets, and human-labelled myoblasts [PMID:16413178][PMID:9624186][PMID:10585296][PMID:11278916]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The Kd belongs to alpha3beta1. Most confirming papers are abstract-only, antibody-blocking adhesion readouts. One further paper was review_only.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"},{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand"},{"PMID":"11278916","why":"Alpha7beta1 and myoblast migration on laminin"}],"covers":["LR001002","LR004421"]},"LR006104":{"pair":"LAMB2 -> ITGB4","headline":"LAMB2 (in laminin-511/521) binds integrin alpha6beta4 at Kd 25 nM; plus an abstract-level binding report.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521, which contains LAMB2, bound recombinant alpha6beta4 in solid-phase assays [PMID:16413178]. Alpha6beta4 was also reported as a receptor for laminin isoforms 1, 2, 4 and 5 in radioligand-binding and adhesion assays [PMID:7721947]. Annotated effect is Stimulatory [flag].","molecular_requirements":"The tested binder is the alpha6beta4 heterodimer and the ligand the assembled laminin heterotrimer; ITGB4 alone was not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 25 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta4 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; 804G rat bladder epithelial cells with laminin of unstated origin [PMID:7721947]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. PMID:7721947 was read as abstract only and its species is ambiguous.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-511/521"},{"PMID":"7721947","why":"alpha6beta4 receptor for several laminins, abstract only"}],"covers":["LR002870","LR006104"]},"LR011126":{"pair":"LAMB3 -> ITGA6:ITGB4","headline":"LAMB3 co-precipitates with ITGA6 in human keratinocytes; one paper, mapped to the ITGA6:ITGB4 complex.","interaction_type":"direct binding","direction_and_effect":"Endogenous immunoprecipitation showed ITGA6 co-precipitates with LAMB3 in HOK cells, with a predicted structural model [PMID:41960183]. The paper's introduction describes laminin-332 binding the alpha6beta4 receptor, citing other work [PMID:41960183].","molecular_requirements":"The IP tested ITGA6, not the ITGA6:ITGB4 complex; ITGB4 contribution is not shown by this paper. ITGB4 induction was comparatively muted in the data [PMID:41960183].","affinity_potency":[],"species_and_systems":"Human oral keratinocyte (HOK) cells [PMID:41960183].","localisation_and_range":"Ligand flagged secreted and receptor complex flagged transmembrane [flag]; range otherwise not reported.","caveats":"Co-IP of ITGA6 does not show direct binding or the role of ITGB4. One abstract_insufficient paper is not shown. Complex is flagged transmembrane [flag].","key_references":[{"PMID":"41960183","why":"Co-IP of ITGA6 with LAMB3 in HOK cells"}],"covers":["LR011126"]},"LR011081":{"pair":"LAMB3 -> ITGA9:ITGB1","headline":"No paper verifies LAMB3 with ITGA9:ITGB1; the only database record concerns alpha2beta1.","interaction_type":"database-asserted only","direction_and_effect":"Only Reactome integrin alpha2beta1 binding laminin-332 is recorded [DB:Reactome R-HSA-349626]; it does not name alpha9beta1.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. One paper was abstract_insufficient, one pending, one different_entity.","key_references":[],"covers":["LR011081"]},"LR004430":{"pair":"LAMC1 -> ITGB1","headline":"LAMC1 (in several laminins) binds beta1 integrins; Kd 3.4 nM in recombinant assay plus adhesion-blocking studies.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha3beta1 in solid-phase assays [PMID:16413178]. Platelet adhesion to platelet laminin was largely inhibited by anti-beta1 and anti-alpha6 antibodies [PMID:10585296]. A549 adhesion to laminin-10/11 was inhibited by anti-alpha3 or anti-beta1 antibodies [PMID:9624186]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Binders are alpha-beta1 heterodimers (alpha3beta1, alpha6beta1, alpha7beta1 across papers), never ITGB1 alone; ligands are assembled laminin heterotrimers, so LAMC1 is one chain [PMID:16413178]. PDB 7CEC lists chains of P11047 and P05556 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; human platelets [PMID:10585296]; human A549 cells [PMID:9624186]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. The other papers were read as abstracts only and use antibody blocking (functional). Eight confirmed rows but only four papers are shown; PMID:11278916 is also listed.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"},{"PMID":"9624186","why":"Anti-beta1 blocks A549 adhesion to laminin-10/11, abstract only"},{"PMID":"10585296","why":"Anti-beta1 blocks platelet adhesion to laminin, abstract only"}],"covers":["LR001012","LR004430"]},"LR001019":{"pair":"LCN2 -> LRP2","headline":"Megalin (LRP2) binds NGAL/LCN2 with high affinity by surface plasmon resonance and mediates its uptake.","interaction_type":"direct binding","direction_and_effect":"Megalin bound NGAL with high affinity by surface plasmon resonance, and a rat yolk sac cell line endocytosed NGAL by a mechanism completely blocked by an anti-megalin antibody [PMID:15670845]. It acts as an uptake receptor.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NGAL with rat megalin-expressing yolk sac cells [PMID:15670845]; mouse pair is ortholog-projected.","localisation_and_range":"LCN2 flagged secreted [flag]; megalin described as expressed in polarized epithelia [PMID:15670845].","caveats":"Abstract only; the numeric affinity is not given in the abstract.","key_references":[{"PMID":"15670845","why":"SPR binding and uptake of NGAL by megalin"}],"covers":["LR001019","LR004437"]},"LR006113":{"pair":"LGALS1 -> CD7","headline":"Galectin-1 binds T-cell glycoproteins including CD7, and CD7 is needed for galectin-1-induced T-cell death.","interaction_type":"functional only","direction_and_effect":"CD7 is required for galectin-1-mediated T-cell death, making galectin-1/CD7 a death-signalling pair; the abstract states galectin-1 binds CD7 as background [PMID:10946254].","molecular_requirements":"Galectin-1 binds several T-cell surface glycoproteins, not CD7 alone [PMID:10946254].","affinity_potency":[],"species_and_systems":"Human T cells; ligand and receptor both human [PMID:10946254]. Mouse pair ortholog-inferred. BioGRID reports Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"Galectin-1 flagged secreted and receptor [flag]; acts on T-cell surface [PMID:10946254].","caveats":"Binding is cited as background, not shown by this paper; abstract-only read. Other galectin-1 receptors also contribute to death signalling.","key_references":[{"PMID":"10946254","why":"CD7 required for galectin-1-induced T-cell death"}],"covers":["LR002879","LR006113"]},"LR005222":{"pair":"LGALS3 -> LAG3","headline":"Galectin-3 binds LAG-3 on CD8+ T cells and LAG-3 is needed for galectin-3 suppression of IFN-gamma in vitro.","interaction_type":"functional only","direction_and_effect":"Galectin-3 suppressed CD8+ T cells in a LAG-3-dependent way: wild-type cells showed a 20% reduction in IFN-gamma at 150 ug/mL or higher, while LAG-3 knockout cells did not [PMID:25691328]. PD-1 knockout had minimal effect [PMID:25691328].","molecular_requirements":"Co-immunoprecipitation of LAG-3 with galectin-3 in activated CD8+ T cell lysates, with a cross-linked LAG-3/galectin-3 complex at 150-250 kD; PD-1 did not co-precipitate [PMID:25691328].","affinity_potency":[],"species_and_systems":"Mouse T cells and galectin-3-deficient mice, tumour models; curator lists human [PMID:25691328]. Human pair is ortholog-inferred.","localisation_and_range":"Galectin-3 binds activated CD8+ T cells only in the tumour microenvironment [PMID:25691328]; LAG3 flagged transmembrane [flag].","caveats":"Read depth recorded as abstract only although full-text excerpts exist. Glycan dependence and affinity not reported in our excerpts.","key_references":[{"PMID":"25691328","why":"Galectin-3 binds LAG-3; needed for CD8+ T-cell suppression"}],"covers":["LR001880","LR005222"]},"LR006122":{"pair":"LGALS3 -> MUC1","headline":"Galectin-3 binds the MUC1 extracellular domain and promotes MUC1-EGFR association; one paper, curated as direct binding but read from the abstract.","interaction_type":"direct binding","direction_and_effect":"Binding of galectin-3 to the MUC1 extracellular domain induces MUC1 cell surface polarization and increases MUC1-EGFR association, leading to increased EGFR dimerization and activation (agonist-like) [PMID:28731466].","molecular_requirements":"Requires both the galectin-3 C-terminal carbohydrate recognition domain and its N-terminal multimerization domain; the truncated galectin-3C lacking the multimerization domain had no effect [PMID:28731466].","affinity_potency":[],"species_and_systems":"Human HCT116 colon and HBL-100-derived breast epithelial cells expressing MUC1; mouse pair is ortholog-inferred [PMID:28731466].","localisation_and_range":"Both partners carry a secreted flag [flag]; galectin-3 was added exogenously to cells, so it acts as a secreted ligand on membrane MUC1.","caveats":"Binding itself was curated from the abstract (read depth abstract only); full-text passages show the functional readouts (EGFR phosphorylation) rather than a direct binding measurement. Without EGF, galectin-3 had no significant effect on EGFR activation; endogenous cell-surface galectin-3 contributed minimally [PMID:28731466]. No affinity reported.","key_references":[{"PMID":"28731466","why":"Galectin-3 binding to MUC1 promotes EGFR dimerization and activation in epithelial cancer cells"}],"covers":["LR002888","LR006122"]},"LR002900":{"pair":"LGALS8 -> ITGB1","headline":"Galectin-8 binds alpha3beta1 integrin from carcinoma and other cells and blocks cell adhesion, inducing apoptosis; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Galectin-8 inhibited adhesion of human 1299 carcinoma cells to plates coated with integrin ligands and induced apoptosis (antagonist of adhesion); effects were not mimicked by galectin-1 or galectin-3, and Mn2+ abolished the inhibition [PMID:10852818].","molecular_requirements":"The integrin identified is alpha3beta1, so both ITGA3 and ITGB1 chains are involved; whether one chain suffices is not reported in our evidence [PMID:10852818].","affinity_potency":[],"species_and_systems":"Human 1299 carcinoma cells; alpha3beta1 also from HeLa and human endothelial cells; mouse pair is ortholog-inferred [PMID:10852818].","localisation_and_range":"Galectin-8 is a secreted protein (secreted flag [flag]); endogenous galectin-8 secreted from 1299 cells forms complexes with surface alpha3beta1 integrin [PMID:10852818].","caveats":"Abstract only. Binding is sugar-dependent (a beta-galactoside lectin reading glycans) [PMID:10852818]. BioGRID lists Affinity Capture-Western and Reconstituted Complex records [DB:BioGRID]. No affinity reported. Human pair is ortholog-inferred in the interaction list.","key_references":[{"PMID":"10852818","why":"Galectin-8 binding to alpha3beta1 integrin inhibits adhesion and induces apoptosis"}],"covers":["LR002900","LR006130"]},"LR006131":{"pair":"LGALS8 -> PDPN","headline":"Galectin-8 interacts with podoplanin in a glycosylation-dependent manner, found by protein array; functional effects on lymphatic endothelial cells.","interaction_type":"direct binding","direction_and_effect":"Galectin-8 promoted lymphatic endothelial cell adhesion and haptotactic migration when immobilized, but inhibited tube formation when incorporated into a collagen matrix [PMID:19268462].","molecular_requirements":"Interaction depends on podoplanin glycosylation, tested with Fc glycoforms from different cell lines; podoplanin's O-glycans matter [PMID:19268462].","affinity_potency":[],"species_and_systems":"Recombinant human galectin-8 with podoplanin-Fc; human lymphatic and blood endothelial cells. Mouse pair is ortholog-inferred [PMID:19268462].","localisation_and_range":"Podoplanin is a membrane glycoprotein; galectin-8 is secreted per flag [flag]. UniProt notes a possible role in connecting lymphatic endothelium to matrix [DB:UniProt].","caveats":"Abstract and full-text excerpts show a protein-array hit as the only interaction above threshold; other galectins on the array were negative [PMID:19268462]. Other glycoproteins probably cooperate. No affinity in the excerpts shown.","key_references":[{"PMID":"19268462","why":"Galectin-8 identified as glycosylation-dependent podoplanin partner"}],"covers":["LR002902","LR006131"]},"LR005231":{"pair":"LGI3 -> ADAM22","headline":"LGI3 associates with ADAM22 in LPS-treated HaCaT keratinocytes; one abstract, plus Reactome records.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation, flow cytometry and immunocytochemistry revealed LGI3 associated with ADAM22 in LPS-treated keratinocytes [PMID:31627033]. Reactome lists LGI3 binding ADAM22,23,syntaxin1 [DB:Reactome]. Effect direction not reported in our evidence.","molecular_requirements":"Reactome binding reaction involves ADAM22, ADAM23 and syntaxin1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"HaCaT human keratinocytes, cell-based assays [PMID:31627033]. The mouse pair is not ortholog-inferred.","localisation_and_range":"LGI3 is secreted by LPS-stimulated HaCaT cells [PMID:31627033].","caveats":"Abstract only; association by co-IP does not demonstrate direct binding. Two rows were judged different_entity.","key_references":[{"PMID":"31627033","why":"LGI3 associates with ADAM22 in keratinocytes"}],"covers":["LR001889","LR005231"]},"LR001028":{"pair":"LPA -> ITGAM","headline":"Lp(a) binds integrin Mac-1 (ITGAM/ITGB2) via apo(a); one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Through its apo(a) moiety Lp(a) specifically interacts with the beta2-integrin Mac-1, promoting monocyte adhesion and transendothelial migration; engagement activates NF-kappaB and induces tissue factor expression [PMID:16403785].","molecular_requirements":"The ligand part is apo(a); the receptor is the Mac-1 heterodimer (alphaM beta2), so ITGAM and ITGB2 both matter [PMID:16403785]. Binding is blocked by plasminogen/angiostatin kringle 4 and strengthened by homocysteine [PMID:16403785].","affinity_potency":[],"species_and_systems":"Human proteins; monocytes and atherosclerotic plaques [PMID:16403785].","localisation_and_range":"LPA is flagged secreted [flag]; Lp(a) is a circulating lipoprotein acting on cell-surface integrin.","caveats":"One paper, abstract only; no affinity reported. No database record. The evidence concerns the heterodimer, not ITGAM alone.","key_references":[{"PMID":"16403785","why":"Lp(a) apo(a) binds Mac-1 and promotes monocyte adhesion"}],"covers":["LR001028"]},"LR008999":{"pair":"LPL -> SDC1","headline":"SDC1 binds LPL in cells; one full-text co-IP paper shows intracellular sorting, a second shows syndecan-mediated lipoprotein catabolism.","interaction_type":"direct binding","direction_and_effect":"In HeLa cells, SDC1 acts as a sorting receptor capturing LPL at the trans-Golgi network, and exogenous GFP-LPL and Flag-SDC1 co-immunoprecipitated [PMID:31543446]. This is intracellular sorting, not a signalling effect. Syndecan transfection in CHO cells increased cell association and degradation of lipase-enriched lipoproteins [PMID:9294130].","molecular_requirements":"LPL sorting requires bivalent interaction with SDC1 heparan sulfate chains and with the Golgi membrane [PMID:31543446]. Knockdown of SDC1 alone, among four syndecans, reduced LPL co-sorting; an SDC1 mutant lacking heparan sulfate was tested in rescue [PMID:31543446]. Other syndecans also increased lipoprotein catabolism [PMID:9294130].","affinity_potency":[],"species_and_systems":"Human proteins; HeLa cells [PMID:31543446]; transfected CHO cells [PMID:9294130].","localisation_and_range":"SDC1 is annotated transmembrane and secreted, LPL secreted [flag]. The binding is described in the secretory pathway [PMID:31543446].","caveats":"Interaction is largely heparan sulfate (GAG) mediated, so it is not a typical protein-protein receptor binding. The 1997 paper is abstract only and functional rather than a binding assay [PMID:9294130]. Affinity not reported in our evidence.","key_references":[{"PMID":"31543446","why":"Co-IP and sorting of LPL by SDC1 at the TGN"},{"PMID":"9294130","why":"Syndecans mediate internalisation of lipase-enriched lipoproteins"}],"covers":["LR008999"]},"LR006140":{"pair":"LRFN4 -> PTPRF","headline":"LRFN4 (SALM3) binds LAR-family RPTPs including PTPRF in a splice-dependent trans-synaptic interaction; one paper, plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SALM3 interacts with and requires all three LAR-RPTPs (LAR, PTP-sigma, PTP-delta) for presynaptic differentiation [PMID:26321637]. The interaction needs the mini-exon B insert in the LAR-RPTP [PMID:26321637]. Reactome lists SALM3 binding LAR-RPTP [DB:Reactome].","molecular_requirements":"LAR-RPTPs containing meB alone bound SALM3, those with only meA or neither did not; adding meA to meB increased binding. Ig1-3 domains of PTP-delta were sufficient [PMID:26321637].","affinity_potency":[],"species_and_systems":"Paper reports mouse SALM3 and mouse PTP-delta in its assays; dossier species fields say human and the mouse pair is ortholog-inferred [PMID:26321637]. Cell-binding and co-culture assays, plus Salm3 knockout mice [PMID:26321637].","localisation_and_range":"Both flagged transmembrane for the pair, so contact-dependent trans-synaptic adhesion [flag][PMID:26321637].","caveats":"Evidence is family-level for all LAR-RPTPs; pair-specific data for PTPRF are not separated in our evidence. Paper read only as abstract per record, though full-text excerpts are present. Affinity not reported in our evidence.","key_references":[{"PMID":"26321637","why":"SALM3 binds LAR-RPTPs in a meB-dependent manner"}],"covers":["LR002915","LR006140"]},"LR001037":{"pair":"LRPAP1 -> LRP2","headline":"RAP (LRPAP1) binds LRP2 (gp330) with high affinity at two mapped RAP sites; foundational 1994 evidence plus structure and database records.","interaction_type":"direct binding","direction_and_effect":"RAP binds gp330 with high affinity in a Ca2+-dependent manner and is an effective inhibitor of ligand binding to gp330 and LRP [PMID:7512726]. Curators label it an antagonist [PMID:7512726].","molecular_requirements":"gp330 binds two separate sites on RAP, residues 85-148 and 178-248; the heparin site is between residues 261 and 323 [PMID:7512726].","affinity_potency":[],"species_and_systems":"Biochemical binding studies (ligand blotting, affinity chromatography, fusion proteins); the paper's species is listed as human [PMID:7512726]. Databases: PDB structure [DB:PDB 9QAW], BioGRID [DB:BioGRID], UniProt [DB:UniProt]. Both listed species are ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted [flag]. The abstract says RAP is most abundant in the ER lumen and may function in receptor folding or trafficking [PMID:7512726].","caveats":"No affinity value in our evidence. RAP is a chaperone/inhibitor, not a signalling ligand. Abstract only.","key_references":[{"PMID":"7512726","why":"gp330 binds RAP with high affinity; two RAP binding sites mapped"}],"covers":["LR001037","LR004451"]},"LR005240":{"pair":"LRRC4B -> PTPRS","headline":"NGL-3 (LRRC4B) interacts with PTPsigma via its first two FNIII domains for bidirectional synapse formation; supported by two papers and Reactome.","interaction_type":"direct binding","direction_and_effect":"PTPsigma interacts with NGL-3 via its first two FNIII domains, and this promotes synapse formation bidirectionally, like LAR [PMID:20139422]. Curators label it agonist [PMID:20139422]. PTPsigma mutants expressed on HEK293T cells bound recombinant NGL-3-Fc [PMID:29934346].","molecular_requirements":"The first two FNIII domains of PTPsigma are involved [PMID:20139422]. Three PTPsigma mutants still bound NGL-3-Fc [PMID:29934346].","affinity_potency":[],"species_and_systems":"HEK293T binding assays and rat neurons [PMID:29934346]; species of the first paper listed as human [PMID:20139422]. Reactome lists the complex [DB:Reactome]. Both listed species are ortholog-inferred.","localisation_and_range":"Membrane-bound, contact-dependent trans-synaptic adhesion (annotation [flag]).","caveats":"No affinity in our evidence. 29934346 was read via browser and the quote is marked unverifiable pending spot-check. Four other judged papers were review_only and two abstract_insufficient. Paralogs PTPRF and PTPRD bind the same ligand.","key_references":[{"PMID":"20139422","why":"NGL-3 binds PTPsigma and drives bidirectional synapse formation"},{"PMID":"29934346","why":"PTPsigma mutants bind NGL-3-Fc"}],"covers":["LR001898","LR005240"]},"LR008003":{"pair":"LTA:LTB -> LTBR","headline":"The lymphotoxin heteromer as ligand of LTBR is supported by database records only; no verified paper in this dossier.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper here (curator outcome review_only). UniProt says LTBR is the receptor for the heterotrimeric lymphotoxin containing LTA and LTB, and LTA binds LTBR in its heterotrimeric form with LTB [DB:UniProt].","molecular_requirements":"Both LTA and LTB subunits are required per UniProt; a heterotrimer of the form LTA(1)-LTB(2) is referred to in UniProt text [DB:UniProt]. Reactome lists LTBR:lymphotoxin,TNFSF14 complexes [DB:Reactome]; a structure is deposited [DB:PDB 4MXW]. GtoPdb lists LTA-LTBR and LTB-LTBR [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species and assays not reported in our evidence.","localisation_and_range":"LTBR flagged transmembrane [flag]; membrane-anchored lymphotoxin implies contact-dependent signalling, not stated in this dossier.","caveats":"No papers judged. Separate dossiers for LTA and LTB individually carry the primary papers. Affinity not reported.","key_references":[],"covers":["LR008003"]},"LR001046":{"pair":"LTF -> LRP1","headline":"Lactoferrin binds LRP1 and both blocks uptake of other ligands and drives mitogenic signalling; evidence mixes bovine and human/rat systems.","interaction_type":"direct binding","direction_and_effect":"Bovine lactoferrin bound LRP on blots and blocked LRP-dependent cholesteryl ester synthesis stimulation in cultured human fibroblasts, acting as a competitive inhibitor of other ligands [PMID:1464627]. In osteoblasts, lactoferrin induced RAP-sensitive p42/44 MAPK signalling and proliferation, reduced in LRP1-null fibroblasts [PMID:15178744].","molecular_requirements":"RAP, an LRP1/2 inhibitor, blocked lactoferrin endocytosis and signalling [PMID:15178744]. Endocytic and signalling functions of LRP1 are independent of each other [PMID:15178744]. LRP has at least three distinct, partially overlapping ligand sites [PMID:1464627].","affinity_potency":[],"species_and_systems":"Bovine lactoferrin with LRP in cultured human fibroblasts [PMID:1464627]; primary rat osteoblasts, human SaOS-2 cells and LRP1-null fibroblasts [PMID:15178744]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Lactoferrin flagged secreted [flag]; endocytic receptor uptake from the extracellular space [PMID:15178744].","caveats":"Both papers abstract-only. No affinity. In 15178744, osteoblasts also express LRP2, so LRP1-specificity relies on SaOS-2 and LRP1-null cells. Human lactoferrin was not used in the first paper.","key_references":[{"PMID":"1464627","why":"LRP binds lactoferrin and blocks other ligands"},{"PMID":"15178744","why":"LRP1-dependent lactoferrin mitogenic signalling"}],"covers":["LR001046","LR004459"]},"LR001055":{"pair":"MDK -> ALK","headline":"Midkine binds ALK with picomolar apparent affinity on intact human cells, but curators mark the pair as contested.","interaction_type":"direct binding","direction_and_effect":"Midkine binds ALK and stimulates ALK phosphorylation in WI-38 fibroblasts and activates PI3-kinase and MAP kinase signalling (agonist). Anti-ALK antibodies blocked MK binding and MK-stimulated colony formation [PMID:12122009].","molecular_requirements":"ALK extracellular ligand-binding domain is involved; pleiotrophin competes for ALK binding [PMID:12122009].","affinity_potency":[{"value":"Kd 170 pM","assay":"apparent Kd of MK binding to ALK","system":"intact human cells","cite":"PMID:12122009"},{"value":"Kd 20 pM","assay":"apparent Kd of PTN competition of MK binding","system":"intact human cells","cite":"PMID:12122009"}],"species_and_systems":"Human cells (SW-13, WI-38, HUVEC, SH-SY5Y, U87MG) and athymic nude mice for tumour growth [PMID:12122009]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane; ALK is a transmembrane receptor [flag]. Secreted growth factor, paracrine.","caveats":"Curator notes the pair is contested, not accepted in much of the ALK literature, and warrants downweighting pending independent replication. Abstract only. Reactome, BioGRID and UniProt records exist [DB:Reactome][DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"12122009","why":"MK-ALK binding, blockade and signalling"}],"covers":["LR001055","LR004468"]},"LR001901":{"pair":"MDK -> NOTCH2","headline":"Midkine reported to bind NOTCH2 and activate its signalling in human keratinocytes; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"MK binds the Notch2 receptor in HaCaT keratinocytes and activates Notch2 signalling (agonist), linked to Hes1 and Jak2/Stat3 and to EMT [PMID:18469519].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes [PMID:18469519]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK flagged secreted; NOTCH2 flagged transmembrane [flag]. Paracrine.","caveats":"Single paper, abstract only; binding assay not described. Curator notes this is a non-canonical pairing. Reactome has binding and complex records [DB:Reactome].","key_references":[{"PMID":"18469519","why":"MK-Notch2 binding and signalling in HaCaT cells"}],"covers":["LR001901","LR005243"]},"LR001064":{"pair":"MDK -> TSPAN1","headline":"One abstract-only paper reports midkine interacting with TSPAN1 in head and neck cancer cells; assay not detailed.","interaction_type":"direct binding","direction_and_effect":"Midkine interacted with TSPAN1 and promoted TSPAN1 association with integrin alpha6beta1 in HNSCC cells, with FAK, paxillin and Stat1alpha activation and increased migration/invasiveness [PMID:18851943].","molecular_requirements":"Signalling is described as integrin-dependent, with TSPAN1-alpha6beta1 integrin association [PMID:18851943].","affinity_potency":[],"species_and_systems":"Human HNSCC cells [PMID:18851943]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence; midkine flagged secreted [flag]. TSPAN1 is a tetraspanin and its extracellular binding site is not described.","caveats":"Abstract-only; the physical assay for the MK-TSPAN1 interaction is not given, and our curated 'direct_binding' label may overstate it. Acts as an integrin-organising partner rather than a classic receptor, and no affinity.","key_references":[{"PMID":"18851943","why":"MK interacts with TSPAN1 and enhances TSPAN1-integrin association in HNSCC cells"}],"covers":["LR001064","LR004477"]},"LR001073":{"pair":"MMP13 -> LRP1","headline":"MMP-13 is an LRP1 endocytic ligand per ligand blot and SPR; support from one 1999 rat paper and a 2020 survey.","interaction_type":"direct binding","direction_and_effect":"LRP-1 mediates collagenase-3 internalization [PMID:10514495]. SPR shows MMP-13 (E204A) binds LRP-1, and TIMP-3 increases affinity 7.6-fold, TIMP-1 and TIMP-2 by 2.4- and 4.6-fold [PMID:32694578].","molecular_requirements":"Rat work proposes a two-step mechanism using a specific 170-kDa collagenase-3 receptor plus LRP1 [PMID:10514495]. TIMP-bound complexes bind LRP-1 better [PMID:32694578].","affinity_potency":[{"value":"KD 25.6 nM","assay":"SPR, catalytically inactive MMP-13 (E204A)","system":"purified LRP-1","cite":"PMID:32694578"}],"species_and_systems":"Rat osteoblastic UMR 106-01 cells [PMID:10514495]; human proteins in SPR [PMID:32694578].","localisation_and_range":"MMP-13 flagged secreted [flag]; cleared by endocytosis [PMID:10514495].","caveats":"Abstract-only reading. The SPR used an inactive mutant, not wild-type enzyme. The 2020 paper's MMP-1 and MMP-13 rows share one abstract [PMID:32694578]. Ligand-blot evidence is indirect for LRP1 identity.","key_references":[{"PMID":"10514495","why":"Ligand blot; LRP1 required for collagenase-3 internalization"},{"PMID":"32694578","why":"SPR affinity with TIMP bridging"}],"covers":["LR001073","LR004485"]},"LR001910":{"pair":"MRC1 -> PTPRC","headline":"MRC1 binds CD45 (PTPRC); two abstract-only papers, one glycoform-dependent.","interaction_type":"direct binding","direction_and_effect":"The mannose receptor cysteine-rich domain binds two low molecular weight CD45 isoforms in a sugar-dependent manner [PMID:10575006]. MRC1 on dendritic cells interacts directly with CD45 on T cells and inhibits its phosphatase activity, inducing T-cell tolerance [PMID:27601670].","molecular_requirements":"Binding depends on the cysteine-rich domain acting as a lectin and on cell-specific, possibly sulfated, CD45 glycoforms [PMID:10575006].","affinity_potency":[],"species_and_systems":"Ligand blots of mouse spleen and lymph node lysates [PMID:10575006]; DC/T-cell coculture in vitro and in vivo [PMID:27601670]. Dossier labels experiments human.","localisation_and_range":"Both are membrane proteins [flag], so contact-dependent between dendritic cells/macrophages and T cells.","caveats":"Both papers read as abstracts only. Binding is glycoform-conditional, so it will not hold in every CD45-expressing cell. One IntAct solid-phase record [DB:IntAct P22897-P08575].","key_references":[{"PMID":"10575006","why":"CR-Fc binds CD45 glycoforms"},{"PMID":"27601670","why":"Direct MR-CD45 interaction inhibits phosphatase"}],"covers":["LR001910","LR005250"]},"LR001082":{"pair":"MYOC -> FZD1","headline":"Myocilin-AP fusion bound FZD1 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. UniProt also records MYOC interacting with FZD1 [DB:UniProt].","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001082","LR004493"]},"LR001091":{"pair":"NDP -> FZD4","headline":"Norrin binds Frizzled-4 with high affinity and activates Wnt/beta-catenin signalling with LRP5/6; two papers plus GtoPdb support it.","interaction_type":"direct binding","direction_and_effect":"Norrin is an agonist of FZD4: MBP-Norrin raised TCF reporter activity about twofold in Fz4 cells and about sixfold with Lrp5, EC50 approximately 6 nM [PMID:24186977]. It is classed a full agonist [DB:GtoPdb]; Norrin induces Fz4- and Lrp-dependent classical Wnt pathway activation [PMID:15035989].","molecular_requirements":"Norrin forms a ternary complex with Fz4 and Lrp5/6, binding their extracellular domains at separate sites, and a Norrin dimer is required for activation [PMID:24186977]. Binding was specific to Fz4, with no Fz8 CRD interaction [PMID:24186977].","affinity_potency":[{"value":"Kd 11 nM","assay":"AlphaScreen saturation binding","system":"biotin-MBP-Norrin to Fz4-FcH6 CRD","cite":"PMID:24186977"},{"value":"5 nM","assay":"biolayer interferometry","system":"MBP-Norrin dimer to Fz4-FcH6 dimer","cite":"PMID:24186977"}],"species_and_systems":"Human Norrin fused to MBP made in E. coli, with mammalian Fz4 CRD-Fc and 293STF cells [PMID:24186977]; the paper annotated as mouse proteins in the curation. High-affinity binding and signalling in cells reported in [PMID:15035989].","localisation_and_range":"Norrin is flagged secreted and not transmembrane [flag], so it acts as a secreted paracrine ligand.","caveats":"PMID:15035989 was read as abstract only, with no number in our evidence. The recombinant Norrin has an MBP tag; species labels in the curation differ between papers.","key_references":[{"PMID":"24186977","why":"Binding affinities, ternary Fz4-Lrp5/6 complex"},{"PMID":"15035989","why":"Norrin-Fz4 as a high-affinity ligand-receptor pair"}],"covers":["LR001091","LR004502"]},"LR004502":{"pair":"NDP -> FZD4","headline":"Norrin binds Frizzled-4 with high affinity and activates Wnt/beta-catenin signalling with LRP5/6; two papers plus GtoPdb support it.","interaction_type":"direct binding","direction_and_effect":"Norrin is an agonist of FZD4: MBP-Norrin raised TCF reporter activity about twofold in Fz4 cells and about sixfold with Lrp5, EC50 approximately 6 nM [PMID:24186977]. It is classed a full agonist [DB:GtoPdb]; Norrin induces Fz4- and Lrp-dependent classical Wnt pathway activation [PMID:15035989].","molecular_requirements":"Norrin forms a ternary complex with Fz4 and Lrp5/6, binding their extracellular domains at separate sites, and a Norrin dimer is required for activation [PMID:24186977]. Binding was specific to Fz4, with no Fz8 CRD interaction [PMID:24186977].","affinity_potency":[{"value":"Kd 11 nM","assay":"AlphaScreen saturation binding","system":"biotin-MBP-Norrin to Fz4-FcH6 CRD","cite":"PMID:24186977"},{"value":"5 nM","assay":"biolayer interferometry","system":"MBP-Norrin dimer to Fz4-FcH6 dimer","cite":"PMID:24186977"}],"species_and_systems":"Human Norrin fused to MBP made in E. coli, with mammalian Fz4 CRD-Fc and 293STF cells [PMID:24186977]; the paper annotated as mouse proteins in the curation. High-affinity binding and signalling in cells reported in [PMID:15035989].","localisation_and_range":"Norrin is flagged secreted and not transmembrane [flag], so it acts as a secreted paracrine ligand.","caveats":"PMID:15035989 was read as abstract only, with no number in our evidence. The recombinant Norrin has an MBP tag; species labels in the curation differ between papers.","key_references":[{"PMID":"24186977","why":"Binding affinities, ternary Fz4-Lrp5/6 complex"},{"PMID":"15035989","why":"Norrin-Fz4 as a high-affinity ligand-receptor pair"}],"covers":["LR001091","LR004502"]},"LR006212":{"pair":"NFASC -> CNTNAP1","headline":"Cell aggregation with CNTN1/CASPR1 cells supports Nfasc155 binding the CNTN1:CASPR1 unit; CASPR1 alone is not tested.","interaction_type":"direct binding","direction_and_effect":"N2A cells expressing CNTN1/CASPR1 readily interact and form aggregates with Nfasc155-expressing cells; p.P705T and p.P939Ter variants abolished the interaction [PMID:31501903]. Effect direction is not reported in our evidence.","molecular_requirements":"The assay used CNTN1 together with CASPR1, so a CNTNAP1-only requirement is not shown [PMID:31501903]. Nfasc155 is the isoform tested. Reactome lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"N2A cell aggregation assay with Nfasc155 variants from human patients; species of the cells is not reported in our evidence; paper read in full text [PMID:31501903]. The human pair is listed and the mouse pair is ortholog-inferred.","localisation_and_range":"Cell-surface adhesion molecules acting through cell-cell aggregation [PMID:31501903]; neither is annotated secreted [flag].","caveats":"The paper's main finding is disease variants; the aggregation is a side assay, and the text cites an earlier report for the interaction. Chain-only evidence for CNTNAP1. Many other papers were judged abstract-insufficient or a different entity.","key_references":[{"PMID":"31501903","why":"Aggregation of Nfasc155 cells with CNTN1/CASPR1 cells, abolished by variants"}],"covers":["LR002987","LR006212"]},"LR004511":{"pair":"NID1 -> PTPRF","headline":"The laminin-nidogen complex binds the LAR Fn5 domain in vitro; binding depends on a splice isoform and is of the complex, not NID1 alone.","interaction_type":"direct binding","direction_and_effect":"The laminin-nidogen complex was identified as a ligand for LAR-FnIII domain 5 in GST-fusion binding assays; antibody cross-linking of LAR inhibited cell process formation on laminin-nidogen [PMID:9647658]. Interaction is annotated stimulatory [flag].","molecular_requirements":"Binding is regulated by alternative splicing: including a small exon in LAR-Fn5 disrupts it [PMID:9647658]. The ligand was the laminin-nidogen complex, and the excerpts show binding to laminin chains [PMID:9647658].","affinity_potency":[],"species_and_systems":"GST-LAR-FnIII fusion proteins and HeLa cells; the curator records human; the paper was read in abstract and excerpts [PMID:9647658]. BioGRID records a reconstituted complex [DB:BioGRID]. Human pair is listed and mouse pair is ortholog-inferred.","localisation_and_range":"Matrix ligand; NID1 is annotated secreted [flag].","caveats":"Binding was shown for the laminin-nidogen complex; NID1 alone is not shown in our evidence. Single paper, 1998.","key_references":[{"PMID":"9647658","why":"Laminin-nidogen binds LAR-Fn5, regulated by splicing"}],"covers":["LR001100","LR004511"]},"LR001109":{"pair":"NLGN3 -> NRXN2","headline":"Only a general beta-neurexin binding paper; NRXN2 and NLGN3 not individually resolved.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins as native and recombinant proteins [PMID:8576240]; effect not reported.","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Species unspecified for this row [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair.","caveats":"Abstract only; beta-neurexins as a class, so NRXN2 is not individually shown. No database record and no affinity.","key_references":[{"PMID":"8576240","why":"Neuroligins bind beta-neurexins"}],"covers":["LR001109","LR004520"]},"LR004520":{"pair":"NLGN3 -> NRXN2","headline":"Only a general beta-neurexin binding paper; NRXN2 and NLGN3 not individually resolved.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins as native and recombinant proteins [PMID:8576240]; effect not reported.","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Species unspecified for this row [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair.","caveats":"Abstract only; beta-neurexins as a class, so NRXN2 is not individually shown. No database record and no affinity.","key_references":[{"PMID":"8576240","why":"Neuroligins bind beta-neurexins"}],"covers":["LR001109","LR004520"]},"LR001118":{"pair":"NODAL -> ACVR1C","headline":"Functional support for ALK7 (ACVR1C) as a Nodal type I receptor, mainly from mouse Nodal and Xenopus experiments.","interaction_type":"functional only","direction_and_effect":"ALK7 acts as a receptor for mouse Nodal and Xenopus Xnr1; constitutively active ALK7 mimics Xnr1 and dominant-negative ALK7 specifically blocks Nodal and Xnr1 [PMID:11485994]. UniProt: upon NODAL binding, activation suppresses AKT and activates Smad2 signalling [DB:UniProt].","molecular_requirements":"ALK7 collaborates with ActRIIB; both receptors can independently bind Xnr1; Cripto interacts with Xnr1 and ALK7 and greatly enhances response [PMID:11485994].","affinity_potency":[],"species_and_systems":"Mouse Nodal and Xenopus Xnr1 in Xenopus embryos and reconstitution [PMID:11485994]. The human pair is direct; mouse likewise.","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"Abstract only; two further papers abstract-insufficient.","key_references":[{"PMID":"11485994","why":"Biochemical and functional evidence that ALK7 is a Nodal receptor"}],"covers":["LR001118","LR004529"]},"LR001127":{"pair":"NPNT -> ITGB1","headline":"Nephronectin binds integrin alpha8beta1, so ITGB1 is supported only as the beta chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"The paper shows binding of an alpha8beta1 heterodimer probe to nephronectin and in vivo complex formation [PMID:11470831]; binding was RGD-inhibitable [PMID:11470831].","molecular_requirements":"ITGB1 acts as a subunit with ITGA8; Reactome lists NPNT:ITGA8:ITGB1 [DB:Reactome]. The evidence does not test ITGB1 alone, and ITGB1 pairs with other alpha chains: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse tissue and recombinant probes [PMID:11470831]; human pair is ortholog-inferred.","localisation_and_range":"Nephronectin is an extracellular matrix protein, no transmembrane region [PMID:11470831].","caveats":"Chain-only evidence: the single paper used the alpha8beta1 heterodimer, not ITGB1 separately. Abstract-level judgement, though full text excerpts support RGD-dependent binding [PMID:11470831].","key_references":[{"PMID":"11470831","why":"alpha8beta1 binding to nephronectin"}],"covers":["LR001127","LR004537"]},"LR006221":{"pair":"NPPC -> NPR1","headline":"CNP-NPR1 is supported only by a BioGRID record; all eight judged papers were abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified direction or effect is available. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"CNP annotated secreted and NPR1 transmembrane [flag].","caveats":"No confirmed paper. Treat as unverified or likely weak; low confidence for CCC scoring.","key_references":[],"covers":["LR002997","LR006221"]},"LR001136":{"pair":"NPVF -> NPFFR1","headline":"NPVF peptides bind NPFFR1 (FF1) with nanomolar affinity; two abstract-level papers plus GtoPdb full-agonist records.","interaction_type":"direct binding","direction_and_effect":"NPVF-derived peptides showed higher affinity for FF1 than NPFF-derived peptides [PMID:11481330]. In human NPFF1 cells the peptides act as agonists; GtoPdb lists a full agonist [PMID:12242085][DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor or complex requirement reported in our evidence.","affinity_potency":[{"value":"pKi 9.2-9.3","assay":"GtoPdb agonist record","system":"not reported in our evidence","cite":"PMID:12242085"}],"species_and_systems":"Radioligand binding on human NPFF1 in CHO cells, human peptides [PMID:12242085]; the first paper does not state species [PMID:11481330]. Mouse pair is projected from human.","localisation_and_range":"NPVF is flagged secreted and NPFFR1 a transmembrane receptor [flag]; paracrine/neuroendocrine range is inferred only from these flags.","caveats":"Both papers were read as abstracts only. The peptides bind both NPFF receptors, with only a slight preference for FF1 [PMID:12242085]. Affinity is given as a range in GtoPdb, not per peptide.","key_references":[{"PMID":"11481330","why":"Identifies NPVF peptides; higher affinity for FF1 than NPFF peptides"},{"PMID":"12242085","why":"Human NPFF1/NPFF2 binding in CHO cells, nanomolar affinity"}],"covers":["LR001136","LR004546"]},"LR001145":{"pair":"NPY -> PRLHR","headline":"NPY binds PRLHR1 only at micromolar levels and blocks PRLH signalling; a weak antagonist from a single abstract.","interaction_type":"direct binding","direction_and_effect":"A micromolar level of NPY bound and completely inhibited the PRLH-evoked response in PRLHR1-expressing cells, so NPY acts as an antagonist here, not an agonist [PMID:15885496][DB:GtoPdb].","molecular_requirements":"Single receptor chain (PRLHR1 subtype); no co-receptor reported.","affinity_potency":[{"value":"pKi 5.4","assay":"curator-recorded affinity; NPY inhibition of PRLH response","system":"PRLHR1-expressing cells","cite":"PMID:15885496"}],"species_and_systems":"Cells expressing vertebrate PRLHR1; the dossier lists human ligand and receptor [PMID:15885496]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, PRLHR transmembrane [flag].","caveats":"Single paper, read as abstract only. The effect is weak (micromolar) and is likely an evolutionary cross-reactivity rather than physiological signalling. The pKi is curator-recorded.","key_references":[{"PMID":"15885496","why":"Micromolar NPY inhibits PRLH response at PRLHR1"}],"covers":["LR001145","LR004554"]},"LR006230":{"pair":"NRG1 -> ITGB3","headline":"Single abstract-level report that NRG1 binds integrin beta3 (ITGB3); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003006","LR006230"]},"LR003008":{"pair":"NRG3 -> EGFR","headline":"NRG3 activates EGFR in transfected cells, from a single abstract-level 1998 paper.","interaction_type":"functional only","direction_and_effect":"Recombinant NRG-3 EGF-like domain activated EGF receptor (erbB1) when expressed individually, an agonist effect [PMID:9772300].","molecular_requirements":"EGFR acted alone; erbB2 and erbB3 were activated only when expressed together [PMID:9772300].","affinity_potency":[],"species_and_systems":"Human breast cancer cells and 32D cells transfected with erbB family members; recombinant E. coli-made domain [PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag]; not tested in the paper.","caveats":"Single paper, abstract only. Activation was shown, not binding; no affinity reported. NRG3 is better known here for ErbB4 (see NRG3 -> ERBB4), so EGFR is a secondary receptor in our evidence.","key_references":[{"PMID":"9772300","why":"NRG-3 activates EGFR and other erbB members"}],"covers":["LR003008","LR006232"]},"LR012431":{"pair":"NRP1 -> FLT1:KDR","headline":"NRP1 with FLT1:KDR rests on database records only; no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes NRP-1 forming a ternary complex with VEGF165 and VEGFR1 [DB:Reactome]. Curated effect is Stimulatory; no paper in our evidence supports it.","molecular_requirements":"The complex pair needs both FLT1 and KDR, but records support NRP1 with KDR and with FLT1 separately [DB:BioGRID][DB:IntAct]; a joint FLT1:KDR complex is not shown.","affinity_potency":[],"species_and_systems":"Human; BioGRID entries are affinity capture-western, IntAct coimmunoprecipitation [DB:BioGRID][DB:IntAct].","localisation_and_range":"NRP1 is flagged secreted, receptor and transmembrane [flag]; the interaction is through VEGF165 as a bridge in Reactome [DB:Reactome].","caveats":"No papers were judged (3 pending). Evidence is database-only; examples cited here are not curator-verified. The ligand/receptor direction is not established: NRP1 acts as a co-receptor with VEGF165.","key_references":[],"covers":["LR012431"]},"LR001154":{"pair":"NRTN -> GFRA2","headline":"NRTN is a preferred ligand for GFRA2, supported by binding, signalling, structure and UniProt records.","interaction_type":"direct binding","direction_and_effect":"GFRA2 mediates NTN signalling through Ret, and TrnR2-Ret cells are more sensitive to NTN than to GDNF [PMID:9182803]. UniProt calls GFRA2 the receptor for neurturin [DB:UniProt].","molecular_requirements":"GFRA2 acts with Ret; GFRA2 is GPI-linked [PMID:9182803]. Binding of 125I-ligand to human GFRalpha1/2 was studied with and without cRET [PMID:10829012]. PDB entries contain chains of NRTN and GFRA2 [DB:PDB 5MR4].","affinity_potency":[{"value":"approximately 30-fold more sensitive to NTN than to GDNF","assay":"Ret phosphorylation, relative sensitivity of TrnR2-Ret cells","system":"fibroblasts expressing TrnR2 and Ret","cite":"PMID:9182803"}],"species_and_systems":"Human receptors, fibroblasts and 125I-ligand binding to human GFRalpha2 [PMID:10829012][PMID:9182803].","localisation_and_range":"NRTN annotated secreted [flag]; GFRA2 GPI-anchored [PMID:9182803].","caveats":"Papers read as abstracts only; affinity values from PMID 10829012 are not in our abstract text. Review-only and pending papers not counted.","key_references":[{"PMID":"9182803","why":"TrnR2 (GFRA2) mediates NTN signalling via Ret"},{"PMID":"10829012","why":"Ligand binding to human GFRalpha1/2 with and without cRET"}],"covers":["LR001154","LR004563"]},"LR003017":{"pair":"NRXN1 -> DAG1","headline":"Neurexins bind dystroglycan in a tight, glycosylation-dependent interaction; shown for neurexin class, curator assigned NRXN1.","interaction_type":"direct binding","direction_and_effect":"Alpha- and beta-neurexins were identified as neuronal dystroglycan receptors; dystroglycan binds a subset of neurexin LNS domains [PMID:11470830]. Reactome lists a Dystroglycan:NRXN1 complex [DB:Reactome].","molecular_requirements":"Binding requires glycosylation of dystroglycan, is regulated by alternative splicing of neurexins, and alpha-latrotoxin competes for the site [PMID:11470830].","affinity_potency":[],"species_and_systems":"Affinity chromatography from brain extract; species not stated in the dossier. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Dystroglycan is flagged secreted and transmembrane [flag]; NRXN1 is transmembrane [flag].","caveats":"The paper's abstract names neurexins generally; the curator note says NRXN1 is recorded as the canonical member, not directly shown. No affinity value in our evidence.","key_references":[{"PMID":"11470830","why":"neurexins identified as neuronal dystroglycan receptors"}],"covers":["LR003017","LR006241"]},"LR003026":{"pair":"NRXN2 -> DAG1","headline":"Direct, tight Ca2+-dependent binding of the neurexin-2alpha second LNS domain to dystroglycan, from full text.","interaction_type":"direct binding","direction_and_effect":"The second LNS domain of all three alpha-neurexins (neurexin 1alpha, 2alpha, and 3alpha) formed tight Ca2+-dependent complexes with dystroglycan [PMID:11470830].","molecular_requirements":"Only alpha-neurexins containing the second or sixth LNS domain captured dystroglycan, and a single isolated LNS domain fully bound; binding requires dystroglycan glycosylation and is regulated by neurexin splicing [PMID:11470830].","affinity_potency":[],"species_and_systems":"Ig-fusion affinity chromatography with rat brain extract (curator note); human and mouse pairs are ortholog-inferred.","localisation_and_range":"DAG1 is flagged secreted and transmembrane; NRXN2 is neither flagged as secreted nor transmembrane in the dossier [flag].","caveats":"Evidence is for the alpha-neurexin NRXN2 LNS domain; beta-neurexin NRXN2 not specified. One review_only row was excluded.","key_references":[{"PMID":"11470830","why":"second LNS domain of neurexin-2alpha binds dystroglycan"}],"covers":["LR003026","LR006250"]},"LR001163":{"pair":"NTN1 -> DCC","headline":"Well-supported direct binding of netrin-1 to DCC, with structural, binding and functional evidence; netrin-1 acts as an attractive agonist.","interaction_type":"direct binding","direction_and_effect":"Netrin-1 binds DCC and acts as an agonist: an anti-DCC antibody blocks netrin-1-dependent commissural axon outgrowth in vitro [PMID:8861902]. Netrin-1 engages DCC through its EGF-3 domain [PMID:29503192].","molecular_requirements":"Netrin-1 binds the fifth fibronectin type III repeat of DCC, with 1:1 stoichiometry in solution [PMID:12810718]. APP acts as a co-receptor in the DCC complex and enhances netrin-1-driven MAPK signalling [PMID:22782894]. Draxin tethers netrin-1 to DCC [PMID:29503192]. Binding in one cell-surface study appeared to depend on a coreceptor or accessory proteins [PMID:9950216].","affinity_potency":[],"species_and_systems":"Experiments in the dossier used human proteins [PMID:12810718][PMID:29503192]; commissural axon outgrowth in vitro [PMID:8861902]; rat commissural axons and Xenopus spinal axons [PMID:11239160]. Mouse pair is ortholog-inferred. Also recorded in BioGRID, IntAct, PDB 4URT and Reactome [DB:PDB 4URT][DB:Reactome].","localisation_and_range":"Netrin-1 is secreted and DCC is transmembrane [flag]; DCC is described as expressed on commissural axons [PMID:8861902].","caveats":"Most papers were read as abstracts only. In one study netrin-1 could be cross-linked to DCC on the cell surface but did not immunoprecipitate without cross-linking and failed to bind a soluble DCC ectodomain fusion [PMID:9950216]. One retracted row is not shown.","key_references":[{"PMID":"8861902","why":"Identifies DCC as a netrin-1-binding receptor on commissural axons"},{"PMID":"12810718","why":"Maps netrin binding to DCC fifth fibronectin repeat"},{"PMID":"29503192","why":"Crystal structures with Draxin; netrin-1 uses EGF-3 domain"}],"covers":["LR001163","LR004572"]},"LR003035":{"pair":"NTN3 -> DCC","headline":"Murine netrin-3 binds DCC with lower affinity than other netrin receptors; evidence is one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds DCC, with lower affinity than to neogenin and the UNC5 receptors [PMID:10366627]. Netrin-3 can mimic netrin-1 outgrowth-promoting activity on commissural axons but with lower specific activity [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse netrin-3 protein; the human pair is ortholog-inferred and the mouse pair projected from human evidence. Assay format is not stated in the abstract [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and DCC transmembrane [flag].","caveats":"Abstract only, no affinity numbers. Binding is weaker than for other receptors, so DCC may be a minor receptor for netrin-3.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binding to DCC with comparatively low affinity"}],"covers":["LR003035","LR006259"]},"LR001172":{"pair":"NTNG1 -> LRRC4C","headline":"Netrin-G1 binds NGL-1 (LRRC4C): binding, structure and KO mouse data support a real trans-synaptic pair.","interaction_type":"direct binding","direction_and_effect":"NGL-1 interacts specifically with netrin-G1 through its LRR region [PMID:14595443]. Surface-bound NGL-1 stimulates, but soluble NGL-1 disrupts, thalamic axon growth [PMID:14595443]. Netrin-G1 and NGL1 specify excitatory synapses in the hippocampal temporoammonic pathway [PMID:25411505].","molecular_requirements":"Not reported in our evidence beyond the LRR region of NGL-1 [PMID:14595443].","affinity_potency":[],"species_and_systems":"Human NGL-1 with mouse thalamic axons [PMID:14595443]; netrin-G and NGL knockout mice [PMID:25411505]. Database records: BioGRID co-crystal structure, IntAct surface plasmon resonance and PDB 3ZYJ [DB:PDB 3ZYJ][DB:BioGRID][DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Netrin-G1 is a lipid-anchored protein [PMID:14595443]; NGL-1 is a transmembrane protein [PMID:14595443]. Trans-synaptic or contact-mediated.","caveats":"Abstracts only; no affinity numbers in our evidence. The 2014 paper states the pairing as background rather than testing it directly. One abstract_insufficient row is not shown.","key_references":[{"PMID":"14595443","why":"Identifies NGL-1 as netrin-G1 ligand"},{"PMID":"25411505","why":"Netrin-G1/NGL1 knockout mouse synapse specificity"}],"covers":["LR001172","LR004581"]},"LR001181":{"pair":"NXPH3 -> NRXN3","headline":"Neurexophilin-3 binds neurexin-3 LNS2 per a 2019 full-text study and a 1998 recombinant study.","interaction_type":"direct binding","direction_and_effect":"Nxph3 binding to Nrxn1-3 LNS2SS2- was tested [PMID:31566781], and neurexophilins 1 and 3 bind the second LNS domain of all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 is the binding domain [PMID:9856994]. The equivalent I401Q mutation in Nrxn3 decreased Nxph1 binding from the nanomolar to the millimolar range; Nxph3 values are not stated in our excerpts [PMID:31566781].","affinity_potency":[],"species_and_systems":"Recombinant mouse proteins [PMID:9856994]; recombinant LNS2 constructs [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; membrane neurexin [flag].","caveats":"The quoted NXPH3 sentence is a lead-in, not a result. No Nxph3 affinity in our evidence. The 1998 paper was abstract only.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001181","LR004590"]},"LR003044":{"pair":"OMG -> PTPRD","headline":"OMG binds PTPRD by SPR in the micromolar range in one full-text paper; no other evidence.","interaction_type":"direct binding","direction_and_effect":"Direction is OMG as ligand, PTPRD as receptor. SPR with human OMG and RPTP ectodomains showed micromolar-range binding to all three R2A RPTPs including PTPRD [PMID:36178190]. Functional effect is not reported in our evidence.","molecular_requirements":"PTPRD ectodomain used alone; no co-receptor or subunit requirement reported in our evidence.","affinity_potency":[{"value":"micromolar range","assay":"SPR, OMG vs RPTP ectodomains","system":"recombinant human proteins","cite":"PMID:36178190"}],"species_and_systems":"Human OMG and human PTPRD recombinant ectodomains, SPR [PMID:36178190]. Mouse pair is projected from human, not tested.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. PTPRD is a flagged transmembrane receptor [flag].","caveats":"Single paper. The PTPRD interaction came from phylogenetic homology analysis, not from the CRISPRa screen (the screen's top hit was PTPRU) [PMID:36178190]. No exact Kd given for PTPRD in our excerpts. No database records.","key_references":[{"PMID":"36178190","why":"SPR validation of OMG binding to R2A RPTPs"}],"covers":["LR003044","LR006268"]},"LR001190":{"pair":"OXT -> AVPR1A","headline":"Oxytocin binds and activates AVPR1A with lower affinity than vasopressin; partial agonist at human receptor, with species differences.","interaction_type":"direct binding","direction_and_effect":"OXT activates Ca2+ signalling at human AVPR1A but as a partial agonist, about 45% of the maximal AVP response; at marmoset AVPR1A it exceeded AVP [PMID:31664130]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"Ki 34.9 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"15.8 nM (Leu8-OXT), 8.7 nM (Pro8-OXT)","assay":"125I-OVTA competition binding, versus 0.6 nM for AVP","system":"human AVPR1a in CHO cells","cite":"PMID:31664130"},{"value":"69.3 nM (Leu8-OXT), 36.2 nM (Pro8-OXT)","assay":"Ca2+ response potency, versus AVP 1.6 nM","system":"human AVPR1a","cite":"PMID:31664130"}],"species_and_systems":"Human receptor in recombinant cells; marmoset and macaque receptors also tested [PMID:31664130]. Mouse pair is ortholog-inferred.","localisation_and_range":"OXT is flagged secreted and AVPR1A a transmembrane receptor [flag].","caveats":"OXT is a lower-affinity cross-reactive ligand; the authors suggest it may partly antagonise human AVPR1a signalling [PMID:31664130]. Both key papers were read as abstract or in part; PDB structures are not listed for this pair. GtoPdb gives pKi 6.9 to 8.3 [DB:GtoPdb]. Marmoset OXT affinity is about 10-fold lower than human [PMID:31664130].","key_references":[{"PMID":"31664130","why":"affinity and efficacy of OXT versus AVP at primate AVPR1a"},{"PMID":"10519430","why":"Ki of oxytocin at V1a"}],"covers":["LR001190","LR004599"]},"LR004601":{"pair":"OXT -> AVPR2","headline":"No curator-verified evidence that oxytocin acts on AVPR2; support is a database assertion and the one paper checked was negative.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists oxytocin as a full agonist at AVPR2 [DB:GtoPdb]. The one paper judged did not test oxytocin at V2; the stated selectivity is of its own antagonist compound [PMID:12660315].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system confirmed for this pair in our evidence.","localisation_and_range":"OXT is flagged secreted; AVPR2 is a transmembrane receptor [flag].","caveats":"Verified negative for PMID:12660315 (pair_absent). Five other papers were judged a different entity and two were abstract_insufficient. UniProt notes OXT interacts with AVPR1A, AVPR1B and AVPR2 [DB:UniProt]. GtoPdb pKi range 5.4 to 6.8 [DB:GtoPdb] is low affinity.","key_references":[],"covers":["LR001192","LR004601"]},"LR003080":{"pair":"PCDHGB6 -> PCDHGB6","headline":"Mouse gammaB6 engages homophilic interactions and reaches the cell surface in K562 assays; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Homophilic interaction; the paper states gamma and beta proteins tested show strict trans-homophilic specificity [PMID:25171406]. No agonist/antagonist effect reported.","molecular_requirements":"Cell-surface expression of gammaB6 was verified with extracellular c-Myc tags [PMID:25171406]. Cis interactions with other Pcdhs matter for Pcdh-alpha delivery [PMID:25171406].","affinity_potency":[],"species_and_systems":"Mouse isoforms in K562 cell aggregation assays [PMID:25171406]; human pair ortholog-inferred.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent.","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology.","key_references":[{"PMID":"25171406","why":"Names gammaB6 as homophilic and surface-expressed."}],"covers":["LR003080","LR006303"]},"LR006311":{"pair":"PDPN -> CD177","headline":"Human PDPN binds CD177 directly with micromolar affinity, and CD177 acts as a functional antagonist in fibroblasts.","interaction_type":"direct binding","direction_and_effect":"Screening identified CD177 as a PDPN binding partner; cellular assays show CD177 is a functional antagonist, recapitulating the phenotype of PDPN-deficient cancer-associated fibroblasts [PMID:34879110].","molecular_requirements":"Binding was measured with recombinant ectodomains; no co-receptor requirement reported in our evidence [PMID:34879110].","affinity_potency":[{"value":"KD = 3.3 \u00b1 0.7 \u03bcM","assay":"surface plasmon resonance, recombinant PDPN ectodomain","system":"human proteins","cite":"PMID:34879110"}],"species_and_systems":"Human proteins and primary human CAFs from colorectal cancer [PMID:34879110]. No binding between mouse CD177 and mouse PDPN was detected, so the interaction may be human-specific [PMID:34879110].","localisation_and_range":"Both are membrane proteins in the paper's setting (CD177 on neutrophils); the secreted flag on CD177 comes from an annotation flag [flag]. Contact-dependent use is likely but the soluble Fc ectodomain was used as stimulus [PMID:34879110].","caveats":"Affinity is 10-fold weaker than CLEC-2 (KD = 210 \u00b1 0.3 nM) [PMID:34879110]. Mouse pair is ortholog-inferred but the paper reports no mouse binding.","key_references":[{"PMID":"34879110","why":"Interactome screen, SPR KD and antagonist phenotype in CAFs"}],"covers":["LR003088","LR006311"]},"LR004610":{"pair":"PDYN -> OPRD1","headline":"Dynorphin A peptides bind the cloned delta receptor, with kappa preference; evidence is from a 1995 binding paper.","interaction_type":"direct binding","direction_and_effect":"Dynorphin A peptides prefer kappa but also bind the cloned delta and mu receptors [PMID:8624732]. GtoPdb records an agonist (full agonist) interaction [DB:GtoPdb].","molecular_requirements":"Peptide-derived ligands (dynorphin A fragments from prodynorphin) were tested [PMID:8624732].","affinity_potency":[],"species_and_systems":"Cloned human receptors transiently expressed in COS-1 cells; abstract only [PMID:8624732].","localisation_and_range":"PDYN flagged secreted; OPRD1 transmembrane [flag].","caveats":"Delta is a secondary target; no numeric affinity in our evidence for delta. GtoPdb lists pKi units but no values in our dossier. Mouse and human pairs are ortholog-inferred.","key_references":[{"PMID":"8624732","why":"Cloned opioid receptor binding of prodynorphin peptides, incl. delta"}],"covers":["LR001201","LR004610"]},"LR001208":{"pair":"PENK -> OPRM1","headline":"No verified paper; support rests on GtoPdb and IntAct records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a partial agonist [DB:GtoPdb]. IntAct reports a scintillation proximity assay between P35372 and P01210 [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the underlying assays not reported in our evidence.","localisation_and_range":"PENK is flagged secreted [flag].","caveats":"No curator-verified paper; all 12 judged rows were abstract_insufficient and one was a different entity. GtoPdb affinity unit pKi has no value in the dossier [DB:GtoPdb].","key_references":[],"covers":["LR001208","LR004617"]},"LR001217":{"pair":"PGF -> NRP2","headline":"Heparin-binding PlGF binds NRP2 per one abstract-only paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"NRP2 binds the heparin-binding form of placenta growth factor [PMID:10748121].","molecular_requirements":"Only the heparin-binding PlGF form binds [PMID:10748121].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells express NRP2 splice forms a17 and a22 [PMID:10748121]. Mouse pair is ortholog-inferred.","localisation_and_range":"PGF is flagged secreted [flag].","caveats":"One paper, abstract only; PlGF affinity not reported in our evidence. No database records.","key_references":[{"PMID":"10748121","why":"NRP2 binds heparin-binding PlGF"}],"covers":["LR001217","LR004620"]},"LR006320":{"pair":"PGLYRP1 -> CXCR3","headline":"No verified paper; only a UniProt annotation of the Tag7-Mts1 complex as CXCR3 ligand.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the PGLYRP1 complex acts as a ligand of CCR5 and CXCR3 [DB:UniProt].","molecular_requirements":"The ligand is a complex with S100A4/Mts1 per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Both judged rows were abstract_insufficient. A companion paper rules out PGLYRP1 alone binding CCR5, so chain-level support is doubtful [DB:UniProt].","key_references":[],"covers":["LR003098","LR006320"]},"LR003107":{"pair":"PLAT -> ANXA2","headline":"tPA's protease-independent NF-kB signalling in macrophages requires annexin A2; one abstract-only paper plus BioGRID.","interaction_type":"functional only","direction_and_effect":"The protease-independent action of tPA required its membrane receptor annexin A2 in macrophage NF-kB activation [PMID:22677557]. BioGRID lists a reconstituted complex [DB:BioGRID 278617].","molecular_requirements":"tPA induced annexin A2 aggregation and interaction with CD11b; CD11b ablation abolished the effect [PMID:22677557], so the effect needs a co-partner beyond ANXA2.","affinity_potency":[],"species_and_systems":"Experimental species not recorded; abstract mentions tPA-knockout mice and macrophages [PMID:22677557]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"tPA secreted per flag [flag]; annexin A2 acting at the membrane per the abstract [PMID:22677557].","caveats":"Abstract only; physical binding is not described in the abstract, which says 'required its membrane receptor' [PMID:22677557]. Binding rests on a BioGRID record not linked to a dossier paper.","key_references":[{"PMID":"22677557","why":"tPA activates macrophage NF-kB via annexin A2/CD11b and ILK"}],"covers":["LR003107","LR006328"]},"LR001226":{"pair":"PLAU -> VLDLR","headline":"uPA complexed with PAI-1 binds the VLDL receptor with high affinity and is internalised; free uPA alone is not shown.","interaction_type":"direct binding","direction_and_effect":"In vitro, the uPA.PAI-1 complex bound purified VLDL receptor with high affinity, and VLDLR-expressing fibroblasts internalised and degraded 125I-labelled uPA.PAI-1; non-infected cells did not [PMID:7592875]. The record is labelled agonist, i.e. endocytic clearance, not signalling.","molecular_requirements":"The ligand tested is uPA bound to PAI-1, not uPA alone [PMID:7592875].","affinity_potency":[],"species_and_systems":"Human cell and protein sources; internalisation tested in VLDLR/LRP-double-deficient murine fibroblasts infected with an adenoviral VLDLR vector [PMID:7592875]. Abstract only.","localisation_and_range":"Ligand flagged secreted; receptor transmembrane [flag]. Complex is cleared by endocytosis [PMID:7592875].","caveats":"One paper, abstract only; one further row is pending and not shown. No affinity value reported. The curated evidence sentence concerns lipoprotein lipase rather than uPA.","key_references":[{"PMID":"7592875","why":"VLDLR binds and internalises uPA.PAI-1"}],"covers":["LR001226","LR004629"]},"LR003116":{"pair":"PLAUR -> LRP1","headline":"Only functional, complex-level evidence for PLAUR with LRP1; no direct binding measured in the judged papers.","interaction_type":"functional only","direction_and_effect":"Interfering with LRP binding to the [uPAR:uPA:PAI-1] complex markedly decreased human myogenic cell motility [PMID:10896774]. Database records (BioGRID affinity-capture and reconstituted complex; UniProt) also assert PLAUR-LRP1 interaction [DB:BioGRID][DB:UniProt].","molecular_requirements":"LRP binds the assembled uPAR:uPA:PAI-1 complex, not uPAR alone [PMID:10896774]. UniProt says the interaction leads to PLAUR internalisation and is impaired by SORL1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human myogenic cells; abstract only [PMID:10896774].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Evidence is interference, not binding. A second paper was abstract-insufficient.","key_references":[{"PMID":"10896774","why":"LRP involvement in uPAR:uPA:PAI-1 complex-dependent motility"}],"covers":["LR003116","LR006337"]},"LR001235":{"pair":"PMCH -> MCHR2","headline":"MCH binds and activates MCHR2 in human recombinant cells, shown by three independent 2001 reports; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"MCH is an agonist at MCHR2: nanomolar MCH raises intracellular Ca2+ in transfected HEK293 cells and fluorescently labelled MCH binds with nanomolar affinity [PMID:11274220]. Another group reports high-affinity MCH binding with inositol phosphate turnover and Ca2+ release [PMID:11404457], and a third reports binding with Gq signalling [PMID:11416225].","molecular_requirements":"MCHR2 alone is sufficient in these cell systems. Signalling is insensitive to pertussis toxin and does not reduce forskolin-stimulated cAMP, suggesting exclusive Galphaq coupling [PMID:11404457]. The cyclic core of MCH with an N-terminal Arg activates MCH-2R about as well as full-length hMCH [PMID:11478907].","affinity_potency":[{"value":"nanomolar affinity","assay":"fluorescently labelled MCH binding","system":"HEK293 cells expressing MCH2","cite":"PMID:11274220"},{"value":"pIC50 8.2-9.2","assay":"GtoPdb curated affinity","system":"not stated","cite":"PMID:11404457"}],"species_and_systems":"Human ligand and receptor in recombinant mammalian cells [PMID:11274220][PMID:11404457]; no other species tested in our evidence.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag]; a diffusible peptide acting on a cell-surface receptor.","caveats":"MCH is non-selective between MCHR1 and MCHR2 [PMID:11478907][PMID:11839762], so MCHR1 co-expression confounds inference. All papers read as abstracts only. A PDB structure exists [DB:PDB 8WST].","key_references":[{"PMID":"11274220","why":"cloning of MCH2; nanomolar MCH responses and binding"},{"PMID":"11404457","why":"independent identification; Gq-only signalling"},{"PMID":"11416225","why":"third independent identification"}],"covers":["LR001235"]},"LR001244":{"pair":"POMC -> OPRD1","headline":"One in vivo rat study implicates delta opioid receptor in beta-endorphin action; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"In rats, intra-NAc beta-endorphin lowers cue-induced cocaine seeking, and the delta opioid antagonist naltrindole raises it and blocks beta-endorphin's effect; the mu antagonist CTAP had no effect [PMID:23800967]. GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat in vivo behaviour with intra-accumbens infusion; read as abstract only [PMID:23800967]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"POMC flagged secreted, OPRD1 transmembrane [flag]; the paper infuses beta-endorphin locally into nucleus accumbens [PMID:23800967].","caveats":"Evidence is antagonist pharmacology in behaviour, not binding. The active ligand is beta-endorphin, not full-length POMC. Only one paper; GtoPdb row has no affinity values given.","key_references":[{"PMID":"23800967","why":"Rat in vivo: naltrindole reverses beta-endorphin effect"}],"covers":["LR001244","LR004646"]},"LR003125":{"pair":"POSTN -> ITGB3","headline":"Periostin-dependent cell adhesion is blocked by anti-alpha(V)beta(3) antibody, supporting ITGB3 as a periostin receptor; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Purified recombinant periostin supports adhesion of ovarian epithelial cells, inhibited by monoclonal antibodies against alpha(V)beta(3) or alpha(V)beta(5), but not by anti-beta(1) antibody [PMID:12235007]. The curator notes alphaVbeta3 colocalises to focal adhesions on periostin [PMID:12235007].","molecular_requirements":"The evidence concerns the alphaV-beta heterodimers, so alphaV with ITGB3 is needed; ITGB3 alone is not tested [PMID:12235007].","affinity_potency":[],"species_and_systems":"Human ovarian epithelial cells, recombinant periostin; read as abstract only [PMID:12235007]. The mouse pair is ortholog-inferred.","localisation_and_range":"Periostin is flagged secreted [flag]; adhesion to purified protein suggests matrix-bound action, which is an inference.","caveats":"Antibody blocking is indirect; the abstract does not report binding or affinity. The same antibody result covers both beta chains and does not separate them. Only one paper confirmed in the shown dossier.","key_references":[{"PMID":"12235007","why":"Antibody-blocked adhesion to periostin via alphaV integrins"}],"covers":["LR003125","LR006346"]},"LR001253":{"pair":"PRLH -> PRLHR","headline":"Well supported agonist pair: PrRP binds GPR10 with sub-nM Kd and activates it in transfected cells; GtoPdb and PDB structures agree.","interaction_type":"direct binding","direction_and_effect":"Human and rat PrRP-20 and PrRP-31 are potent full agonists at GPR10, raising intracellular calcium without changing cAMP [PMID:11030716]. PrRP31 and PrRP20 promoted arachidonic acid metabolite release in receptor-expressing CHO cells but not mock cells [PMID:9607765]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone sufficient in transfected cells. Both the 31- and 20-residue PrRP forms act [PMID:11030716].","affinity_potency":[{"value":"Kd 0.026 nM","assay":"[125I]-PrRP-20 saturation binding, high-affinity site","system":"HEK293 cells stably expressing human GPR10","cite":"PMID:11030716"},{"value":"Kd 0.57 nM","assay":"[125I]-PrRP-20 saturation binding, low-affinity site","system":"HEK293 cells stably expressing human GPR10","cite":"PMID:11030716"}],"species_and_systems":"Human GPR10 in HEK293 [PMID:11030716]; the 1998 identification used human receptor cDNA and rat pituitary cells, with a rat ortholog (UHR-1) in CHO cells [PMID:9607765]. Mouse pair is projected.","localisation_and_range":"PRLH is flagged secreted and PRLHR transmembrane [flag].","caveats":"The 9607765 evidence was browser-read and the curator's quote is unverified pending spot-check; the 11030716 paper was abstract-only. Structures exist [DB:PDB 8ZPS].","key_references":[{"PMID":"11030716","why":"Saturable PrRP binding to GPR10, Kd 0.026 nM"},{"PMID":"9607765","why":"Orphan receptor ligand identification of PrRP"}],"covers":["LR001253","LR004654"]},"LR003134":{"pair":"PRNP -> NCAM1","headline":"Co-crosslinking and binding-site mapping show PrP-NCAM1 complexes in mouse N2a cells, but a sibling row was judged pair_absent; conflicting curation.","interaction_type":"conflicting","direction_and_effect":"PrP(C) was found in complexes with N-CAM splice variants in mouse N2a cells by formaldehyde crosslinking and LC/MS/MS; the PrP-binding site maps to the FNIII modules of N-CAM [PMID:11743735]. N-CAM-/- mice still succumbed to scrapie, so N-CAM is not needed for PrP(Sc) replication [PMID:11743735].","molecular_requirements":"Glycans are not needed; the PrP face uses the N terminus, helix A and adjacent loop [PMID:11743735].","affinity_potency":[],"species_and_systems":"Mouse neuroblastoma N2a and ScN2a cells and N-CAM-/- mice [PMID:11743735].","localisation_and_range":"PRNP is flagged non-secreted; NCAM1 is flagged secreted and transmembrane [flag]. The complexes isolate with caveolae-like domains [PMID:11743735].","caveats":"Same paper has one row confirmed and one pair_absent (human row propagated from the mouse row); both are abstract-only. Complex formation is shown, not signalling or direction. BioGRID lists reconstituted complex, protein-peptide and co-crystal records from another paper [DB:BioGRID].","key_references":[{"PMID":"11743735","why":"In situ crosslinking identifies PrP-N-CAM complexes"}],"covers":["LR003134","LR006355"]},"LR001262":{"pair":"PROS1 -> TYRO3","headline":"Protein S is a long-standing agonist ligand of TYRO3 (Dtk); support from 1995-96 and 2014 abstract-only papers.","interaction_type":"functional only","direction_and_effect":"Protein S was identified as a ligand for Tyro 3 [PMID:7867073]; Dtk (Tyro3) was reported to bind protein S [PMID:8641360]. In reporter cells, TYRO3 had its own interaction and activation pattern with PROS1, modulated by apoptotic cells, phosphatidylserine vesicles and virus [PMID:25074926]. GtoPdb lists the record without type or affinity [DB:GtoPdb].","molecular_requirements":"Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926].","affinity_potency":[],"species_and_systems":"Human proteins and cells in all three papers [PMID:7867073][PMID:8641360][PMID:25074926]; mouse pair listed as not ortholog-inferred but its experiments are not described.","localisation_and_range":"PROS1 flagged secreted [flag]; context-dependent phosphatidylserine presentation affects activation [PMID:25074926].","caveats":"All papers abstract-only; no affinity reported. PMID 8641360 is mainly an expression study in hematopoiesis and its binding statement is background [PMID:8641360]. Two review-only rows and one different-entity row were excluded.","key_references":[{"PMID":"7867073","why":"First identification of protein S as Tyro3/Axl ligand."},{"PMID":"25074926","why":"Reporter-cell study with PROS1 and TYRO3 activation context."},{"PMID":"8641360","why":"Dtk binds protein S; expression in hematopoiesis."}],"covers":["LR001262","LR004662"]},"LR003143":{"pair":"PTH -> LRP6","headline":"PTH engages LRP6 indirectly through a PTH1R/LRP6 complex in one in vitro study.","interaction_type":"functional only","direction_and_effect":"PTH treatment induces endocytosis of a PTH1R/LRP6 complex that enhances Smad1 phosphorylation, an agonist effect [PMID:22589223].","molecular_requirements":"PTH1R is required; the effect was abrogated by PTH1R deletion, and LRP6 forms a complex with PTH1R [PMID:22589223].","affinity_potency":[],"species_and_systems":"Mesenchymal stromal cells in vitro and transplanted cells in vivo, curator lists human ligand and receptor [PMID:22589223].","localisation_and_range":"Ligand and receptor flagged secreted and transmembrane respectively [flag].","caveats":"No direct PTH-LRP6 binding shown; the curator notes the interaction is through complex formation with PTH1R. Abstract only.","key_references":[{"PMID":"22589223","why":"PTH1R/LRP6 endocytosis enhances BMP-Smad1 signalling."}],"covers":["LR003143","LR006364"]},"LR001271":{"pair":"PTHLH -> PTH1R","headline":"PTHrP is a classical PTH1R agonist with structural and binding database records; papers here are mostly indirect.","interaction_type":"direct binding","direction_and_effect":"PTHrP is an agonist of PTH1R. A [Trp23]hPTHrP-(1-36) analogue was a full agonist at the PTH/PTHrP receptor [PMID:8702701]. In intestinal epithelial cells, neutralising PTH1R and antagonising PTHLH prevented TGF-beta1-induced EMT, and PTHLH-PTH1R signals through PKA-Runx2 [PMID:29577935]. UniProt describes PTH1R as a receptor for PTH and PTHLH [DB:UniProt].","molecular_requirements":"Receptor residues 173-189, at the C-terminal end of the N-terminal extracellular domain, contact a PTH agonist photoprobe [PMID:9108031]. Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"pIC50 6.5","assay":"binding/activity of a PTHrP-derived analogue (value as recorded)","system":"human PTH-2 receptor study; recorded against PTH1R row","cite":"PMID:8702701"}],"species_and_systems":"Human ligand and receptor in recombinant HEK-293 cells [PMID:9108031], and human intestinal tissue plus mice [PMID:29577935]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTHLH is flagged as secreted and PTH1R as transmembrane [flag]; paracrine or endocrine.","caveats":"All papers were read as abstracts. PMID 9108031 maps the contact site with a PTH photoprobe, not PTHrP itself. PMID 8702701 used a modified PTHrP analogue and studied mainly PTH2R. The EMT paper is a functional readout. Structures and BioGRID/IntAct records support direct binding [DB:PDB 3H3G] [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"8702701","why":"Residue-23-modified PTHrP is a full agonist at PTH1R"},{"PMID":"9108031","why":"Photoaffinity mapping of receptor contact domain"},{"PMID":"29577935","why":"PTHLH-PTH1R axis drives EMT via PKA-Runx2"}],"covers":["LR001271","LR004671"]},"LR010820":{"pair":"PTN -> CDH10","headline":"Database-only pair resting on a yeast two-hybrid pooling record; no papers confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; IntAct record from a two-hybrid pooling approach [DB:IntAct].","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"One review_only row and an IntAct physical-association record from a high-throughput two-hybrid screen [DB:IntAct]; no validation, no functional data. PTN is flagged secreted, CDH10 has no receptor flag.","key_references":[],"covers":["LR010820"]},"LR003152":{"pair":"PTN -> RNF167","headline":"Single SPR study reports PTN ectodomain binding to RNF167; no functional evidence.","interaction_type":"direct binding","direction_and_effect":"PTN ectodomain captured on sensors bound RNF167; RNF128 was the negative control and showed no binding [PMID:36178190]. Direction or functional effect is not reported in our evidence.","molecular_requirements":"Tested with the RNF167 extracellular domain; co-receptors or subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; surface plasmon resonance with recombinant ectodomains, found as a hit in a CRISPRa cell-based screen [PMID:36178190].","localisation_and_range":"PTN is flagged secreted [flag]. RNF167 has no secreted or transmembrane flag in the dossier; the paper describes it as a transmembrane PA-TM-RING E3 ligase [PMID:36178190].","caveats":"Only one paper, in vitro binding; no affinity reported; the paper notes E3 ligase interactions tend to have very weak affinity and fast kinetics [PMID:36178190]. Physiological signalling relevance not shown.","key_references":[{"PMID":"36178190","why":"SPR binding of PTN to RNF167 ectodomain"}],"covers":["LR003152","LR006373"]},"LR003161":{"pair":"PTPRD -> SLITRK2","headline":"Direct structural and cell-adhesion evidence that PTPRD and SLITRK2 bind; splicing-dependent.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the Slitrk2-PTP-delta trans-synaptic adhesion complex was reported, with mutational analysis showing splicing-dependent adhesion that induces synaptic differentiation [PMID:25989451]. Slitrk2-expressing L cells also aggregated with PTP-delta-expressing L cells [PMID:23345436].","molecular_requirements":"Binding depends on splicing of the type IIa RPTPs and Slitrks [PMID:25989451]. Single-chain sufficiency beyond the two domains crystallised is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Structure paper read as abstract only; species of the proteins in it is not stated in the dossier [PMID:25989451]. Aggregation assay used mouse L cells [PMID:23345436]. Human and mouse pairs both listed, neither projected.","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic adhesion indicates contact-dependent signalling [PMID:25989451].","caveats":"Structural paper was read only as abstract (curator notes were taken from it); the aggregation quote from the second paper is flagged unverifiable pending spot-check. Neither paper reports affinity in our evidence.","key_references":[{"PMID":"25989451","why":"Crystal structure of the Slitrk2-PTP-delta complex"},{"PMID":"23345436","why":"L-cell aggregation of Slitrk2 with PTP-delta cells"}],"covers":["LR003161","LR006382"]},"LR003170":{"pair":"PTPRS -> SLITRK1","headline":"Mouse cell-aggregation evidence that PTP-sigma and SLITRK1 adhere; single paper.","interaction_type":"functional only","direction_and_effect":"Slitrk1-expressing cells aggregated with PTP-sigma-expressing cells; the paper concludes PTP-sigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Slitrks require distinct LAR-RPTP family members for synapse formation, in an isoform-dependent manner [PMID:23345436]. Subunit needs beyond that are not reported. A BioGRID reconstituted complex is listed [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells; the abstract also uses rat brain [PMID:23345436]. Human pair is direct; mouse pair is ortholog-inferred.","localisation_and_range":"Cell-cell aggregation implies contact-dependent action; PTPRS is flagged secreted [flag] [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check. BioGRID lists a reconstituted complex of SLITRK1 and PTPRS from PMID 25394468 [DB:BioGRID].","key_references":[{"PMID":"23345436","why":"Slitrk-PTP-sigma cell aggregation and synapse-formation requirement"}],"covers":["LR003170","LR006391"]},"LR001280":{"pair":"PYY -> NPY1R","headline":"PYY-NPY1R rests only on database records; no paper in our evidence confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists PYY as an agonist of NPY1R [DB:GtoPdb]. UniProt describes NPY1R as a receptor for NPY and PYY [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records physical association by scintillation proximity assay [DB:IntAct]. Species of experiments not reported in our evidence; human and mouse pairs are projected from other evidence (ortholog inferred).","localisation_and_range":"PYY is flagged as secreted and not transmembrane; NPY1R as a transmembrane receptor [flag].","caveats":"No curator-verified paper: three abstracts were insufficient and one was review only. Reactome and UniProt statements are generic to NPY-family peptides. No affinity value in our evidence.","key_references":[],"covers":["LR001280","LR004680"]},"LR006401":{"pair":"RELN -> EFNB3","headline":"Reelin reportedly binds the extracellular domain of ephrin Bs, with mouse genetic interaction; one abstract-only paper and a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"Reelin binds the extracellular domain of ephrin Bs, which associate at the membrane with VLDLR and ApoER2; ephrin B loss impairs Reelin-induced Dab1 phosphorylation [PMID:21460838]. Compound mutants (Reln+/-; Efnb3-/-) show migration defects like the reeler mouse [PMID:21460838].","molecular_requirements":"Ephrin Bs act together with VLDLR and ApoER2 rather than alone; EFNB3-specific binding is not separated from EFNB1/B2 in our evidence [PMID:21460838].","affinity_potency":[],"species_and_systems":"Mouse genetics and neurons per the abstract; curators record human/human [PMID:21460838]. BioGRID lists a Reconstituted Complex record [DB:BioGRID].","localisation_and_range":"Reelin is flagged secreted; EFNB3 is a membrane-bound ligand [flag].","caveats":"One paper read as abstract only; no affinity. Evidence covers ephrin Bs as a group. Human pair is ortholog-inferred; direct data are mouse.","key_references":[{"PMID":"21460838","why":"Reelin binds ephrin B extracellular domain; genetic interaction"}],"covers":["LR003181","LR006401"]},"LR004700":{"pair":"RLN3 -> RXFP3","headline":"Relaxin-3 is the well-supported high-affinity agonist of RXFP3, with binding and functional data across human, mouse and rat receptors.","interaction_type":"direct binding","direction_and_effect":"Relaxin-3 binds GPCR135 (RXFP3) and activates it: GTPgammaS binding is stimulated and cAMP accumulation inhibited [PMID:14522968]; H3 relaxin also activates ERK1/2 via G(i/o) proteins [PMID:17351017]. It is the only insulin/relaxin member reported to activate it [PMID:14522968].","molecular_requirements":"Not reported in our evidence beyond the single receptor chain. BioGRID lists a reconstituted complex and a protein-peptide record [DB:BioGRID]; a PDB entry 9KFI is listed [DB:PDB 9KFI].","affinity_potency":[{"value":"Kd 0.31 nM","assay":"125I-relaxin-3 binding","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"EC50 0.25 nM","assay":"GTPgammaS binding","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"EC50 0.35 nM","assay":"cAMP accumulation inhibition","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"IC50 or EC50 values close to 0.5 nM","assay":"binding and activation","system":"mouse, rat and human GPCR135","cite":"PMID:15367576"}],"species_and_systems":"Human recombinant receptor in CHO-K1 and HEK-293 cells [PMID:17351017]; mouse and rat GPCR135 showed very similar pharmacology to human [PMID:15367576]. The mouse pair is also listed as ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag]; brain co-expression is described [PMID:14522968].","caveats":"Papers were read as abstracts only. Relaxin-3 also acts on other relaxin-family receptors in our evidence (see RXFP1, RXFP4 pairs) [PMID:16411781]. Bradykinin did not activate GPCR135 [PMID:15367576].","key_references":[{"PMID":"14522968","why":"Deorphanisation with Kd and EC50 values"},{"PMID":"15367576","why":"Cross-species conservation of relaxin-3/GPCR135 pharmacology"},{"PMID":"17351017","why":"ERK1/2 signalling downstream of RXFP3"}],"covers":["LR001302","LR004700"]},"LR006410":{"pair":"ROBO1 -> ROBO2","headline":"ROBO1 and ROBO2 ectodomains interact heterophilically; one abstract-only paper plus an IntAct record.","interaction_type":"direct binding","direction_and_effect":"Extracellular domains of Robo1 and Robo2 are homophilic adhesion molecules that can also interact with each other [PMID:12504588]. Direction is a formality for this symmetric adhesion; no agonist or antagonist effect is reported for the pair itself.","molecular_requirements":"Neurite outgrowth was blocked by an antibody against the first Ig domain of Robo1/2 or by soluble Robo-Fc chimera [PMID:12504588]; subunit requirements otherwise not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo1 and Robo2 transfected into 3T3 cells, tested on retinal and olfactory neurons [PMID:12504588]. The mouse pair is projected from human evidence.","localisation_and_range":"Robo2 carries a secreted flag and Robo1 a membrane flag [flag]; the paper describes trans adhesion between family members [PMID:12504588].","caveats":"Abstract only. Binding between the two ectodomains is stated in a single sentence; no affinity. IntAct lists a 'polymerization' record from the same paper [DB:IntAct].","key_references":[{"PMID":"12504588","why":"Only paper: Robo1/Robo2 ectodomain homophilic and heterophilic interaction"}],"covers":["LR003190","LR006410"]},"LR001325":{"pair":"RTN4 -> LINGO1","headline":"LINGO-1 is a component of the Nogo receptor complex; direct Nogo-LINGO-1 binding is not shown.","interaction_type":"functional only","direction_and_effect":"LINGO-1 is described as a component of the NgR1 complexes responding to myelin inhibitors including Nogo, leading to RhoA activation [PMID:15694322]; UniProt also describes it as a functional component of the Nogo receptor complex [DB:UniProt].","molecular_requirements":"LINGO-1 is a fixed component of p75/NgR1/LINGO-1 and TAJ/NgR1/LINGO-1 complexes [PMID:15694322]. NgR1 is required in the complex.","affinity_potency":[],"species_and_systems":"Curators record mouse ligand and receptor; the abstract reports mouse Taj-deficient neurons [PMID:15694322].","localisation_and_range":"RTN4 flagged non-secreted [flag]; LINGO-1 acts within a membrane receptor complex.","caveats":"Direct binding of Nogo to LINGO-1 is not shown; the confirmed row is background stated in the abstract of a TAJ paper. Four other papers had abstracts judged insufficient.","key_references":[{"PMID":"15694322","why":"LINGO-1 as a component of NgR1 complexes; TAJ substitutes for p75"}],"covers":["LR001325","LR004722"]},"LR003206":{"pair":"S100A1 -> TLR4","headline":"Functional evidence in cardiac fibroblasts that S100A1 signals through TLR4/MyD88; direct binding is not shown and the receptor role is indirect.","interaction_type":"functional only","direction_and_effect":"Extracellular S100A1 activates MAPK/SAPK and NF-kB (p65) in cardiac fibroblasts in a TLR4- and MyD88-dependent manner, independent of RAGE [PMID:24833748]. Antibody-mediated S100A1 neutralization enlarged infarct size and worsened left ventricular function post-MI, and CFs adopt an anti-fibrotic phenotype [PMID:24833748]. Reactome asserts S100A1 binds TLR4:LY96 [DB:Reactome R-HSA-6805943].","molecular_requirements":"TLR4 and MyD88 are needed for ERK1/2 activation; RAGE is not. S100A1 is internalized independent of TLR4 but routed to endolysosomes in a TLR4-dependent way, and signalling may arise from an endolysosomal TLR4/MyD88 complex [PMID:24833748]. LY96 (MD-2) requirement is only from Reactome [DB:Reactome R-HSA-6805997].","affinity_potency":[],"species_and_systems":"Human S100A1 in mouse cells: WT, RAGE-/-, TLR4-/- and MyD88-/- fibroblasts, mouse MI model, and patient serum [PMID:24833748].","localisation_and_range":"Released from damaged cardiomyocytes and acts on neighbouring cardiac fibroblasts (paracrine); S100A1 has a secreted flag [PMID:24833748][flag].","caveats":"Binding to TLR4 is inferred from knockout dependence and a proximity ligation colocalisation (supplementary); no Kd or purified binding is in our evidence. Other cell types did not respond. Only the abstract was formally read by the curator. Reactome support rests partly on this same paper.","key_references":[{"PMID":"24833748","why":"TLR4/MyD88-dependent S100A1 signalling in cardiac fibroblasts"}],"covers":["LR003206","LR006426"]},"LR003215":{"pair":"S100A4 -> CCR5","headline":"S100A4 alone binds the CCR5 extracellular domain but is not sufficient for migration; the Tag7-Mts1 complex is needed.","interaction_type":"direct binding","direction_and_effect":"Only Mts1 (S100A4) binds the CCR5 extracellular domain, but this binding is not enough to induce cell movement; the Tag7-Mts1 complex induces PBMC migration via CCR5 and CXCR3 [PMID:30713770]. UniProt records the same function [DB:UniProt].","molecular_requirements":"The intact S100A4-PGLYRP1 (Tag7) complex is required for chemotaxis; Tag7 alone does not bind CCR5 per curator notes [PMID:30713770].","affinity_potency":[],"species_and_systems":"Human PBMC from healthy donors [PMID:30713770].","localisation_and_range":"S100A4 is flagged secreted and CCR5 transmembrane [flag].","caveats":"Abstract only; affinity not reported. S100A4 alone is not functionally sufficient, so scoring S100A4 alone for CCR5 may overstate signalling.","key_references":[{"PMID":"30713770","why":"S100A4 binds CCR5; complex drives migration"}],"covers":["LR003215","LR006433"]},"LR003224":{"pair":"S100A8 -> ALCAM","headline":"ALCAM is reported as an S100A8/A9 receptor in melanoma by binding and NF-kappaB activation; abstract-only and complex-level.","interaction_type":"direct binding","direction_and_effect":"ALCAM and MCAM function as S100A8/A9 receptors like RAGE and induce melanoma progression via NF-kappaB activation and ROS formation; MCAM activates NF-kappaB more than ALCAM or RAGE [PMID:27151304].","molecular_requirements":"The paper concerns the S100A8/A9 complex [PMID:27151304].","affinity_potency":[],"species_and_systems":"Malignant melanoma cells; species not stated in the abstract [PMID:27151304]. Mouse pair is projected.","localisation_and_range":"S100A8 is flagged secreted and ALCAM transmembrane [flag].","caveats":"Abstract only; binding method and affinity not reported in our evidence. S100A8 not separated from S100A9.","key_references":[{"PMID":"27151304","why":"ALCAM/MCAM as S100A8/A9 receptors"}],"covers":["LR003224","LR006441"]},"LR003233":{"pair":"S100A9 -> ALCAM","headline":"ALCAM reported as an S100A8/A9 receptor in melanoma cells; abstract-only functional evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM and MCAM also function as S100A8/A9 receptors as RAGE does, inducing NF-kappaB activation and ROS formation in malignant melanoma; MCAM activates NF-kappaB more prominently than ALCAM [PMID:27151304].","molecular_requirements":"The ligand is the S100A8/A9 complex; S100A9 alone is not separated in our evidence [PMID:27151304].","affinity_potency":[],"species_and_systems":"Human melanoma cells per the abstract; mouse pair is ortholog-inferred.","localisation_and_range":"ALCAM is flagged both secreted and transmembrane [flag], so a soluble form may exist; ligand secreted [flag].","caveats":"Abstract only; no binding measurement or affinity; no database support.","key_references":[{"PMID":"27151304","why":"ALCAM and MCAM function as S100A8/A9 receptors in melanoma"}],"covers":["LR003233","LR006450"]},"LR003242":{"pair":"S100B -> ALCAM","headline":"S100B signals through CD166/ALCAM in mouse endothelial cells; functional evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Binding of S100B to CD166/ALCAM induced dose- and time-dependent NF-kappaB expression in wild type and RAGE(-/-) mouse endothelial cells; ALCAM siRNA completely inhibited S100B-induced NF-kappaB activation in RAGE(-/-) but not in WT cells [PMID:23729438]. Agonist.","molecular_requirements":"Acts independently of RAGE in RAGE(-/-) cells; ALCAM(-/-) and RAGE(-/-) show reciprocal upregulation, with ALCAM(-/-) RAGE(-/-) mice showing a 27% reduction in DTH [PMID:23729438].","affinity_potency":[],"species_and_systems":"Mouse endothelial cells and mice; the human pair is ortholog-inferred, the mouse pair is not [PMID:23729438].","localisation_and_range":"Ligand secreted [flag]; ALCAM flagged secreted and transmembrane [flag].","caveats":"Abstract only; a direct binding assay is not described in our evidence, and no affinity is reported. Compensation by RAGE complicates knockout results.","key_references":[{"PMID":"23729438","why":"ALCAM as S100B receptor, RAGE-independent NF-kB activation"}],"covers":["LR003242","LR006458"]},"LR001334":{"pair":"SCGB3A2 -> MARCO","headline":"UGRP1 (SCGB3A2) identified as a MARCO ligand by expression cloning, with FRET and UniProt support.","interaction_type":"direct binding","direction_and_effect":"Retroviral expression cloning identified MARCO as a receptor for UGRP1; LPS competed with UGRP1 for MARCO and bacterial binding [PMID:12847263]. BioGRID lists a FRET interaction and UniProt states SCGB3A2 binds MARCO [DB:BioGRID][DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; expression cloning, MARCO expressed by alveolar macrophages [PMID:12847263]. Mouse pair is ortholog-inferred.","localisation_and_range":"UGRP1 is secreted [flag]; expressed by lung Clara-like cells, with MARCO on alveolar macrophages [PMID:12847263].","caveats":"Abstract only; no affinity. A second confirmed row is not shown. Binding to bacteria and competition with LPS suggest a scavenger-type role.","key_references":[{"PMID":"12847263","why":"Expression cloning of MARCO as UGRP1 receptor"}],"covers":["LR001334","LR004730"]},"LR003251":{"pair":"SCUBE2 -> KDR","headline":"SCUBE2 is reported as a VEGFR2 co-receptor forming a complex with VEGF and KDR; one paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"SCUBE2 forms a complex with VEGF and VEGFR2 and acts as a coreceptor, facilitating VEGF binding and augmenting VEGFR2 signalling; overexpression increases and knockdown or knockout reduces VEGF-induced angiogenesis and VEGFR2 phosphorylation [PMID:27834687].","molecular_requirements":"SCUBE2 acts together with VEGF and VEGFR2 (ternary complex), not as a stand-alone ligand [PMID:27834687].","affinity_potency":[],"species_and_systems":"Human endothelial cells (lentiviral overexpression and shRNA) plus EC-specific Scube2 knockout mice, Matrigel plugs and hind-limb ischemia [PMID:27834687]. BioGRID lists affinity capture-western [DB:BioGRID].","localisation_and_range":"SCUBE2 is flagged secreted [flag]; the paper calls it a peripheral membrane protein on endothelial cells [PMID:27834687].","caveats":"One paper read as abstract only; no affinity. It is a co-receptor role, so direct binding of SCUBE2 to KDR alone is not shown in our evidence. UniProt notes the interaction [DB:UniProt].","key_references":[{"PMID":"27834687","why":"SCUBE2 as VEGFR2 coreceptor, co-IP and mouse knockout"}],"covers":["LR003251","LR006467"]},"LR001343":{"pair":"SEMA3A -> PLXNA2","headline":"Structural and cell evidence that SEMA3A contacts PlexinA2 within an Nrp1-stabilised ternary complex.","interaction_type":"direct binding","direction_and_effect":"Within each heterotrimer, semaphorin contacts plexin, similar to co-receptor-independent complexes; Nrp1 stabilises a canonical but weakened Sema3-PlxnA interaction [PMID:23104057]. Sema3A, not Sema3C or Sema3F, induces contraction of NP1/PlexA2-expressing COS-7 cells [PMID:11239433]. Effect agonist [PMID:23104057].","molecular_requirements":"Needs Nrp1 co-receptor: Nrp1 cross-braces two Sema3A-PlxnA2 pairings, the Nrp1 a1 domains wedged between Sema3A and PlxnA2 sema domains [PMID:23104057]. NP1 is required with PlexA2 in the cell assay [PMID:11239433]. Reactome: Sema3A binds Nrp-1 bound to PlexinA [DB:Reactome].","affinity_potency":[],"species_and_systems":"Crystal structure of a mouse semaphorin-plexin-Nrp complex (dossier labels species human) [PMID:23104057]; COS-7 assays with mouse-labelled proteins [PMID:11239433].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"The Sema3A-PlxnA2 interaction is weak and the structure is low resolution; the Sema3A-PlxnA2 interface was not among the mutated interfaces [PMID:23104057]. The structural paper was assessed from abstract plus excerpts, the second assay is cell-based, not binding.","key_references":[{"PMID":"23104057","why":"Low-resolution Sema3A-PlxnA2-Nrp1 complex structure"},{"PMID":"11239433","why":"Sema3A contracts NP1/PlexA2 COS-7 cells"}],"covers":["LR001343","LR004739"]},"LR001352":{"pair":"SEMA3E -> PLXND1","headline":"Well-supported direct, neuropilin-independent receptor pair with biochemical, genetic and database support.","interaction_type":"direct binding","direction_and_effect":"Sema3E acts as a repulsive cue for plexin-D1-expressing endothelial cells [PMID:15550623]. Sema3E and Plexin D1 knockdown reduced metastatic potential of human carcinoma cells in mice [PMID:20664171]. Sema3E-Plexin-D1 signaling negatively regulates VEGF-induced Dll4-Notch signaling [PMID:21724832]. Curators labelled the first paper agonist.","molecular_requirements":"Sema3E-plexin-D1 signaling did not require neuropilins [PMID:15550623]. A screen found Sema3E interacts directly with PlxnD1 without Nrp1 or Nrp2 [PMID:26633812]. Database records: IntAct surface plasmon resonance between SEMA3E and PLXND1 [DB:IntAct]; Reactome lists SEMA3E binds to PLXND1 [DB:Reactome]; UniProt notes SH3BP1 dissociates upon SEMA3E binding to PLXND1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse in vivo vascular patterning [PMID:15550623]; human tumor cells in mice [PMID:20664171]; mouse retina [PMID:21724832]; screen with human recombinant proteins [PMID:26633812]. Both species' pairs are not ortholog-inferred.","localisation_and_range":"SEMA3E is annotated secreted [flag]; Sema3E from somites acts on adjacent vessels, a paracrine action [PMID:15550623].","caveats":"Three of four shown papers are abstract-only. The screen sentence in PMID 26633812 is a general statement crediting earlier work for the Sema3E-PlxnD1 direct interaction. No affinity from papers; database record is an SPR assay [DB:IntAct]. Two review_only rows are not shown.","key_references":[{"PMID":"15550623","why":"Sema3E-plexin-D1 patterns vasculature, neuropilin-independent"},{"PMID":"26633812","why":"Biochemical screen reporting direct Sema3-Plxn interactions"},{"PMID":"20664171","why":"Sema3E-PlexinD1 in metastasis"}],"covers":["LR001352","LR004748"]},"LR001361":{"pair":"SEMA4D -> CD72","headline":"SEMA4D (CD100) binds CD72 on lymphocytes in human and mouse studies; well supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified CD72 as the lymphocyte CD100 receptor; CD100 stimulation dephosphorylates CD72 and dissociates SHP-1, turning off CD72 negative signalling [PMID:11114375]. Human CD100-Fc specifically bound CD72-expressing cells and co-stimulated B cells and dendritic cells and induced TNF-alpha, IL-6 and IL-8 [PMID:12882840]. Platelet work shows the same SHP-1 dissociation [PMID:17244710].","molecular_requirements":"CD72 is named alone; the platelet paper also names plexin-B1 as a second SEMA4D receptor [PMID:17244710].","affinity_potency":[{"value":"Kd ~3e-7 M","assay":"receptor affinity on lymphocytes","system":"lymphocytes","cite":"PMID:11114375"}],"species_and_systems":"Human recombinant hCD100-Fc and CD72 [PMID:12882840]; platelets with Sema4d-null mice and ADAM17-null mouse platelets [PMID:17244710].","localisation_and_range":"Sema4D is flagged both secreted and transmembrane [flag]. Platelet paper shows membrane-bound sema4D acting on nearby platelets, then ADAM17-dependent shedding of the extracellular domain [PMID:17244710].","caveats":"All papers abstract only. The Kd of ~3e-7 M is a receptor measurement on lymphocytes, not on purified CD72 [PMID:11114375]. Database records: BioGRID, IntAct, Reactome [DB:BioGRID][DB:Reactome]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"11114375","why":"Expression cloning of CD72 as CD100 receptor"},{"PMID":"12882840","why":"Human CD100-Fc binds human CD72, functional readouts"},{"PMID":"17244710","why":"CD72 and plexin-B1 in platelets"}],"covers":["LR001361","LR004757"]},"LR007400":{"pair":"SEMA6A -> NRP1:PLXNA2","headline":"Database-asserted only; the records describe SEMA6A with PLXNA2, and none in our evidence involves NRP1.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the SEMA6A homodimer interacts with a PLXNA2 homodimer, giving a heterotetramer (By similarity) [DB:UniProt]. Reactome lists a SEMA6A:PLXNA2,PLXNA4 complex [DB:Reactome]. Effect direction is not reported in our evidence.","molecular_requirements":"Neither record includes NRP1, so a requirement for the NRP1:PLXNA2 complex is unsupported here [DB:Reactome][DB:UniProt].","affinity_potency":[],"species_and_systems":"Human entities; no experiment in our evidence.","localisation_and_range":"Ligand is flagged membrane-bound [flag]; receptor complex is flagged transmembrane [flag].","caveats":"No papers; the one paper-judged row was a different entity. The UniProt statement is by similarity.","key_references":[],"covers":["LR007400"]},"LR006500":{"pair":"SEMA6C -> PLXNA1","headline":"Mouse abstract states PlexinA1 is the proprioceptive axon receptor for Sema6C; support is functional loss-of-function, abstract only.","interaction_type":"functional only","direction_and_effect":"PlexinA1 is described as a proprioceptive sensory axon-specific receptor for sema6C and sema6D; loss of plexinA1 signalling causes proprioceptive axons to invade the superficial dorsal horn [PMID:17145500].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse plexinA1 mutant spinal cord; human pair is ortholog-inferred, mouse pair is not.","localisation_and_range":"Ligand is not flagged secreted, so likely membrane-associated; the abstract describes sema6C/6D expressed in the dorsal horn [PMID:17145500].","caveats":"Abstract only; no binding or affinity data in our evidence. The Sema6C-specific effect is not separated from Sema6D. Other judged rows were abstract_insufficient.","key_references":[{"PMID":"17145500","why":"PlexinA1 as receptor for sema6C/6D in proprioceptive axon segregation"}],"covers":["LR003284","LR006500"]},"LR001370":{"pair":"SEMA7A -> ITGB1","headline":"Beta1 integrin is supported only as part of alpha1beta1 in an abstract-only immune study; no chain-specific data.","interaction_type":"functional only","direction_and_effect":"Sema7A stimulates cytokine production in monocytes and macrophages through alpha1beta1 integrin [PMID:17377534]. The modulatory effect is annotated stimulatory. Reactome lists a SEMA7A:Integrin alpha1beta1 complex [DB:Reactome].","molecular_requirements":"Beta1 acts with alpha1 in this study; beta1 alone is not shown to suffice.","affinity_potency":[],"species_and_systems":"Curator notes describe human monocytes/macrophages and Sema7a-/- mice [PMID:17377534].","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; the abstract describes it as GPI-anchored [PMID:17377534].","caveats":"Abstract only; chain-only attribution from a heterodimer, no affinity data.","key_references":[{"PMID":"17377534","why":"Sema7A signals via alpha1beta1 integrin"}],"covers":["LR001370","LR004766"]},"LR005303":{"pair":"SFRP2 -> FZD5","headline":"SFRP2 binds FZD5 and activates NFATc3 signalling in endothelial cells; one full-text paper supports it.","interaction_type":"direct binding","direction_and_effect":"FZD5 is reported as a receptor for SFRP2 and the effect is agonist: FZD5 is necessary for SFRP2-induced tube formation and calcium flux, and required for SFRP2-induced NFATc3 activation [PMID:28840375].","molecular_requirements":"Not reported beyond FZD5 itself; co-receptors or other subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding by co-immunofluorescence, co-immunoprecipitation and ELISA, plus homology modelling, in human SFRP2/FZD5 and mouse endothelial cell lines (2H11, MS1, SVR) [PMID:28840375]. The dossier covers human and mouse pairs.","localisation_and_range":"SFRP2 is flagged secreted [flag], so paracrine or autocrine action is plausible.","caveats":"Single paper; the curator read depth is abstract-only, though full-text excerpts were available. Binding affinity is not quantified in the excerpts. Mouse cells were used with recombinant human SFRP2.","key_references":[{"PMID":"28840375","why":"Binding assays and FZD5 knockdown linking SFRP2 to NFATc3 and angiogenesis"}],"covers":["LR001973","LR005303"]},"LR003305":{"pair":"SIGLEC10 -> AOC3","headline":"Siglec-10 binds VAP-1 (AOC3) in one phage-display study with adhesion assays; VAP-1 also uses Siglec-10 as an enzyme substrate.","interaction_type":"direct binding","direction_and_effect":"Siglec-10 was identified as a leukocyte ligand for VAP-1 by phage display; binding was verified by adhesion assays and the interaction increased hydrogen peroxide production, indicating Siglec-10 is a substrate for VAP-1 [PMID:19861682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, leukocytes and endothelial adhesion assays [PMID:19861682].","localisation_and_range":"AOC3 is an endothelial adhesin on inflamed endothelium; contact-dependent [PMID:19861682]. SIGLEC10 flagged secreted [flag], which may be an annotation artefact.","caveats":"Abstract-only; single paper. The enzyme-substrate effect means the interaction is not purely receptor signalling. No affinity.","key_references":[{"PMID":"19861682","why":"Siglec-10 is a leukocyte ligand for VAP-1"}],"covers":["LR003305"]},"LR005312":{"pair":"SLAMF7 -> SLAMF7","headline":"Homophilic SLAMF7 interaction reported in myeloma cells (soluble to surface), plus IntAct and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Soluble SLAMF7 enhanced multiple-myeloma cell growth through homophilic interaction with surface SLAMF7, activating SHP-2 and ERK; elotuzumab suppressed this in vitro and in vivo [PMID:31358854].","molecular_requirements":"Cleaved soluble SLAMF7 acts on surface SLAMF7 [PMID:31358854]. Further subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human myeloma cells and a murine xenograft model [PMID:31358854].","localisation_and_range":"Soluble form shed from the membrane, detected in myeloma-patient serum, so potentially paracrine or endocrine; membrane form acts by contact [PMID:31358854].","caveats":"Abstract only; no affinity. IntAct (FACS, protein array, solid phase) and Reactome dimer records support self-interaction [DB:IntAct] [DB:Reactome]. A second confirmed row is not shown.","key_references":[{"PMID":"31358854","why":"Soluble SLAMF7 homophilic action on myeloma cells"}],"covers":["LR001983","LR005312"]},"LR003314":{"pair":"SLIT3 -> PLXNA1","headline":"Slit3-C fragment is reported as a PlexinA1 receptor ligand in brown fat; one bioRxiv abstract.","interaction_type":"functional only","direction_and_effect":"Plxna1 is reported as a previously unrecognised receptor for Slit3-C and is essential for sympathetic innervation and cold-induced neurite expansion in BAT [PMID:39386533].","molecular_requirements":"Cleavage of Slit3 yields Slit3-N and Slit3-C; Slit3-C acts on Plxna1 while Slit3-N binds a distinct receptor [PMID:39386533]. Bmp1 is the cleaving protease [PMID:39386533].","affinity_potency":[],"species_and_systems":"Mouse brown adipose tissue is implied; species of the experiments is not stated in the abstract [PMID:39386533]. Mouse pair is non-inferred, human ortholog-inferred.","localisation_and_range":"Secreted by adipocyte progenitors [PMID:39386533].","caveats":"Preprint, abstract only; the assay is annotated direct_binding but the abstract shows functional requirement, binding data not reported in our evidence. Two other abstracts insufficient.","key_references":[{"PMID":"39386533","why":"Plxna1 as Slit3-C receptor in BAT"}],"covers":["LR003314","LR006528"]},"LR005321":{"pair":"SLITRK3 -> PTPRD","headline":"SLITRK3 acts via PTPdelta to drive inhibitory synapses; two papers, one with Slitrk3-deficient mice.","interaction_type":"direct binding","direction_and_effect":"Slitrk3 is a postsynaptic adhesion molecule that selectively regulates inhibitory synapse development via trans-interaction with axonal PTPdelta; Slitrk3-deficient mice have fewer inhibitory synapses [PMID:22286174]. Slitrk3-expressing L cells aggregated with PTPdelta cells [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Fibroblasts with co-cultured rat hippocampal neurons, and mice [PMID:22286174]; mouse L cells [PMID:23345436]. Both pairs ortholog-inferred.","localisation_and_range":"Trans-synaptic contact: postsynaptic Slitrk3 on inhibitory sites, axonal PTPdelta [PMID:22286174].","caveats":"Direct binding is inferred from a coculture trans-interaction assay in the abstract. Four review-only rows not shown.","key_references":[{"PMID":"22286174","why":"Slitrk3 inhibitory synapses via PTPdelta"},{"PMID":"23345436","why":"Slitrk3 L-cell aggregation with PTPdelta"}],"covers":["LR001992","LR005321"]},"LR003323":{"pair":"SLURP2 -> CHRNB4","headline":"SLURP-2 co-purifies the beta4 nAChR subunit; a possible alpha3beta4 target in PC12 cells; one paper.","interaction_type":"direct binding","direction_and_effect":"Affinity purification from cortical extracts shows SLURP-2 binds the beta4 subunit [PMID:27485575]. In PC12 cells, SLURP-2 influenced nicotine-induced ERK1/2 phosphorylation, suggesting alpha3beta4 nAChR as another possible target [PMID:27485575].","molecular_requirements":"The alpha3beta4 combination is suggested as the functional target; beta4 alone was not tested for function [PMID:27485575].","affinity_potency":[],"species_and_systems":"Recombinant human SLURP-2 (rSLURP-2); human receptors in Xenopus oocytes and CHO cells, affinity purification from cortical brain extracts, and human oral keratinocyte Het-1A cells [PMID:27485575]. Species of the brain extract is not reported in our evidence. PC12 cells were also used [PMID:27485575].","localisation_and_range":"SLURP2 is flagged as secreted [flag]; the receptor is flagged as a receptor [flag]. Range is not discussed in our evidence.","caveats":"Functional link to beta4 is indirect and described as 'possible'. No affinity reported. Single paper.","key_references":[{"PMID":"27485575","why":"Recombinant SLURP-2 pharmacology and binding to acetylcholine receptors"}],"covers":["LR003323"]},"LR005330":{"pair":"SOSTDC1 -> LRP6","headline":"Wise/SOSTDC1 physically binds LRP6 and competes with Wnt8; three papers, all abstract-level, with a context-dependent effect.","interaction_type":"direct binding","direction_and_effect":"Wise interacts physically with LRP6 and competes with Wnt8 for binding; it activates Wnt signalling in Xenopus animal caps but antagonises Wnt8-induced secondary axis, so effect is context-dependent [PMID:12900447]. In human-origin work Wise blocks Wnt1 activity via LRP6 [PMID:19553665]. In mouse tooth it inhibits Lrp5/6-dependent Wnt signalling [PMID:20724449].","molecular_requirements":"Wise binds LRP6 through one of three cystine-knot loops; a deletion lacking that loop still binds BMP4, and BMP4 does not interfere with Wise-LRP6 binding. Extra LRP6 prevents Wise inhibiting BMP4 [PMID:19553665].","affinity_potency":[],"species_and_systems":"Xenopus [PMID:12900447]; human proteins [PMID:19553665]; mouse tooth in vivo [PMID:20724449]. Mouse pair ortholog-inferred.","localisation_and_range":"Wise is secreted; acts on the surface co-receptor LRP6 [flag] [PMID:19553665] (cell-surface heparan sulfate association noted).","caveats":"All abstracts only. Activating versus inhibiting outcome depends on context. No affinity values. No database records.","key_references":[{"PMID":"12900447","why":"Wise binds LRP6, competes with Wnt8; dual activity"},{"PMID":"19553665","why":"Wise binds LRP6 via a cystine-knot loop, separate from BMP4"},{"PMID":"20724449","why":"Mouse tooth genetics, Lrp5/6 dependence"}],"covers":["LR002002","LR005330"]},"LR001406":{"pair":"SPP1 -> ITGA5","headline":"SPP1 activates integrin alpha5beta1 in rat nucleus pulposus cells; one full-text functional paper and database complexes.","interaction_type":"functional only","direction_and_effect":"SPP1 accelerates nucleus pulposus cell degeneration by activating integrin alpha5beta1, aggravating mitochondrial damage and inhibiting mitophagy via PINK1/PARKIN blockade [PMID:39721032].","molecular_requirements":"The receptor is alpha5beta1 (ITGA5/ITGB1) [PMID:39721032]. The ITGA5 entity is annotated as integrin alpha5beta1 [flag]. Reactome lists SPP1 with alpha5beta1 and alpha9beta1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human degenerated discs showed elevated SPP1 and ITGA5; rat nucleus pulposus cells were used for SPP1 knockdown experiments [PMID:39721032].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA5 not secreted [flag].","caveats":"The paper is a disease-mechanism study; the excerpts shown do not include a direct binding assay. Read with abstract plus excerpts only. Binding evidence sits in the ITGA5:ITGB1 dossier.","key_references":[{"PMID":"39721032","why":"SPP1-ITGA5/B1 axis inhibits mitophagy in nucleus pulposus cells"}],"covers":["LR001406","LR004801"]},"LR002009":{"pair":"SPP1 -> ITGB3","headline":"Osteopontin is reported to engage integrin alphavbeta3 (RGD-dependent); our own evidence is thin and abstract-level.","interaction_type":"direct binding","direction_and_effect":"Osteopontin is a ligand for alphavbeta3 [PMID:16005200]; alphavbeta3 is described as a previously known OPN-binding integrin [PMID:7592829]. Effect direction is not reported in our evidence.","molecular_requirements":"alphavbeta3 binds the RGD site of osteopontin; thrombin cleavage is not required for optimal adhesion [PMID:16005200]. The heterodimer, not ITGB3 alone, is the binding unit.","affinity_potency":[],"species_and_systems":"Experimental species unspecified [PMID:16005200]; human GST-OPN with HEK293 cells in the background paper, where alphavbeta3 was not the new finding [PMID:7592829].","localisation_and_range":"SPP1 is flagged secreted [flag]; OPN is called an extracellular matrix protein [PMID:7592829].","caveats":"Both papers were read as abstracts only and neither mainly tests alphavbeta3. The mouse pair is ortholog-inferred. Reactome has an alphaVbeta3:SPP1 complex [DB:Reactome]. One further paper was judged abstract-insufficient.","key_references":[{"PMID":"16005200","why":"Compares RGD dependence across five OPN integrins"},{"PMID":"7592829","why":"States alphavbeta3 as known OPN receptor"}],"covers":["LR002009","LR005337"]},"LR003332":{"pair":"SPP1 -> ITGB6","headline":"Osteopontin is identified as an alphavbeta6 ligand by one abstract-level paper; direct but single-source.","interaction_type":"direct binding","direction_and_effect":"alphavbeta6 is identified as an osteopontin receptor by affinity chromatography and cell adhesion [PMID:16005200]. Effect direction not reported in our evidence.","molecular_requirements":"alphavbeta6 binds the RGD site (RGD peptide or RAA mutation abolishes adhesion); thrombin cleavage is not needed for optimal adhesion [PMID:16005200].","affinity_potency":[],"species_and_systems":"Species not specified in the abstract; recombinant OPN forms in cell adhesion assays [PMID:16005200].","localisation_and_range":"SPP1 is flagged secreted [flag].","caveats":"Single paper, abstract only; no database record. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"16005200","why":"Identifies alphavbeta6 as an OPN receptor"}],"covers":["LR003332","LR006539"]},"LR001415":{"pair":"TAC1 -> TACR1","headline":"Tachykinins from TAC1 (substance P, neurokinin A) bind and activate NK1/TACR1 with nanomolar affinity; strongly supported by binding, structures and databases.","interaction_type":"direct binding","direction_and_effect":"Agonist. Substance P binds NK1 saturably with high affinity [PMID:1311270]. Neurokinin A also binds NK-1 with high affinity, though it competes poorly against radiolabelled substance P [PMID:8985159]. GtoPdb records full agonist [DB:GtoPdb]. In NT2-N neuronal cells SP/NK-1R signalling regulates MIP-1beta [PMID:12548712].","molecular_requirements":"Single receptor chain. Chimeric human NK1/NK3 receptors showed conserved C-terminal tachykinin sequences matter for binding [PMID:8702757]. Structures of TACR1 with TAC1 peptide are in PDB [DB:PDB 2KS9][DB:PDB 7P00]; Reactome lists TACR1:TAC1(58-68) [DB:Reactome].","affinity_potency":[{"value":"Kd = 0.17 nM","assay":"radiolabelled substance P saturation binding","system":"stable CHO clones expressing rat NK1","cite":"PMID:1311270"},{"value":"Kd=0.51nM","assay":"homologous binding of radiolabelled NKA","system":"cloned NK-1 receptor in COS-7 cells","cite":"PMID:8985159"},{"value":"Ki=0.13 nM","assay":"SP, [3H]-substance P competition","system":"human NK1","cite":"PMID:11786503"}],"species_and_systems":"Mostly recombinant human receptors (COS-7, HEK) [PMID:8985159][PMID:11786503][PMID:8702757]; rat receptors in CHO cells [PMID:1311270]; human NT2-N cells [PMID:12548712]. Mouse pair is projected from human.","localisation_and_range":"TAC1 is flagged secreted and TACR1 transmembrane, implying paracrine or neuronal signalling [flag].","caveats":"All shown papers are abstract-level. Dossier ligand is labelled neurokinin A but most evidence uses substance P; NKA is a lower-potency NK1 ligand than SP in competition [PMID:8985159]. The NT2-N paper shows co-expression and functional coupling, not binding [PMID:12548712]. Rat Kd for NKA (3.4 nM) in PMID:1311270 is at NK2, not NK1.","key_references":[{"PMID":"8985159","why":"NKA and septide bind NK-1 with high affinity"},{"PMID":"1311270","why":"SP binding to rat NK1 in stable CHO clones"},{"PMID":"11786503","why":"SP Ki at human NK1"}],"covers":["LR001415","LR004810"]},"LR003341":{"pair":"TAFA1 -> CMKLR2","headline":"The cited paper shows FAM19A1 (TAFA1) acting through GPR1, not directly CMKLR2; support depends on an alias match.","interaction_type":"functional only","direction_and_effect":"Antagonist-labelled by curators. The paper identifies GPR1 as a functional receptor for FAM19A1, and GPR1's N-terminal domain neutralised FAM19A1 effects on neural stem cells [PMID:29799787].","molecular_requirements":"FAM19A1 interacted with GPR1 via its N-terminal domain; ROCK/ERK1/2 and ROCK/STAT3 pathways were required [PMID:29799787].","affinity_potency":[],"species_and_systems":"Neural stem cell proliferation assays with recombinant FAM19A1 [PMID:29799787].","localisation_and_range":"TAFA1 is flagged secreted [flag]; the paper calls FAM19A1 a classic secretory protein [PMID:29799787].","caveats":"Abstract only. The curator note says GPR1 is gene-symbol-aliased to CMKLR2, so this pair rests on aliasing, not a CMKLR2 experiment [PMID:29799787]. No database records.","key_references":[{"PMID":"29799787","why":"FAM19A1 identified as GPR1 ligand in neural stem cells"}],"covers":["LR003341","LR006548"]},"LR003350":{"pair":"TAFA2 -> RNF167","headline":"TAFA2 binds the RING E3 ligase RNF167 ectodomain by SPR in one screening paper; no affinity or function reported.","interaction_type":"direct binding","direction_and_effect":"SPR sensorgrams showed human TAFA-2 binding to RNF167-ECD, with MCAM as a no-binding comparison [PMID:36178190]. RNF167 was a shared CRISPRa screen hit for PTN, TAFA-2 and TAFA-5 [PMID:36178190]. Effect on RNF167 is not reported in our evidence.","molecular_requirements":"RNF167 is described as a transmembrane PA-TM-RING E3 ligase; the ectodomain alone was used [PMID:36178190].","affinity_potency":[],"species_and_systems":"Recombinant human proteins, SPR [PMID:36178190]. Mouse pair is projected by orthology.","localisation_and_range":"TAFA2 annotated secreted [flag]; RNF167 annotated receptor [flag].","caveats":"Single paper. The authors note that RING E3 ligase interactions are characterised by weak affinity and fast kinetics [PMID:36178190]. Whether TAFA2 acts as a signalling ligand for an E3 ligase is not shown.","key_references":[{"PMID":"36178190","why":"SPR binding of TAFA-2 to RNF167-ECD after a CRISPRa screen"}],"covers":["LR003350","LR006553"]},"LR001424":{"pair":"TCN2 -> LRP2","headline":"Megalin (LRP2) binds the TC-B12 complex with high affinity; evidence is rabbit/rat, human and mouse pairs are inferred.","interaction_type":"direct binding","direction_and_effect":"Ligand blotting showed 125I-TC-B12 binds exclusively to megalin in rabbit kidney cortex, and SPR showed a high-affinity interaction with purified rabbit megalin [PMID:8710919]. 125I-TC-B12 was endocytosed in a RAP-inhibitable way in megalin-expressing cells and in perfused rat proximal tubules [PMID:8710919]. This makes megalin an uptake receptor for vitamin B12 [PMID:8710919].","molecular_requirements":"Binding is Ca2+ dependent and inhibited by RAP; the complex is TC bound to B12 [PMID:8710919]. The related receptor LRP (\u03b12MR) showed no measurable affinity [PMID:8710919].","affinity_potency":[],"species_and_systems":"Rabbit TC-B12 and purified rabbit megalin (SPR), rat yolk sac carcinoma cells and rat kidney [PMID:8710919]. Both listed pairs (human, mouse) are ortholog-inferred. Reactome also lists the complex [DB:Reactome].","localisation_and_range":"Megalin is a 600-kDa endocytic receptor of renal proximal tubule epithelium and other absorptive epithelia [PMID:8710919]; TCN2 annotated secreted [flag].","caveats":"Abstract only; no KD value is given in our excerpt. Human evidence is not directly held.","key_references":[{"PMID":"8710919","why":"SPR, ligand blotting and uptake show megalin binds TC-B12"}],"covers":["LR001424","LR004819"]},"LR001433":{"pair":"TF -> TFR2","headline":"Transferrin binds soluble TfR2 directly (Kd 27 nM, human proteins), weaker than to TfR.","interaction_type":"direct binding","direction_and_effect":"Iron-loaded transferrin (Fe-Tf) binds TfR2; TfR2 was previously found functional for iron uptake in transfected cells [PMID:11027676]. Reactome describes TFR2 dimer binding 2 holoTF on the plasma membrane [DB:Reactome].","molecular_requirements":"Reactome models a TFR2 dimer with 2 holoTF [DB:Reactome]. Iron-loaded Tf was the ligand tested [PMID:11027676].","affinity_potency":[{"value":"Kd 27 nM","assay":"surface plasmon resonance with soluble forms; 25-fold lower affinity than TfR for Tf","system":"soluble human proteins","cite":"PMID:11027676"}],"species_and_systems":"Soluble human TfR2 and Tf; no detectable TfR2-HFE binding [PMID:11027676].","localisation_and_range":"TF is annotated secreted and TFR2 as transmembrane receptor [flag], consistent with a circulating ligand and a cell-surface receptor.","caveats":"Abstract only was read. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"11027676","why":"SPR Kd of TfR2 for iron-loaded Tf"}],"covers":["LR001433"]},"LR001460":{"pair":"TG -> ASGR1","headline":"Only indirect evidence: thyroglobulin competed with a hepatitis C virus preparation for asialoglycoprotein receptor binding.","interaction_type":"functional only","direction_and_effect":"Thyroglobulin and asialothyroglobulin partially prevented binding of HCV structural proteins to human hepatocytes [PMID:12477859]. Direction and effect of TG on ASGR1 are not reported in our evidence.","molecular_requirements":"Binding was decreased by calcium depletion [PMID:12477859]. Subunit requirements for TG are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured human hepatic cells [PMID:12477859].","localisation_and_range":"TG is annotated secreted [flag].","caveats":"Thyroglobulin was only used as a competitor in an HCV binding assay; no direct TG-ASGR1 binding was measured. Abstract only.","key_references":[{"PMID":"12477859","why":"HCV binding competed by thyroglobulin"}],"covers":["LR001460"]},"LR001442":{"pair":"TGFB1 -> SDC2","headline":"Syndecan-2 ectodomain binds TGF-beta directly, with regulatory effect on signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"S2 core protein ectodomain directly bound TGF-beta, and S2 promoted TGF-beta binding in renal papillary fibroblasts; S2 regulates TGF-beta-mediated matrix deposition [PMID:14976204].","molecular_requirements":"Ectodomain binds; a cytoplasmic-truncated S2 also promoted binding [PMID:14976204]. TGF-beta isoform not stated in our evidence.","affinity_potency":[],"species_and_systems":"Renal papillary fibroblast transfection; species not reported in our evidence [PMID:14976204].","localisation_and_range":"TGFB1 is flagged secreted [flag]. SDC2 is annotated transmembrane [flag]; it is a transmembrane heparan sulfate proteoglycan [PMID:14976204].","caveats":"Abstract read only; isoform of TGF-beta not specified, and affinity not reported. Syndecan acts as a regulator rather than a signalling receptor. One further paper abstract-insufficient.","key_references":[{"PMID":"14976204","why":"S2 ectodomain directly binds TGF-beta"}],"covers":["LR001442","LR004837"]},"LR002018":{"pair":"TGFB1 -> VASN","headline":"TGF-beta1 binds vasorin directly and vasorin dampens its signalling; vasorin acts as a TGF-beta binding modulator, not a classic receptor.","interaction_type":"direct binding","direction_and_effect":"Vasorin directly binds TGF-beta and attenuates TGF-beta signalling in vitro; restoring vasorin in vivo reduced injury-induced vascular lesions, partly via TGF-beta inhibition, an antagonist/decoy-like role [PMID:15247411]. Desialylation of VASN enhanced TGF-beta1 binding 2- to 3-fold and dampened TGF-beta1 signalling and angiogenesis [PMID:30252131].","molecular_requirements":"Not reported in our evidence beyond VASN being the binding partner. Full text reports binding fold to TGF-beta1 of 3.2x without alpha2,3-sialic acid and 1.45x without N-glycan [PMID:30252131].","affinity_potency":[],"species_and_systems":"Human VASN and TGF-beta1 in the 2018 work (MCF7 secreted VASN, HUVEC readouts); in vivo arterial injury model in the 2004 paper [PMID:30252131][PMID:15247411]. Mouse pair is ortholog-projected.","localisation_and_range":"Vasorin is a type I membrane protein [PMID:15247411]; a secreted form (sVASN, 93 kDa) occurs in MCF7 medium [PMID:30252131]. Our receptor flag marks it non-transmembrane [flag].","caveats":"Both papers were judged on abstracts, the second with full-text excerpts. Glycosylation modulates binding, so affinity depends on the VASN form. BioGRID and UniProt also list the interaction [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"15247411","why":"Direct TGF-beta binding by vasorin, antagonism in vitro and in vivo"},{"PMID":"30252131","why":"Sialylation of VASN changes TGF-beta1 binding 2- to 3-fold"}],"covers":["LR002018","LR005346"]},"LR001451":{"pair":"TGFB3 -> TGFBR1","headline":"TGF-beta3 to TGFBR1 rests on database records, including a ligand-receptor structure; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists TGFB3-TGFBR1 as agonist [DB:GtoPdb]; a structure of the TGF-beta signalling complex exists [DB:PDB 2PJY]. IntAct lists molecular sieving [DB:IntAct].","molecular_requirements":"UniProt says ligands assemble TGFBR1 and TGFBR2 heterohexamers; not reported for TGFBR1 alone in our evidence.","affinity_potency":[],"species_and_systems":"No papers verified; four judged abstract-insufficient.","localisation_and_range":"Ligand secreted [flag].","caveats":"No curator-verified paper; annotated stimulatory [flag].","key_references":[],"covers":["LR001451","LR004846"]},"LR010712":{"pair":"THBS1 -> ITGA3:ITGB1","headline":"Functional evidence for alpha3beta1 as a THBS1 receptor, plus pan-beta1 adhesion data; no affinity.","interaction_type":"functional only","direction_and_effect":"Breast carcinoma adhesion and chemotaxis to TSP1 are mainly mediated by alpha3beta1 [PMID:10196234]. In a human immuno-lung organoid model, the THBS1-(ITGA3+ITGB1) axis was reported to drive macrophage-induced lung cell senescence (agonist) [PMID:40712141]. beta1 integrins mediate cell adhesion to THBS1 type 1 and type 2 repeats, with pan-beta1 specificity for the type 1 repeats [PMID:15292271].","molecular_requirements":"Both ITGA3 and ITGB1 are named as the receptor [PMID:40712141]. beta1 expression is necessary for adhesion to type 1/2 repeats, and divalent cations are needed [PMID:15292271]. Reactome and BioGRID support the beta1-containing complexes [DB:Reactome][DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human cells: breast carcinoma lines [PMID:10196234], hPSC-derived lung organoids with macrophages and COVID-19 lung tissue [PMID:40712141].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"Two of three papers were read as abstracts only. The organoid paper infers the axis from signalling and spatial transcriptomics, not binding. The 2004 paper is not alpha3-specific. Three further papers were judged abstract-insufficient.","key_references":[{"PMID":"10196234","why":"alpha3beta1 mediates adhesion and chemotaxis to TSP1"},{"PMID":"40712141","why":"THBS1-(ITGA3+ITGB1) axis in macrophage-driven lung senescence (full text)"},{"PMID":"15292271","why":"beta1 integrins bind TSP1 type 1/2 repeats"}],"covers":["LR010712"]},"LR011441":{"pair":"THBS2 -> SDC4","headline":"One 2025 abstract states CAF-secreted THBS2 binds SDC4 on lung adenocarcinoma cells and enhances EMT.","interaction_type":"direct binding","direction_and_effect":"THBS2 secreted by mCAFs directly binds SDC4 on tumour cells, enhancing EMT programs [PMID:40973793]. Stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Lung adenocarcinoma tumour cells, in vivo and in vitro [PMID:40973793].","localisation_and_range":"Secreted by cancer-associated fibroblasts and acts on tumour cells (paracrine) [PMID:40973793].","caveats":"Abstract only; method of binding not stated; two other rows abstract_insufficient.","key_references":[{"PMID":"40973793","why":"THBS2 from mCAFs binds SDC4 on tumour cells"}],"covers":["LR011441"]},"LR008201":{"pair":"TIMP2 -> ITGA3:ITGB1","headline":"TIMP-2 binds alpha3beta1 on endothelial cells and inhibits proliferation; one abstract-read paper with a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"Anti-angiogenic TIMP-2 effects required alpha3beta1-mediated binding of TIMP-2 to endothelial cells, lowering beta1-associated PTP activity and dissociating SHP-1, with higher PTP activity on FGFR-1 and KDR; the effect is antagonist/inhibitory of proliferation [PMID:12887919]. BioGRID lists a reconstituted complex for TIMP2-ITGB1 [DB:BioGRID].","molecular_requirements":"Both ITGA3 and ITGB1 are members of the receptor complex [flag]; the paper implicates the heterodimer, and chain-only sufficiency is not reported in our evidence [PMID:12887919].","affinity_potency":[],"species_and_systems":"Human endothelial cells per curated row [PMID:12887919].","localisation_and_range":"TIMP2 flagged secreted [flag].","caveats":"Single paper read as abstract; no affinity. The BioGRID record is for ITGB1, not the heterodimer [DB:BioGRID].","key_references":[{"PMID":"12887919","why":"alpha3beta1-dependent TIMP-2 action"}],"covers":["LR008201"]},"LR003404":{"pair":"TIMP2 -> MMP2","headline":"TIMP-2 binds MMP-2 (crystal structure, binding assays), but this is an inhibitor-enzyme interaction rather than classic signalling.","interaction_type":"direct binding","direction_and_effect":"TIMP-2 forms a complex with MMP-2 and, with MT1-MMP, a ternary complex with pro-MMP-2 that permits activation by a neighbouring TIMP-2-free MT1-MMP [PMID:12755684]. Low TIMP-2 levels increased MMP-2 activation and invasion in glioblastoma cells, whereas higher levels inhibited it [PMID:14631378]. A co-crystal structure exists [DB:PDB 1GXD].","molecular_requirements":"Ternary complex with MT1-MMP and pro-MMP-2 [PMID:12755684]. MMP2 is flagged both secreted and receptor, not transmembrane [flag].","affinity_potency":[],"species_and_systems":"Human cell systems (glioblastoma lines, engineered cells and plasma membrane fractions) [PMID:12755684][PMID:14631378]; mouse pair is ortholog-inferred.","localisation_and_range":"MMP2 is flagged secreted, so interaction is extracellular and pericellular [flag]; the ternary complex forms on the cell surface [PMID:12755684].","caveats":"Both papers read as abstracts. Effect is dose-dependent: higher TIMP-2 inhibits MMP-2 activation [PMID:14631378]. Binding is enzyme-inhibitor binding; MMP-2 as a receptor comes from an annotation flag.","key_references":[{"PMID":"12755684","why":"TIMP-2/MT1-MMP/pro-MMP-2 ternary complex"},{"PMID":"14631378","why":"TIMP-2 level effects on MMP-2 activation"}],"covers":["LR003404","LR006605"]},"LR001514":{"pair":"TNF -> TNFRSF1B","headline":"TNF engages TNFR2 according to databases and indirect papers; no quantified TNFR2 binding is reported in our evidence.","interaction_type":"direct binding","direction_and_effect":"Reactome describes TNFA trimer binding TNFR2 and recruitment of further TNFR2 [DB:Reactome]. A TNFR2-selective TNF mutant had no significant effect on feline cardiac myocyte motion, unlike the TNFR1-selective mutant [PMID:7664431].","molecular_requirements":"Reactome lists TNFA trimer:TNFR2 trimer complexes [DB:Reactome]. Receptor-selective TNF mutants binding only TNFR2 were isolated by phage display [PMID:19084540].","affinity_potency":[],"species_and_systems":"Human proteins in the papers [PMID:19084540][PMID:17195449]; feline cardiac myocytes with human TNF mutants [PMID:7664431]. Reconstituted-complex and solid-phase records exist [DB:BioGRID][DB:IntAct]. A PDB structure 3ALQ shows TNF with TNFR2 [DB:PDB 3ALQ]. A mouse pair was projected from human evidence.","localisation_and_range":"TNF and TNFR2 are flagged secreted and transmembrane [flag].","caveats":"The confirming papers are abstract-only and mostly background statements: no Kd for TNF at TNFR2 is given [PMID:17195449][PMID:19084540]. GtoPdb lists no affinity or action [DB:GtoPdb]. The cardiac study shows TNFR2 binding of the mutant but no functional effect there [PMID:7664431].","key_references":[{"PMID":"7664431","why":"Receptor-selective TNF mutants in cardiac myocytes"},{"PMID":"19084540","why":"Phage display of TNFR2-selective TNF mutants"}],"covers":["LR001514","LR004904"]},"LR003413":{"pair":"TNFAIP6 -> LRP1","headline":"TSG6 (TNFAIP6) binds purified LRP1 directly in a chondrocyte ligandome study; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"TSG6 was one of ten ligands whose direct LRP1 binding was confirmed, with a correlation between LRP1 affinity and endocytosis rate [PMID:36028175]. LRP1 acts as an endocytic receptor, so LRP1 clears TSG6 from the extracellular space [PMID:36028175]. Agonist versus other effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Direct binding assays with purified LRP1, validation in LRP1-deficient fibroblasts and human chondrocytes, and a conditional Lrp1 knockout mouse [PMID:36028175]. The curator lists both ligand and receptor as human. A mouse pair was projected from human evidence.","localisation_and_range":"TNFAIP6 is flagged secreted; LRP1 flagged as a receptor [flag].","caveats":"Only the abstract was read and no affinity value is given for TSG6; it is one of ten ligands in a screen [PMID:36028175]. No database records are present.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding of TSG6 in cartilage ligandome"}],"covers":["LR003413","LR006614"]},"LR001505":{"pair":"TNFSF13 -> TNFRSF1A","headline":"No supporting paper; the curated paper does not mention TNFR1, leaving only a BioGRID record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"APRIL flagged secreted, TNFRSF1A transmembrane [flag].","caveats":"The curated paper (abstract only) reported coprecipitation of Fas and HVEM only; TNFR1 is not named as a partner, so the verified outcome is pair_absent [PMID:10706119]. The BioGRID record cites that same paper [DB:BioGRID]. Likely a mis-attribution.","key_references":[],"covers":["LR001505","LR004895"]},"LR003422":{"pair":"TSKU -> FZD3","headline":"Tsukushi binds Fzd3 with Kd 2.7 x 10-10 M in vitro; one browser-read Results sentence, spot-check pending.","interaction_type":"direct binding","direction_and_effect":"Fzd3 binds TSK with high affinity in vitro, suggesting TSK modulates Wnt signaling in the SVZ; TSK deficiency causes hydrocephalus and dysregulated Wnt signaling in mice [PMID:33790026]. Agonist or antagonist action at Fzd3 not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[{"value":"Kd 2.7 x 10-10 M","assay":"in vitro binding (Fig. 7B)","system":"Fzd3 with TSK","cite":"PMID:33790026"}],"species_and_systems":"Mouse model (TSK knockout) and in vitro binding; the human pair is ortholog-inferred, mouse is not [PMID:33790026].","localisation_and_range":"TSKU flagged secreted; TSK acts in cerebrospinal fluid and at the ventricular surface [PMID:33790026].","caveats":"The binding sentence is from a browser read and the curator marked it unverifiable pending spot-check; the abstract does not mention Fzd3. Paralog Fzd4 evidence is separate.","key_references":[{"PMID":"33790026","why":"Fzd3-TSK binding, TSK role in SVZ and hydrocephalus"}],"covers":["LR003422","LR006623"]},"LR002027":{"pair":"TSLP -> CRLF2","headline":"TSLP binds CRLF2 as a heterodimer with IL7R (background statement); supported by GtoPdb, PDB and Reactome.","interaction_type":"direct binding","direction_and_effect":"Agonist: CRLF2 binds TSLP as a heterodimer with IL7R [PMID:22915648]; GtoPdb lists Agonist [DB:GtoPdb]. The paper's own results concern CRLF2 mutant signalling in B-ALL, not ligand binding.","molecular_requirements":"IL7R is a partner; CRLF2 signalling needs the box1 domain and tryptophan W286, and Y368 for the CRLF2 F232C mutant [PMID:22915648]. PDB structures show TSLP, TSLPR and IL-7Ralpha complexes [DB:PDB 5J11].","affinity_potency":[],"species_and_systems":"B-cell acute lymphoblastic leukemia cell models [PMID:22915648]; structures [DB:PDB 5J11].","localisation_and_range":"TSLP is flagged secreted, CRLF2 transmembrane [flag]; TSLP is a secreted cytokine.","caveats":"The curated sentence is a background statement of the paper, not a new result. Abstract-level evidence; one further paper was review_only. CRLF2 alone binding strength not reported in our evidence.","key_references":[{"PMID":"22915648","why":"CRLF2 signalling requirements in B-ALL; TSLP heterodimer receptor stated"}],"covers":["LR002027","LR005355"]},"LR001523":{"pair":"UCN -> CRHR2","headline":"Urocortin 1 binds CRF2 receptor with high affinity as an agonist in several abstract-level binding studies.","interaction_type":"direct binding","direction_and_effect":"Agonist: human urocortin binds CRF receptor types 1, 2 alpha and 2 beta and stimulates cAMP in transfected cells [PMID:8612563]; GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the CRF2alpha and CRF2beta receptor variants being tested separately [PMID:9423932]. Non-peptide CRF antagonists had no measurable affinity at CRF2 receptors [PMID:9423932].","affinity_potency":[{"value":"Kd 0.18-0.31 nM","assay":"[3H]-rat urocortin binding, range reported across the recombinant receptors and cerebellum","system":"stably transfected cell homogenates","cite":"PMID:9423932"},{"value":"Ki 1 to 2 nM","assay":"competition with 125I-labelled radioligands, reported for all receptors","system":"CHO cells overexpressing CRF-R1 or CRF-R2","cite":"PMID:9918582"},{"value":"pKd 8.6 to 9.4","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:11123370"}],"species_and_systems":"Human CRF2alpha [PMID:11123370], rat CRF2alpha and CRF2beta recombinant receptors with rat urocortin [PMID:9423932], CHO cells (species unspecified) [PMID:9918582]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"All papers read as abstracts only. Potency rank order at CRF2 receptors was urocortin > sauvagine > urotensin 1 > CRF [PMID:9423932]; urocortin also binds CRF1, so it is not subtype-selective [PMID:8612563].","key_references":[{"PMID":"8612563","why":"Human urocortin binds CRF2 alpha/beta and raises cAMP"},{"PMID":"9423932","why":"Kd and rank order at CRF2 receptors"},{"PMID":"9918582","why":"Ki of 1 to 2 nM in CHO cells"}],"covers":["LR001523","LR004913"]},"LR003431":{"pair":"UNC5A -> FLRT3","headline":"Extracellular binding of UNC5A and FLRT3 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5A is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5A stripes gave no attractive or repulsive neuronal response (n=257/257, 100% permissive) [PMID:26633812]. UniProt lists the extracellular-domain interaction, partly by similarity [DB:UniProt].","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003431","LR006632"]},"LR003440":{"pair":"UNC5D -> FLRT2","headline":"UNC5D-FLRT2 is well supported by binding and by repulsive guidance of cortical neurons, in mouse systems.","interaction_type":"direct binding","direction_and_effect":"Unc5D binds specifically to FLRT2; shed FLRT2/3 ectodomains act as repulsive guidance molecules for axons and somata of Unc5-positive neurons [PMID:21673655]. Deleting FLRT2 or Unc5D makes a subset of SVZ-derived neurons migrate early to the cortical plate, and Unc5D overexpression has the opposite effect [PMID:21673655]. A second paper found FLRT2-Unc5D binding in an ELISA-based screen (mean Abs650nm value = 2.14 for all FLRT x Unc5 pairs) [PMID:26633812]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"The shed ectodomain of FLRT2 is the active form [PMID:21673655]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cortex in vivo (abstract-level) and mouse recombinant proteins in vitro [PMID:21673655, PMID:26633812]; the human pair is ortholog-inferred.","localisation_and_range":"FLRT2 ectodomains are shed from neurons and act at a distance as chemorepellents [PMID:21673655]; Unc5D is a membrane receptor [flag].","caveats":"The 2011 paper was read as abstract only. No Kd or other affinity is given.","key_references":[{"PMID":"21673655","why":"Unc5D binds FLRT2; shed FLRT2 repels Unc5D neurons in cortex"},{"PMID":"26633812","why":"ELISA and titration binding of all FLRT x Unc5 pairs"}],"covers":["LR003440","LR006641"]},"LR001532":{"pair":"VCAM1 -> ITGB7","headline":"alpha4beta7 can bind VCAM-1 given strong activation; five confirmed rows but one paper also recorded as pair absent.","interaction_type":"conflicting","direction_and_effect":"alpha4beta7 binds VCAM-1, but this requires greater integrin activation than binding to MAdCAM-1 [PMID:7687523]. CXCL10 primes alpha4beta7 for VCAM-1 while CCL25 lowers it [PMID:29789438]. Phorbol ester or TCR-CD3 activation caused beta7 integrin binding to VCAM-1 [PMID:12682249].","molecular_requirements":"Receptor is alpha4beta7; the alpha4 blocking antibody HP2/1 abolished adhesion [PMID:29789438].","affinity_potency":[],"species_and_systems":"Lymphocytes and TK1/38C13 cells, species unspecified in the curated row [PMID:7687523]; human lymphocyte lines [PMID:29789438]; activated T cells [PMID:12682249]. Human and mouse rows are not ortholog-inferred.","localisation_and_range":"Cell-surface adhesion; VCAM1 flagged secreted and transmembrane [flag].","caveats":"Same paper PMID 7687523 is both confirmed and a propagated pair_absent row. VCAM-1 binding is conditional on activation or chemokine. Mostly abstract-level; chain-only entry.","key_references":[{"PMID":"29789438","why":"chemokine-dependent alpha4beta7 switch toward VCAM-1"},{"PMID":"7687523","why":"alpha4beta7 binds VCAM-1 only with strong activation"},{"PMID":"12682249","why":"T cell activation induces beta7 binding to VCAM-1"}],"covers":["LR001532","LR004921"]},"LR001541":{"pair":"VEGFA -> KDR","headline":"VEGFA binds and activates KDR (VEGFR2); well supported by binding, affinity and functional papers.","interaction_type":"direct binding","direction_and_effect":"KDR expressed in CMT-3 cells gives saturable 125I-VEGF binding [PMID:1417831]; mouse Flk-1 binds VEGF and mediates VEGF-dependent Ca2+ efflux [PMID:8356051]. Alanine-scanning shows VEGF Arg82, Lys84 and His86 are critical for KDR binding, and KDR rather than FLT-1 drives endothelial mitogenesis [PMID:8621427]. Stimulatory (agonist) [DB:GtoPdb].","molecular_requirements":"Coreceptors modify binding: neuropilin-1 crosslinks to 125I-VEGF165 with VEGFR2 on HUVECs [PMID:17318185]; SCUBE2 forms a complex with VEGF and VEGFR2 and facilitates binding [PMID:27834687]. PGI2 synthesis in bovine cells needs a VEGFR-1/VEGFR-2 heterodimer [PMID:15637071]. VEGFR2 monomers and dimers bind VEGF differently, with a 45-fold difference in affinity [PMID:31023826].","affinity_potency":[{"value":"KD = 75 pM","assay":"saturable 125I-VEGF binding","system":"KDR-transfected CMT-3 cells","cite":"PMID:1417831"}],"species_and_systems":"Human VEGF with human KDR in most papers; mouse Flk-1 in Xenopus oocytes [PMID:8356051]; bovine aortic endothelial cells [PMID:15637071]. The mouse pair is ortholog-inferred.","localisation_and_range":"VEGFA flagged secreted, KDR transmembrane [flag].","caveats":"Most papers read as abstract only. Several confirmations are indirect (coreceptor or heterodimer studies) rather than pure KDR binding. Affinity depends on the receptor association state [PMID:31023826].","key_references":[{"PMID":"1417831","why":"KDR expression gives high-affinity VEGF binding, KD = 75 pM"},{"PMID":"31023826","why":"Binding affinities of VEGF for VEGFR2 monomer versus dimer"},{"PMID":"8621427","why":"VEGF residues for KDR binding"}],"covers":["LR001541","LR004930"]},"LR001550":{"pair":"VEGFC -> NRP2","headline":"VEGF-C binds NRP2 through a processing-gated C-terminal motif, with structure and cell data showing a co-receptor role.","interaction_type":"direct binding","direction_and_effect":"Processed VEGF-C C-terminus bound NRP2 b1b2 and a crystal structure shows a cryptic motif released by proteolysis engages the b1 domain [PMID:25752543]. VEGF-C and VEGF-D interact with NP2 [PMID:16816121]; VEGF-A and VEGF-C induce NRP2 interaction with VEGFR-2, enhancing VEGFR-2 phosphorylation and VEGF-C-induced survival and migration [PMID:16621967].","molecular_requirements":"Binding needs C-terminal proteolytic maturation; unprocessed peptide showed no effect [PMID:25752543]. VEGF-C binds NP2 in a heparin-independent manner and NP2 coprecipitates with VEGFR-3, forming part of a signalling complex [PMID:16816121]. NRP2 acts as a co-receptor with VEGFR-2 [PMID:16621967].","affinity_potency":[{"value":"Kd = 199 \u03bcM \u00b1 71 \u03bcM","assay":"saturable binding of processed VEGF-C C-terminal peptide to Nrp2 b1b2","system":"purified peptide and Nrp2 domains","cite":"PMID:25752543"}],"species_and_systems":"Human ligand and receptor throughout; recombinant domains and cultured endothelial cells [PMID:25752543] [PMID:16816121] [PMID:16621967]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted [flag]. A secreted splice form s9Nrp2 is described as a decoy inhibitor in the structural paper's notes [PMID:25752543].","caveats":"The 199 \u03bcM Kd is for a short peptide and therefore weak; full-length affinity is not reported. A PDB structure exists [DB:PDB 6TJT]. One pending row not shown. Papers read as abstracts, with full-text excerpts for the structural paper.","key_references":[{"PMID":"25752543","why":"structure of processed VEGF-C bound to Nrp2 b1"},{"PMID":"16816121","why":"VEGF-C binding to NP2 and VEGFR-3 complex"},{"PMID":"16621967","why":"NRP2 co-receptor role for VEGF-C"}],"covers":["LR001550","LR004939"]},"LR004133":{"pair":"VEGFD -> ITGA9","headline":"VEGF-D binds integrin alpha9beta1 in a solid-phase assay; single paper and heterodimer-level evidence.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-D bound purified alpha9beta1 integrin dose- and cation-dependently; alpha9beta1-expressing cells adhered and migrated on VEGF-D, blocked by a function-blocking antibody [PMID:15590642].","molecular_requirements":"The evidence concerns the alpha9beta1 heterodimer, not ITGA9 alone [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant protein and cells including mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells [PMID:15590642]. Both interactions are ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Single abstract-read paper; no affinity; no database records in this dossier.","key_references":[{"PMID":"15590642","why":"VEGF-D binds alpha9beta1 integrin"}],"covers":["LR000649","LR004133"]},"LR000650":{"pair":"VEGFD -> ITGB1","headline":"VEGF-D binds alpha9beta1 integrin; ITGB1 credited only as a chain of the heterodimer from one paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-D bound purified alpha9beta1 integrin and adhesion/migration on VEGF-D was alpha9beta1-dependent [PMID:15590642].","molecular_requirements":"ITGB1 alone not tested; alpha9 chain (ITGA9) is needed by the evidence [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant protein plus cell assays; cells include mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells [PMID:15590642]. Interactions are ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Chain-only evidence; beta1 pairs with many alpha chains. Single abstract-read paper; no affinity.","key_references":[{"PMID":"15590642","why":"VEGF-D binds alpha9beta1 integrin"}],"covers":["LR000650","LR004134"]},"LR008111":{"pair":"WNT10A -> FZD1:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD1:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: abstract_insufficient 1.","key_references":[],"covers":["LR008111"]},"LR011243":{"pair":"WNT10A -> FZD6:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD6:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: pending 3.","key_references":[],"covers":["LR011243"]},"LR002036":{"pair":"WNT10A -> FZD8","headline":"Functional evidence only: WNT10A induced reporter signalling via FZD8 in a human cell FZD-knockout rescue panel; no binding measured.","interaction_type":"functional only","direction_and_effect":"In HEK293 reporter cells with multiplex FZD knockouts, Wnt10a induced signalling via FZD5 and FZD8, i.e. an activating, canonical-signalling effect [PMID:28733458].","molecular_requirements":"Rescue was with individual FZDs, so FZD8 alone appears sufficient to restore signalling; LRP co-receptor requirement is not reported in our evidence. FZD5 also responded to Wnt10a, so the receptor is not exclusive [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human cells (HEK293 reporter, FZD knockout panel, curator-recorded human ligand and receptor); a human pair, mouse entry is ortholog-inferred [PMID:28733458].","localisation_and_range":"Ligand flagged secreted, receptor not secreted [flag]; the assay used cells expressing both, so range is not tested.","caveats":"Signalling readout in a genetic rescue assay, not physical binding. The paper notes FZD5 and FZD8 are the most promiscuous receptors [PMID:28733458]. Full text was read.","key_references":[{"PMID":"28733458","why":"FZD rescue map: Wnt10a signals via FZD5 and FZD8 in HEK293 reporter cells"}],"covers":["LR002036","LR005362"]},"LR010811":{"pair":"WNT10B -> FZD5:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268]. UniProt states FZD5 in vitro activates WNT10B signalling (by similarity) [DB:UniProt Q13467].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only. A UniProt record states FZD5 activates WNT10B signalling 'By similarity' [DB:UniProt], so that is inferred, not direct.","key_references":[],"covers":["LR010811"]},"LR011261":{"pair":"WNT2 -> FZD5:LRP5","headline":"WNT2 controls hepatocyte metabolism through FZD5 in humanized mouse liver; LRP5 was not tested.","interaction_type":"functional only","direction_and_effect":"WNT2 secreted by sinusoidal endothelial cells controls cholesterol uptake and bile acid conjugation in hepatocytes through receptor FZD5 [PMID:37562401].","molecular_requirements":"FZD5 named as receptor; LRP5 contribution is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Humanized mouse liver with human hepatocytes and non-parenchymal cells, abstract only [PMID:37562401]; the authors call the interaction species-specific.","localisation_and_range":"Paracrine from endothelial cells to hepatocytes; WNT2 flagged secreted [flag].","caveats":"No binding assay; LRP5 unsupported. One review-only and one abstract_insufficient row.","key_references":[{"PMID":"37562401","why":"Endothelial WNT2 acts via FZD5 on human hepatocytes in vivo"}],"covers":["LR011261"]},"LR003503":{"pair":"WNT4 -> LRP6","headline":"One co-IP result in mouse cells shows a Wnt4-LRP6 complex; other papers were abstract-insufficient.","interaction_type":"direct binding","direction_and_effect":"Co-IP revealed a Wnt4-LRP6 binding complex [PMID:31216173].","molecular_requirements":"Wnt4-Fzd1/Fzd2/Fzd6 complexes and LRP-Fzd complexes were also found, so a Frizzled may bridge the interaction [PMID:31216173].","affinity_potency":[],"species_and_systems":"Co-IP in MC3T3 (mouse) cells, per curator note [PMID:31216173]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and LRP6 flagged transmembrane [flag].","caveats":"Single browser-read result, not spot-checked; co-IP does not show direct binding. No affinity in our evidence.","key_references":[{"PMID":"31216173","why":"co-IP of Wnt4 with LRP in MC3T3 cells"}],"covers":["LR003503","LR006703"]},"LR008120":{"pair":"WNT5A -> FZD1:LRP5","headline":"No paper-level evidence for WNT5A with the FZD1:LRP5 complex; only database records on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no confirmed paper for this complex. BioGRID records WNT5A - FZD1 Affinity Capture-Western [DB:BioGRID] (PMID 10557084); UniProt notes FZD1 is apparently not activated by WNT5A [DB:UniProt].","molecular_requirements":"The complex combines FZD1 and LRP5; the database records concern individual chains, not the assembled complex. ","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone. Curators judged only review-only or abstract-insufficient papers, with none confirmed. A single-chain record does not show that both subunits are needed.","key_references":[],"covers":["LR008120"]},"LR002045":{"pair":"WNT5A -> FZD3","headline":"Wnt5a binds the FZD3 CRD in BLI and is competed by a nanobody; the paper is mainly structural and does not give Wnt5a affinity.","interaction_type":"direct binding","direction_and_effect":"A nanobody (Nb8) bound to the FZD3 CRD reduced Wnt5a binding, indicating competition for FZD3; Nb8 fused to DKK1 C-terminal domain acted as a FZD3-specific Wnt surrogate activating beta-catenin signalling [PMID:39174501]. Wnt5a itself is described as binding immobilized FZD3 CRD in the BLI sensorgrams [PMID:39174501].","molecular_requirements":"The FZD3 CRD lipid-binding groove is the site; Nb8 would impede access of the Wnt palmitoleic moiety [PMID:39174501]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human FZD CRDs, biolayer interferometry and crystallography (Nb8 with FZD3 CRD, 1.8 \u00c5) [PMID:39174501].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The direct Wnt5a-FZD3 evidence is a competition assay with a nanobody; no Wnt5a affinity is reported in our evidence. The curator read only the abstract; the excerpts supply the BLI details. The surrogate activates signalling independently of native Wnt5a.","key_references":[{"PMID":"39174501","why":"FZD3 CRD-Nb8 structure; Nb8 competes with Wnt5a for FZD3"}],"covers":["LR002045","LR005371"]},"LR001604":{"pair":"WNT5A -> FZD5","headline":"Wnt5a binds the FZD5 CRD and acts through FZD5 in several systems; well supported, with agonist activity.","interaction_type":"direct binding","direction_and_effect":"hFz5 was identified as a Wnt-5A receptor: Wnt-5A induced axis duplication in Xenopus embryos in the presence of hFz5 [PMID:9054360]. FZD5 silencing reduced WNT5A binding to endometrial stem-like cells and decreased TCF/LEF activity and active beta-catenin [PMID:35295855]. Fzd5 synergized with Wnt5a in Xenopus axis induction [PMID:11092808].","molecular_requirements":"The FZD5 amino-terminal ectodomain antagonized Wnt-5A/hFz5 signalling [PMID:9054360]. LRP5 is expressed in the same cells but its role is not reported for this pair here [PMID:35295855].","affinity_potency":[{"value":"KD = 5\u201322 nm","assay":"Bio-layer interferometry, WNT-5A binding to FZD5 CRD-Fc","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins for BLI [PMID:25605717]; Xenopus embryos with human or mouse reagents [PMID:9054360][PMID:11092808]; human endometrial cells [PMID:35295855].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Three of four papers were read as abstract only; the BLI quote is from a browser read and unverified [PMID:25605717]. The Xenopus work is functional synergy rather than binding [PMID:11092808]. WNT5A is often non-canonical, yet FZD5 mediated beta-catenin activity in endometrial cells [PMID:35295855].","key_references":[{"PMID":"25605717","why":"BLI KD of WNT-5A for FZD5 CRD"},{"PMID":"9054360","why":"hFz5 identified as a Wnt-5A receptor in Xenopus"},{"PMID":"35295855","why":"FZD5 silencing reduces WNT5A binding and signalling"}],"covers":["LR001604","LR004993"]},"LR003512":{"pair":"WNT5B -> FZD1","headline":"WNT5B binds the FZD1 CRD only weakly in one binding study; UniProt says FZD1 is apparently not activated by WNT5B.","interaction_type":"conflicting","direction_and_effect":"Binding only: WNT-5B showed weak binding (KD > 40 nm) to FZD CRDs including FZD1 per the paper's sentence [PMID:25605717]. UniProt says FZD1 is apparently not activated by WNT5B [DB:UniProt].","molecular_requirements":"CRD only was tested; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read. The sentence groups FZD1/2/4 for WNT-5A; WNT-5B is described as weak to 'these' CRDs.","key_references":[{"PMID":"25605717","why":"BLI mapping of WNT-FZD CRD binding"}],"covers":["LR003512","LR006712"]},"LR001613":{"pair":"WNT7A -> FZD10","headline":"Co-immunoprecipitation and functional data in one endometrial cancer cell abstract; Fzd10 mediates a noncanonical JNK response.","interaction_type":"direct binding","direction_and_effect":"Wnt7a coimmunoprecipitates with Fzd10 (and Fzd5, SFRP4) in Ishikawa cells; Wnt7a signalling through Fzd10 induced a noncanonical JNK-responsive pathway, an agonist effect [PMID:18567805]. SFRP4 suppresses Wnt7a signalling [PMID:18567805].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Ishikawa endometrial cancer cells [PMID:18567805]; the mouse pair is projected from human evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; autocrine and paracrine action reported [PMID:18567805].","caveats":"Abstract only. Co-IP does not prove direct binding.","key_references":[{"PMID":"18567805","why":"Wnt7a co-IPs with Fzd10 and signals via JNK in Ishikawa cells"}],"covers":["LR001613","LR005002"]},"LR003521":{"pair":"WNT7A -> FZD6","headline":"WNT-7A changes FZD6 surface mobility in one full-text FRAP study; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-7A, among others, increased the mobile fraction of FZD6-GFP, taken as acting on this receptor; WNT-5B and WNT-11 had no effect [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility relate to putative precoupling of Gi/o proteins [PMID:24873871].","affinity_potency":[],"species_and_systems":"Human FZD6-GFP in HEK293T/17 cells; the species of the recombinant WNT proteins is not confirmed in the text [PMID:24873871].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; acts on the cell-surface receptor.","caveats":"Receptor mobility is not binding; one paper.","key_references":[{"PMID":"24873871","why":"FRAP shows WNT-7A affects FZD6 mobility"}],"covers":["LR003521","LR006721"]},"LR005006":{"pair":"WNT7B -> FZD1","headline":"WNT7B binds FZD1 on the cell surface in an abstract-level study, but UniProt says FZD1 is apparently not activated by WNT7B.","interaction_type":"conflicting","direction_and_effect":"Wnt7b bound Fzd1 on the cell surface and cooperatively activated canonical Wnt signalling with it when LRP5 was present [PMID:15923619]. UniProt for FZD1 says it is apparently not activated by WNT7A or WNT7B [DB:UniProt].","molecular_requirements":"LRP5 co-expression is needed for cooperative canonical activation [PMID:15923619].","affinity_potency":[],"species_and_systems":"Human per curator fields, cell transfection; mouse pair is listed as not ortholog-inferred [PMID:15923619].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Conflicting UniProt statement on activation [DB:UniProt]. Fzd1 is mostly in lung mesenchyme, unlike Fzd10 in epithelium [PMID:15923619].","key_references":[{"PMID":"15923619","why":"Wnt7b binds Fzd1 and Fzd10 on the cell surface"}],"covers":["LR001617","LR005006"]},"LR003530":{"pair":"WNT7B -> RECK","headline":"WNT7B directly binds RECK, a GPI-anchored receptor that stabilises active WNT7; strong direct-binding evidence.","interaction_type":"direct binding","direction_and_effect":"WNT7A and WNT7B, but not WNT3A, directly bind purified soluble RECK, cell-surface RECK and the GPR124:RECK complex [PMID:30304675]. RECK acts as a selective WNT7 receptor mediating GPR124/FZD/LRP-dependent canonical signalling (agonist) [PMID:30304675]. UniProt notes interaction with RECK confers Wnt7 selectivity in brain endothelial cells [DB:UniProt].","molecular_requirements":"RECK works with GPR124, whose ectodomain mediates canonical signalling, plus FZD/LRP co-receptors [PMID:30304675]. WNT7B bound sRECK-Fc but not the VEGFR2 ECD-Fc negative control, and sRECK-Fc dose-dependently inhibited RECK/GPR124/WNT7B reporter activity [PMID:30304675]. 1:1 stoichiometry and stabilisation of monomeric active ligand were shown for WNT7A.","affinity_potency":[],"species_and_systems":"Human WNT constructs in HEK293 RECK-knockout cells; rat brain vessels used for GPR124-RECK association [PMID:30304675].","localisation_and_range":"RECK is GPI-anchored (cell surface); a soluble RECK also binds WNT7B. GPR124:RECK acted in cis (same cell), not trans [PMID:30304675].","caveats":"Abstract plus full-text excerpts. Stoichiometry and stabilisation data are for WNT7A, not WNT7B. The mouse pair is projected from human.","key_references":[{"PMID":"30304675","why":"WNT7A/B bind RECK directly; RECK-GPR124 signalling"}],"covers":["LR003530","LR006730"]},"LR002054":{"pair":"WNT8A -> FZD5","headline":"WNT8A induces signalling via FZD5 in a FZD-knockout reporter map; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 [PMID:28733458]. Wnt8a acts through a restricted set of FZD genes [PMID:28733458].","molecular_requirements":"FZD5 alone sufficed in the rescue setup; co-receptor need is not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293 cells with multiplex FZD CRISPR knockouts [PMID:28733458]; ligand and receptor species fields are not given in this record. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map in HEK293 cells; promiscuous FZD5/FZD8 (about 70% homology) may be redundant [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR002054","LR005380"]},"LR008102":{"pair":"WNT9A -> EGFR:FZD9:LRP6","headline":"WNT9A-FZD9 signalling requires LRP6 and EGFR in reporter assays; functional evidence from one full-text paper.","interaction_type":"functional only","direction_and_effect":"Wnt9a-Fzd9b signalling also required LRP6, consistent with a role upstream of beta-catenin [PMID:31110287].","molecular_requirements":"Wnt9a-Fzd9b signal was synergistically increased in cells co-transfected with Lrp6; LRP6-deficient HEK293T STF cells lost the signal, while a GSK3 inhibitor still stimulated STF activity [PMID:31110287]. EGFR is a required cofactor [PMID:31110287].","affinity_potency":[],"species_and_systems":"Zebrafish in vivo, human embryonic stem cells and HEK293T cells [PMID:31110287].","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter data; no binding data for the full EGFR:FZD9:LRP6 complex. The paper proposes the three are in proximity at the cell surface [PMID:31110287].","key_references":[{"PMID":"31110287","why":"LRP6 knockout and EGFR requirement for Wnt9a-Fzd9b signalling."}],"covers":["LR008102"]},"LR001622":{"pair":"ZG16B -> CXCR4","headline":"Weak support: PAUF co-immunoprecipitates with CXCR4 and TLR2 and appears to activate CXCR4 signalling, but direct CXCR4 binding is not shown.","interaction_type":"functional only","direction_and_effect":"PAUF (ZG16B) associated with the CXCR4-TLR2 complex in co-immunoprecipitation in HEK293T cells, and induced cAMP-mediated reporter activity that the CXCR4 antagonist AMD3100 abolished, which the authors read as PAUF being a potential CXCR4 activator that partially inhibits TLR2-induced NF-kB activation [PMID:20802527]. IntAct records an anti-tag co-immunoprecipitation [DB:IntAct].","molecular_requirements":"Association was seen with CXCR4 and TLR2 together; CXCR4 might act as a TLR2 co-receptor [PMID:20802527]. Whether CXCR4 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, tagged and overexpressed in HEK293T cells, with THP-1 cells for signalling [PMID:20802527].","localisation_and_range":"ZG16B (PAUF) is flagged secreted [flag] and the paper treats it as a soluble ligand acting on cell-surface receptors [PMID:20802527].","caveats":"Co-immunoprecipitation cannot separate direct CXCR4 binding from binding through TLR2, to which PAUF binds directly. The authors state the mechanism remains to be clarified [PMID:20802527].","key_references":[{"PMID":"20802527","why":"PAUF associates with CXCR4-TLR2 and signals via cAMP/PKA"}],"covers":["LR001622"]},"LR012161":{"pair":"ZNRF3 -> FZD8:LRP5","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD8 partner is named in the UniProt statement; LRP5 evidence is limited to the UniProt statement or absent [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012161"]},"LR001316":{"pair":"RSPO3 -> LGR4","headline":"R-spondins, including RSPO3, bind LGR4 and potentiate Wnt signalling; well supported, though papers are read as abstracts and are family-level.","interaction_type":"direct binding","direction_and_effect":"Agonist: LGR4 and LGR5 bind R-spondins with high affinity and mediate potentiation of Wnt/beta-catenin signalling by enhancing Wnt-induced LRP6 phosphorylation [PMID:21693646]. R-spondins bind LGR4 and LGR5 by their Furin domains [PMID:21909076].","molecular_requirements":"LGR4 associates with the Frizzled/Lrp Wnt receptor complex [PMID:21727895]. Neither receptor couples to heterotrimeric G proteins or beta-arrestin when stimulated [PMID:21693646]. RSPO2 can also act through RNF43 and ZNRF3 independently of LGR4/5/6 [PMID:29769720].","affinity_potency":[],"species_and_systems":"Human and mouse pairs, neither ortholog-inferred. Mammalian cells and Xenopus embryos [PMID:21909076]; mouse gut deletion [PMID:21727895]. Species in the binding assays are partly unspecified.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"The papers address R-spondins as a family and not RSPO3 by name in the abstracts. All were read as abstracts only. Curator notes say the relationship is a modulator of Wnt, not an independent signalling axis [PMID:21693646]. Databases also list the pair [DB:GtoPdb][DB:BioGRID].","key_references":[{"PMID":"21693646","why":"R-spondins as ligands of LGR4 and LGR5"},{"PMID":"21909076","why":"R-spondin Furin domains bind LGR4/5"},{"PMID":"21727895","why":"Lgr4/5 associate with Frizzled/Lrp and mediate R-spondin signalling"}],"covers":["LR001316","LR004713"]},"LR001307":{"pair":"RSPO1 -> LGR4","headline":"Well supported: R-spondin 1 binds LGR4 and potentiates Wnt signalling through the Frizzled/LRP complex, with consistent database records.","interaction_type":"direct binding","direction_and_effect":"RSPOs act as agonist ligands of LGR4/LGR5 and potentiate Wnt/beta-catenin signalling by enhancing Wnt-induced LRP6 phosphorylation [PMID:21693646]. LGR4 removal abrogates RSPO1 enhancement of WNT3A signalling and re-expressing LGR4, -5 or -6 rescues it [PMID:21727895]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 associates with the Frizzled/Lrp Wnt receptor complex by mass spectrometry; it is facultative, not needed for WNT3A signalling alone [PMID:21727895]. Neither receptor couples to G proteins or beta-arrestin [PMID:21693646].","affinity_potency":[{"value":"pEC50 10.699999809265137","assay":"GtoPdb/curated affinity field, Wnt reporter assay","system":"intestinal crypts; Wnt reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human ligand and receptor in HEK293 cells [PMID:21727895]; mouse gut and crypt cultures with Lgr4/5 deletion [PMID:21727895].","localisation_and_range":"RSPO1 is flagged secreted and LGR4 transmembrane [flag], so paracrine action on LGR4-expressing cells.","caveats":"Both papers were read as abstracts. LGR4 acts as a modulator of Wnt signalling rather than an independent axis, so ligand-receptor scoring should consider Frizzled/LRP expression. Many database records (BioGRID, IntAct, Reactome, PDB) agree.","key_references":[{"PMID":"21693646","why":"R-spondins as ligands of LGR4 and LGR5"},{"PMID":"21727895","why":"RSPO1 binds LGR4; LGR4 needed for enhancement"}],"covers":["LR001307","LR004704"]}};